quests[25519] = { id = 25519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abkömmlinge von Tortolla", description = "Meine Kinder.\n\nSie liegen in der Tiefe.\n\nIn Schlick und Sand.\n\nDie anderen verderben sie.\n\nVerdunkeln ihre Seelen im Panzer.\n\nTötet die anderen.\n\nTötet die Verderber.\n\nRettet sie…", sourceObjective = "Tötet 6 Tiefe Verderber, die Tortollas Eier im Aschensee angreifen.", progress = "Meine Kinder.\nSagt mir, dass sie frei geboren werden…", completion = "{race}.\nIhr seid nicht wie die anderen.\n\nMutiger. Stärker.\nEin Teil von dieser Welt…\nNicht wie der Schatten, der zuvor zu mir kam.\n\nDanke.", sourceObjectiveStatus = "unverified-source-field" }
quests[25520] = { id = 25520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ahn erwacht", description = "Ich schlummerte im heiligen Schlick des Hyjal.\nIch schlief, bis die Welt aufbrach.\nAls die anderen kamen, war ich nicht vorbereitet.\n\nJetzt bin ich vorbereitet, {race}.\n\nMeine Kinder und ich. Unseren Zorn erregt man nicht leicht.\nDoch er ist endgültig.\n\nSagt denen, die Euch geschickt haben, dass wir für den Krieg bereit sind.\n\nDie anderen werden vom Berg verbannt.", sourceObjective = "Kehrt zu Erzdruide Hamuul Runentotem im Heiligtum von Malorne zurück.", completion = "{name}!\n\nIhr konntet das Vertrauen des Ahnen gewinnen?\n\nWunderbar! Wir sind einen Schritt näher daran, diesen Berg zurückzugewinnen…", sourceObjectiveStatus = "unverified-source-field" }
quests[25521] = { id = 25521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skorpidooh!", description = "Ihr müsst mir helfen, Ihr müsst, bitte! Ich kam mit Chelsea hierher, um ein bisschen Gold zu machen, ehrliche Arbeit, ein paar Sachen verkaufen. Und jetzt liegt sie auf dem Sterbebett! Sie hat Fieber, das selbst einen Schmied umhauen würde und sie halluziniert...\n\nIch glaube, sie wurde von einem der Skorpide hier gestochen! Ich hab das schon einmal gesehen, es ist kein schöner Anblick. Ich brauche ein paar Giftdrüsen, um ein Gegengift herzustellen, aber ich kann sie nicht alleine lassen!\n\nBitte, helft mir! Besorgt mir die Giftdrüsen!", sourceObjective = "Sammelt 6 Dünenscherenstachel von Dünenscherenpeitschern.", progress = "Habt Ihr sie? Oh, bitte...", completion = "Oh ich danke Euch! Vielen Dank! Ich kenne mich ein bisschen mit Alchemie aus, ich kann auch etwas. Hier wird...", sourceObjectiveStatus = "unverified-source-field" }
quests[25522] = { id = 25522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gargantapid", description = "Nein! Es hat nicht funktioniert! Ich weiß nicht, was ich tun soll, es sei denn...\n\nOh nein, es ist schlimmer, als ich dachte! Sie muss von dem gestochen worden sein, der sich in der Höhle versteckt hat. Ich habe ihn gesehen, als wir angekommen sind. Seine Klauen sind so groß wie Goblins. Sein Schwanz ist so groß wie ein Baum! Wir haben uns am Lagerfeuer leise über ihn unterhalten... wir haben ihn GARGANTAPID getauft!\n\n... hey, lacht Ihr etwa? Hört auf! Das ist alles ernst hier! Chelseas Leben ist in Gefahr! Bitte, ich werde dafür sorgen, dass es sich für Euch lohnt... bringt mir Gargantapids Giftdrüse!", sourceObjective = "Erhaltet Gargantapids Giftdrüse.", progress = "Ihr seid zurück! Habt Ihr sie?", completion = "Ich kann es kaum fassen! Ihr seid großartig! Hier, bitte, nehmt diese Belohnung, nehmt alles, was Ihr wollt. Ich muss Chelsea retten!", sourceObjectiveStatus = "unverified-source-field" }
quests[25523] = { id = 25523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fliegen in den Feuerlanden", description = "{name}, unser Feind nutzt diese Grotte in den Feuerlanden, um eine Invasion vorzubereiten. Wir werden hart zuschlagen, und zwar direkt dort, wo sie leben.\n\nAber zuerst müsst Ihr Euch Eure Flügel verdienen. In den Feuerlanden funktioniert das Fliegen nicht so wie in der Außenwelt. Das hat etwas mit der dichten, überhitzten Luft zu tun. Ihr braucht Übung!\n\nNehmt Euch eine Zwielichtfeuerlanze aus dem Regal hinter mir und schwingt Euch auf einen von Avianas Wächtern. Übt das Fliegen. Ihr müsst nur mit den Flügeln schlagen! Fliegt zu der Fahne, die ich auf dem Sims unter uns aufgestellt habe, und kehrt dann zurück.", sourceObjective = "Nehmt Euch eine Zwielichtfeuerlanze aus dem Regal hinter Farden und legt sie an. Steigt auf einen von Avianas Wächtern und fliegt zum Sims unter Euch. Drückt die Taste 'Flattern', damit Euer Reittier mit den Flügeln schlägt!", progress = "Habt Ihr Euch schon an diese Art des Fliegens gewöhnt?", completion = "Gut gemacht! Wie fühlt es sich an?\n\nEs ist eine echte Herausforderung, in dieser brennenden Ödnis die Flugkunst zu beherrschen, aber das ist der einzige Weg.\n\nIch hoffe, dass Ihr für die Schlacht bereit seid, {name}…", sourceObjectiveStatus = "unverified-source-field" }
quests[25524] = { id = 25524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Plumpsklo", description = "Hallo? Hallo! HILFE!\n\nIch bekomme fast keine Luft mehr! Ihr müsst mich hier rausholen!\n\n<Von innen erklingt ein Würgegeräusch.>\n\nEiner von diesen Schatzjägern der Südmeerfreibeuter hat bestimmt ein Brecheisen bei sich!", sourceObjective = "Erhaltet ein Piratenbrecheisen und versucht, die Tür des Plumpsklos unter Wasser aufzubrechen.", progress = "Oh, um des Lichtes Willen, habt Ihr das Brecheisen? Ich bin hier am Ertrinken!", completion = "Oh, was für ein Glück! Nur noch ein bisschen mehr drücken...", sourceObjectiveStatus = "unverified-source-field" }
quests[25525] = { id = 25525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die erste Welle", description = "Da kommen sie, {name}! Die Zwielichtritter auf ihren schwarzen, in den sengenden Schwefelbrutstätten der Feuerlande geschlüpften Bussarden. Der einzige Weg, sie zu besiegen, führt durch die Luft.\n\nSchwingt Euch erneut in den Himmel, {class}, und tötet sie.\n\nRammt Eure Lanze in die Ritter, um sie zu vernichten.\n\nHinfort! Fliegt, Ihr Narr. Fliegt!", sourceObjective = "Legt eine Zwielichtfeuerlanze an und fliegt auf Avianas Wächter. Tötet 10 Zwielichtritter, indem Ihr in sie hineinfliegt. Drückt die Taste 'Flattern', damit Euer Reittier mit den Flügeln schlägt!", completion = "Ein spektakulärer Flug, {name}! Ihre gequälten Schreie haben die Wände dieser lichtverlassenen Höhle zum Beben gebracht.\n\nDoch unsere Arbeit ist noch nicht zu Ende…", sourceObjectiveStatus = "unverified-source-field" }
quests[25526] = { id = 25526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Plumpsklo", description = "Hallo? Hallo! HILFE!\n\nIch bekomme fast keine Luft mehr! Ihr müsst mich hier rausholen!\n\n<Von innen erklingt ein Würgegeräusch.>\n\nEiner von diesen dreckigen Schatzjägern der Südmeerfreibeuter hat bestimmt ein Brecheisen bei sich!", sourceObjective = "Erhaltet ein Piratenbrecheisen und versucht, die Tür des Plumpsklos unter Wasser aufzubrechen.", progress = "Oh, um Goldes Willen, habt Ihr das Brecheisen? Ich bin hier am Ertrinken!", completion = "Oh, was für ein Glück! Nur noch ein bisschen mehr drücken...", sourceObjectiveStatus = "unverified-source-field" }
quests[25531] = { id = 25531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichtaufstand", description = "Ich bin Euch dankbar, dass Ihr mich befreit habt. Lasst uns den Aufruhr, den Ihr verursacht habt, nutzen und hier verschwinden.\n\nWir müssen uns beeilen, bevor die Kultisten uns auf die Schliche kommen.\n\nSucht mich wieder auf, wenn wir diesen Ort verlassen haben.", sourceObjective = "Sprecht mit Jarod Schattensang an den Toren von Sothann auf dem Hyjal.", completion = "Ihr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25532] = { id = 25532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbesserte Piratenpräzision", description = "Ich weiß nicht, ob es Euch aufgefallen ist, aber die Kanonenkugeln treffen. Es scheint, als würden die Piraten der Südmeerfreibeuter präziser werden... das Schiff brennt!\n\nIhr habt ja jetzt ein Rennboot. Sprecht mit Mazzer Schrottschrauber. \n\nLöscht die Feuer!", sourceObjective = "Holt von Mazzer Schrottschrauber ein Rennboot und benutzt die Frostkanone, um 15 Feuer zu löschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25533] = { id = 25533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbesserte Piratenpräzision", description = "Oh nein, {name} - die Kanonenkugeln treffen den Turbodampfer! Es scheint, als würden die Piraten der Südmeerfreibeuter präziser werden... das Schiff brennt!\n\nIhr habt ja jetzt ein Rennboot. Bitte, sprecht mit Griznak.\n\nLöscht die Feuer!", sourceObjective = "Holt von Griznak ein Rennboot und benutzt die Frostkanone, um 15 Feuer zu löschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25534] = { id = 25534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genug gebrüllt", description = "Vielleicht habt Ihr schon gesehen, dass an dem Schiff, das nördlich von hier angedockt hat, die Kanonen gefeuert werden. Es ist zwar recht lustig, den Gnomen dabei zuzuschauen, mit dem Gesicht voran in den Eisenregen zu rennen, aber leider machen meine Haudraufs das Gleiche, und das ist für meine Gemeinkosten kaum tragbar.\n\nKönntet Ihr versuchen, durch den Kanonenhagel durchzukommen, auf das Schiff zu gelangen und den Zuchtmeister zu töten, der die Kanoniere antreibt? Der Rest der Besatzung wird ein Haufen Trottel ohne Rückgrat sein; wenn er erledigt wurde, sollten sie kein Problem mehr darstellen.", sourceObjective = "Tötet den Zuchtmeister der Südmeerfreibeuter.", completion = "Gute Arbeit Kindchen. Knapp mit dem Leben davongekommen? Von einer Kanonenkugel gekratzt?\n\nNein? Gut, wir haben hier noch anderes zu erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25535] = { id = 25535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunger", description = "Die Armen. Sie sind am Verhungern.\n\nEs gibt viele Dinge, um die wir uns kümmern müssen, nicht zuletzt um die Naga. Doch zuerst müssen wir ihre Mägen füllen. Ich bin mir nicht sicher, was die Naga da oben in der Muschel ihnen gefüttert haben, aber sie sehen ganz schön mitgenommen aus.\n\nEine beträchtliche Zahl Überlebende hat es in die Glimmertiefenschlucht im Nordwesten geschafft. Schließt Euch ihnen an und helft ihnen. Mit ein bisschen Muschelfleisch bekommen wir die Überlebenden sicher schnell hochgepäppelt.", sourceObjective = "Sprecht mit Tauchbegleiter Birmingham in der Glimmertiefenschlucht.", completion = "Noch mehr Hilfe! Spitze! Wir können sie wirklich brauchen, so viel steht fest.", sourceObjectiveStatus = "unverified-source-field" }
quests[25536] = { id = 25536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein feuchter Händedruck", description = "Viele der Überlebenden haben sich in die Glimmertiefenschlucht aufgemacht, um beim Muscheltauchen zu helfen. Wir haben Berichte erhalten, laut denen dort unten eine Art Murlocstamm unsere Leute willkürlich angreift.\n\nDer Admiral muss hier bleiben, da sich immer mehr Männer aus der Schnecke melden. Ich kann ihn einfach nicht überreden, den Tauchern ein paar starke Arme zu Hilfe zu schicken. Wenn Ihr Lust habt, würden sie Eure Hilfe sicher dankend annehmen.\n\nKehrt zu mir zurück und gebt mir Bescheid, ob Ihr die Lage in den Griff bekommen habt.", sourceObjective = "Tötet 10 Gezeitenjäger der Glimmertiefen.", completion = "Vielen Dank, dass Ihr Euch darum gekümmert habt, {class}. Ich weiß, dass wir derzeit viele Sorgen haben, die uns den Kopf zerbrechen, aber die Sicherheit der Überlebenden ist für mich die oberste Priorität.", sourceObjectiveStatus = "unverified-source-field" }
quests[25537] = { id = 25537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kunst der Anlockung", description = "Ich habe eine Idee. Eine brillante Idee! Diese clownartigen Fische sind zu ihrer Verteidigung eine symbiotische Beziehung mit den Anemonen eingegangen. Nachdem ich den Versuch aufgegeben habe, die Taucher als Anemonen zu verkleiden, habe ich den chemischen Lockstoff entdeckt, der die Fische magisch anzieht.\n\nIch habe einen gyroskopischen Thermaseptextraktor mit hierher gebracht, um Proben zu nehmen. Benutzt ihn, um den chemischen Lockstoff aus verschiedenen Anemonen zu extrahieren, und bringt mir dann die Proben, damit ich ihn schnell künstlich herstellen und verteilen kann.\n\nSchnell! Die Brillanz wartet nicht!", sourceObjective = "Benutzt die Extraktionsapparatur für Anemonenchemikalien, um 8 chemische Anemonenproben von den roten Anemonen entlang der Wände der Glimmertiefenschlucht zu sammeln.", completion = "Hervorragend! Chemikalien in Hülle und Fülle!\n\nMein chemischer Direktsynthetisierer ist bereits getestet und vorbereitet. Die Mischung sollte in einem Wimpernschlag bereit zur Verteilung sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[25538] = { id = 25538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geruchsverschleierung", description = "Eine herausragende Arbeit, wenn ich mich einmal selbst loben darf. Bereit zur Verteilung.\n\nSprüht einfach die Muscheltaucher mit einem Hauch dieser Chemikalie ein und schon bald sollten sie einen schuppigen Begleiter haben, der sie beschützt. Wenn Ihr wünscht könnt Ihr Euch auch selbst einsprühen, um den gleichen Effekt zu erzielen.\n\nDa wir gerade von Wünschen sprechen: Ich empfehle Euch, den chemischen Lockstoff nur in sehr geringen Dosen zu verwenden. Wenn Ihr zu viel davon verwendet, kann das unerwünschte Folgen haben...\n\nZumindest unerwünscht für Euch. Wahrscheinlich jedoch sehr wünschenswert für die Fische.\n\nHinfort mit Euch!", sourceObjective = "Benutzt die Applikationsapparatur für Anemonenchemikalien an 8 Muscheltauchern.", completion = "Gut gemacht, mein dufter Handlanger! Ihr seid sowohl schnell als auch eifrig, wenn ich das so sagen darf. Mögen Eure weiteren Reisen vor Inspiration und Opulenz nur so überschäumen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25539] = { id = 25539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgetaucht", description = "Seid Ihr hier, um beim Muscheltauchen zu helfen?\n\nDann mal los! Hier sind fast überall Muscheln, die ertaucht werden wollen.", sourceObjective = "Sammelt 16 Glimmertiefenmuscheln.", progress = "Hat Eurer Ausflug Meeresfrüchte getragen?", completion = "In der Tat, sehr gut gemacht. Dieses beträchtlichen Berges an Muscheln braucht Ihr Euch wahrlich nicht zu schämen. Die Überlebenden in der Höhle werden Euch sicher dankbar sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25540] = { id = 25540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungrige Mäuler warten", description = "Wir haben einen riesen Haufen Muscheln gesammelt, der zurück in die Höhle geschleppt werden müsste, und ich habe einfach erwartet, dass Ihr das Schleppen übernehmt. Ihr habt Euch als gefährlich genug erwiesen, um genau <der/die> Richtige für diese Aufgabe zu sein.\n\nIch rechne nämlich damit, dass die Raubtiere auf dem Rückweg nicht ohne Kampf auf solch ein feines Mahl verzichten. Daher solltet Ihr so schnell wie möglich aufbrechen.\n\nVielen Dank für Eure Hilfe, Freund. Es war mir ein Vergnügen.", sourceObjective = "Bringt den großen Sack Muscheln zum Stillen Strand.", progress = "Ihr seht aus, als wärt Ihr aus einem bestimmten Grund zu uns zurückgekehrt. War Eure Reise erfolgreich?", completion = "Das ist wunderbar. Ich werde sie sofort kochen. Es ist beruhigend zu wissen, dass wir jetzt wenigstens keine Angst haben müssen, zu verhungern.\n\nIch könnte mir vorstellen, dass der Admiral mit vielen Aufgaben auf Euch wartet. Daher möchte ich Euch zumindest eine Weile lang nicht mehr aufhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25541] = { id = 25541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir füllen uns die Taschen", description = "Wir haben eigentlich alles geplündert, was nicht niet- und nagelfest ist, aber fertig sind wir noch nicht hier. Wenn wir dem Dampfdruckkartell schon die Arbeit abnehmen, dann müssen wir schon sicherstellen, dass wir hier auch gut verdienen.\n\nIch habe an den Piraten nur wenige Ohrringe gesehen - das heißt, dass sie ihr Gold am nächstsichersten Ort aufbewahren... in ihren Zähnen. Die Musketiere und Schläger der Südmeerfreibeuter südlich von hier haben in ihren Rängen mehr zu sagen. An ihnen wird man mehr dieser Verschönerungen finden. Bringt mir eine Handvoll Goldfüllungen.", sourceObjective = "Sammelt 20 Goldfüllungen von den Musketieren der Südmeerfreibeuter oder den Schlägern der Südmeerfreibeuter.", progress = "Jetzt werdet hier mal nicht zimperlich.", completion = "Toll! Gold ist Gold, egal aus welchem Mund, welcher Nase oder wo auch immer man es ziehen musste.\n\nUnd nach dem Schmelzen ist es auch alles ganz hygienisch. Zumindest hygienischer.", sourceObjectiveStatus = "unverified-source-field" }
quests[25542] = { id = 25542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wägen - äh, Boote - einkreisen", description = "Die Feuer haben wir unter Kontrolle, aber einige der Piraten der Südmeerfreibeuter machen sich bereit, um den Turbodampfer einzunehmen.\n\nEs ist an der Zeit, dass wir die Kanone der anderen Seite benutzen und sie versenken, bevor es zu spät ist!", sourceObjective = "Versenkt 15 Ruderboote der Südmeerfreibeuter.", completion = "Geschafft! Ihr habt es geschafft!\n\n<Jinky packt Euch und gibt Euch einen Schmatzer auf die Wange! Sie findet ihren Anstand wieder und streicht ihre Kleidung straff.>\n\nDanke, dass Ihr meinen Turbodampfer gerettet habt, Kapitän {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25543] = { id = 25543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wägen - äh, Boote - einkreisen", description = "Die Feuer haben wir unter Kontrolle, aber einige der Piraten der Südmeerfreibeuter machen sich bereit, um den Turbodampfer einzunehmen.\n\nEs ist an der Zeit, dass wir die Kanone der anderen Seite benutzen und sie versenken, bevor es zu spät ist!", sourceObjective = "Versenkt 15 Ruderboote der Südmeerfreibeuter.", completion = "Ihr habt meinen Turbodampfer gerettet!\n\n<Razzeric umarmt Euch kameradschaftlich!>\n\nIch kann gar nicht in Worte fassen, wie erleichtert ich bin, Kapitän {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25544] = { id = 25544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die zweite Welle", description = "Da habt Ihr in ein Wespennest gestochen, {name}. Uns fällt hier die Decke auf den Kopf! Und ihre stärksten Krieger schwingen sich auf Kreaturen, die von dieser Flammenwelt entstellt und verunstaltet wurden.\n\nKehrt noch einmal zurück und holt sie vom Himmel! Gebt jedoch auf die flammenden Brocken Acht.", sourceObjective = "Legt eine Zwielichtfeuerlanze an und fliegt Avianas Wächter. Tötet 10 Zwielichttjoster, indem Ihr in sie hineinfliegt. Drückt die Taste 'Flattern', damit Euer Reittier mit den Flügeln schlägt!", completion = "Bei Avianas Schwingen, Ihr wurdet zum Fliegen geboren, {name}!\n\nSchnell, lasst uns dorthin zurückkehren und erneut zuschlagen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25545] = { id = 25545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu den Waffen!", description = "In unserem Kampf gegen das Ertrinken waren meine Männer und ich gezwungen, unsere Waffen und einen Großteil unserer Rüstungen zurückzulassen.\n\nErunak sagt, dass er bald einen großangelegten Angriff der Naga erwartet und ich bin geneigt, ihm zu glauben.\n\nWenn wir eine Chance haben wollen, ihnen standzuhalten, müsst Ihr uns dabei helfen, unsere verlorene Ausrüstung zurückzuholen. Es sollte alles auf dem Meeresboden in der Nähe unserer Schiffswracks liegen.\n\nSchnell, {race}. Wir sind hier vollkommen schutzlos.", sourceObjective = "Sammelt 4 Speere von Sturmwind, 4 Brustplatten von Sturmwind, 4 Schilde von Sturmwind und 4 Helme von Sturmwind.\n\nIhr könnt die Ausrüstung auch von Strauchdieben der Gilblin sammeln.", progress = "Habt Ihr unsere Ausrüstung zurückgeholt, {race}?", completion = "Gut gemacht, {class}!\n\nDank Euch werden meine Männer sich gegen den Feind wehren können, wenn er angreift.", sourceObjectiveStatus = "unverified-source-field" }
quests[25546] = { id = 25546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siege gehen durch den Magen", description = "Wenn ich diese Männer für die Schlacht bereit machen möchte, brauche ich Eure Hilfe.\n\nJeder anständige Anführer weiß: Leerer Bauch reist und kämpft nicht gern. Kein Essen, kein Sieg.\n\nDiese Soldaten sind von den kürzlichen Strapazen vollkommen erschöpft. Sie brauchen etwas Nahrhaftes für den Fall, dass sie zu den Waffen greifen müssen.\n\nWo wir gerade von leeren Mägen sprechen, da draußen auf dem Meeresboden habe ich einige Krebse gesehen...", sourceObjective = "Sammelt 8 Stück saftiges Krebsfleisch von Spaltscherenhuschern.", progress = "Konntet Ihr etwas Essbares für meine Männer und mich finden, {class}?", completion = "Das sollte gegen die Erschöpfung helfen.\n\nUnd wieder sind wir Euch sehr dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[25547] = { id = 25547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu unseren eigenen Bedingungen", description = "Wir sind so bereit, wie man nur sein kann. Es bringt nichts, hier herumzusitzen und darauf zu warten, dass die Naga uns finden.\n\nIch werde mit den Männern sprechen und dann treffen wir unter unseren eigenen Bedingungen auf den Feind und lassen das Schicksal entscheiden, wie es ausgeht.", sourceObjective = "Sprecht mit Kapitän Taylor im Salzkutter.", completion = "Es ist keine Zeit, um noch zu den Truppen zu sprechen.\n\nAuch gut. Sie wissen, was zu tun ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25548] = { id = 25548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Feuerfürsten", description = "Ich wurde damit beauftragt, unsere militärischen Schachzüge gegen den Feind zu leiten. Eine demutsvolle Aufgabe, wenn man bedenkt, dass Halbgötter unter uns wandeln.\n\nIch muss Euch bitten, einige Überfälle auf Seiten des Feindes durchzuführen. Dabei ist es besonders wichtig, dass Ihr den Feind überrascht und ihn dezimiert, um unsere Hauptstreitmacht zu unterstützen.\n\nEuer erstes Ziel ist die Anhöhe des Aszendenten, wo die am besten ausgebildeten Anhänger des Schattenklans teilweise schon einen elementaren Zustand erreicht haben.", sourceObjective = "Tötet 4 Flammenaszendenten und 5 Zwielichtunterwerfer auf der Anhöhe des Aszendenten auf dem Hyjal.", completion = "Das habt Ihr gut gemacht, {name}. Ich habe ein neues Ziel für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25549] = { id = 25549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Sanktum der Propheten", description = "Die verrückten Propheten des Schattenhammers versammeln sich in einem Gebiet direkt nördlich des Zirkels des Aszendenten.\n\nMan sagt, dass sie ihre düsteren Visionen direkt von den Alten Göttern empfangen. Ganz gleich, ob das stimmt oder nicht, sie sind wichtige spirituelle Vordenker des Kults. Wenn wir das Sanktum der Propheten angreifen, können wir der Moral unserer Gegner einen schweren Schlag versetzen. Und falls wir Glück haben, lauft Ihr dort auch noch einem persönlichen Abgesandten des Feuerfürsten über den Weg.", sourceObjective = "Tötet 4 Zwielichtauguren, 4 Zwielichtanhänger und 1 Abgesandten der Flamme im Sanktum der Propheten.", completion = "Ihr beweist weiterhin Euren Heldenmut, {name}. Wenn Ihr so weitermacht, kann der Hyjal dieses Martyrium vielleicht doch überstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25550] = { id = 25550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magmamonarch", description = "Die Magmariesen, die Ragnaros dienen, stehen unter dem strengen Befehl ihres Königs. Wenn wir ihn ausschalten, werden die anderen sicher in Verwirrung geraten.\n\nOhne die Riesen fällt der Kampf bestimmt ausgeglichener aus. Vielleicht können wir sogar einen Vorteil erringen.\n\nDen Magmamonarchen zu erlegen wird sicher keine einfache Aufgabe. Benutzt diese Trommeln, um den großartigen Tortolla zu Hilfe zu rufen. Er kann König Lavatron bis in alle Ewigkeit in Schach halten. Doch ihn in Schach zu halten wird nicht reichen - und da kommt Ihr ins Spiel.", sourceObjective = "Benutzt die Trommeln des Schildkrötengottes, um für den Kampf gegen König Lavatron Unterstützung zu erhalten.", completion = "Ausgezeichnete Arbeit, {name}. Bald schon werden wir den Sieg auf dem Hyjal erringen.\n\nEs war mir eine Ehre, an Eurer Seite zu kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25551] = { id = 25551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feuerfürst", description = "Jetzt, da der Torwächter aus dem Weg geräumt ist, können die Wächter des Hyjal endlich auf die Sulfuronspitze gelangen.\n\nRagnaros hat keine andere Möglichkeit, als den Hauptweg in die Feuerlande selbst zu verteidigen.\n\nGeht durch das Portal des Schattenhammers im Sanktum der Propheten und trefft mich dort. Malfurion und Hamuul werden Euch dort ebenfalls helfen, während die anderen weiterhin den Feind draußen bekämpfen.", sourceObjective = "Geht durch das Portal im Sanktum der Propheten und helft Cenarius dabei, Ragnaros zu besiegen.", progress = "Ja, {name}?", completion = "Hyjal wurde gerettet, {name}. Und das nur dank Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25552] = { id = 25552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brut des Bösen", description = "Dieses Ei, das Ihr beschafft habt, bietet Anlass zur Beunruhigung, {name}. Die Zwielichtdrachen werden in der Regel aus gestohlenen Eiern anderer Drachenschwärme aufgezogen, die dann durch dunkle Magie verändert werden.\n\nDieses \"natürliche\" Ei ist der Beweis, dass eine ihrer Matriarchinnen inzwischen in der Lage ist, selbst Eier zu legen. Wir müssen sie vernichten, bevor ihre Brut sich ausbreiten kann.\n\nGeht zur Anhöhe des Aszendenten, wo diese entarteten Wesen gehalten werden sollen, und tötet einen der Jungdrachen. Wir werden seinen Schädel benutzen, um seine Mutter hervorzulocken.", sourceObjective = "Besorgt Euch den Schädel eines jungen Zwielichtdrachen auf der Anhöhe des Aszendenten auf dem Hyjal.", progress = "Ihr seid zurück, {name}.", completion = "Das habt Ihr gut gemacht. Wir werden das hier verwenden, um die Zwielichtmatriarchin aus ihrem Versteck zu locken.", sourceObjectiveStatus = "unverified-source-field" }
quests[25553] = { id = 25553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod der Brutmutter", description = "Wir haben die Futterstelle der Matriarchin südlich des Zirkels des Aszendenten ausfindig gemacht.\n\nSie wird sehr wütend sein, wenn sie merkt, dass sie einen ihrer Drachen verloren hat. Legt den Schädel in der Nähe des Aases ab, das sie verschlingt. Wenn sie ihn sieht, wird sie hervorkommen und versuchen, Rache zu nehmen.\n\nDann wartet eine nette Überraschung auf sie.", sourceObjective = "Legt den Zwielichtdrachenschädel an der Futterstelle südlich des Zirkels des Aszendenten ab und tötet Desperiona.", completion = "Das lief… noch besser als erwartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25554] = { id = 25554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Flamme", description = "Wenn wir Ragnaros wieder in die Feuerlande verbannen wollen, müssen wir uns Zugang zur Sulfuronspitze verschaffen.\n\nNur den vertrauenswürdigsten Mitgliedern des Schattenhammerkults werden diese wertvollen Informationen anvertraut.\n\nGeht und sucht auf der Anhöhe des Aszendenten nach Folianten. So übel diese Bücher auch sein mögen, wir können uns die Gelegenheit nicht entgehen lassen, mehr über die Schwächen unseres Feinds zu erfahren.", sourceObjective = "Beschafft Euch den Kodex des Aszendenten, die brennenden Litaneien und den Folianten der Flamme auf der Anhöhe des Aszendenten auf dem Hyjal.", progress = "Wart Ihr bei Eurer Aufgabe erfolgreich, {name}?", completion = "Diese grauenvollen Bücher sollte es besser gar nicht geben. Und doch sind die darin enthaltenen Informationen für uns von größter Wichtigkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25555] = { id = 25555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Torwächter", description = "Laut diesen Folianten dient einer von Ragnaros' mächtigsten Leutnants als einziger Torwächter der Sulfuronspitze.\n\nIhr werdet ihn nicht alleine besiegen können.\n\nBlast in dieses Horn, wenn Ihr Euch in den Kampf mit Azralon stürzt. Daraufhin werden alle in der Nähe befindlichen Streitkräfte zu Eurer Hilfe eilen.\n\nIhr müsst Euch beeilen, {name}. Der Feuerfürst kommt unseren Plänen sicher schnell auf die Schliche.", sourceObjective = "Benutzt das Horn des Cenarius, um Hilfe dabei zu erhalten, Azralon den Torwächter zu töten.", completion = "Es ist vollbracht. Nun bleibt Euch nur noch Eines zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[25556] = { id = 25556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Zul'Farrak", description = "Dieser üble Verräter... ich hätte es besser wissen müssen, als jemand seines Schlags zu vertrauen. Die Suche nach Sul'thraze hat mich geblendet.\n\nVergebt mir, {name}. Mazoga ist nach Zul'Farrak geflohen, der bevölkerungsreichste Teil der Länder der Sandwüter.\n\nIhr müsst ihm folgen, wenn Ihr das Schwert wirklich haben wollt. Geht nicht alleine; der Stamm der Sandwüter liegt hinter diesen Mauern auf der Lauer und sie werden Euch nicht willkommen heißen.\n\nIch werde hier bleiben. Ich muss die Suche nach der Klinge beenden. Solltet Ihr sie finden, so behaltet sie. Ich muss aufhören, bevor es mich verzehrt.", sourceObjective = "Findet Mazoga in Zul'Farrak.", completion = "<Mazogas Geist grinst Euch blutverschmiert an.>\n\nHey, wie geht's, Mann?", sourceObjectiveStatus = "unverified-source-field" }
quests[25558] = { id = 25558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles oder nichts", description = "Es ist soweit.\n\nHier werden wir uns zur Wehr setzen.\n\nWir müssen dieses Schiff bis zum letzten Atemzug verteidigen und dafür sorgen, dass diese Narren es sich zweimal überlegen, bevor sie sich ihm erneut nähern!\n\nMögen unsere Klingen ihnen Angst und Schrecken einjagen!", sourceObjective = "Helft Kapitän Taylor bei der Verteidigung des Salzkutters.", completion = "Der Irdene Ring hat meinen Notruf erhalten und Hilfe geschickt. Genau im rechten Moment, wie es scheint.\n\nHoffentlich können sie bald noch mehr senden. Wir sind nur eine Handvoll gegen viele.", sourceObjectiveStatus = "unverified-source-field" }
quests[25559] = { id = 25559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anspruch erheben", description = "Es scheint, als wären nicht nur wir an den Ruinen interessiert. Jetzt haben wir ausgerechnet Blutelfen bei unseren Ausgrabungsstellen.\n\nIch hatte damit gerechnet, dass sie in der Hitze und ohne ihre schicken Brunnen und weichen Kissen eingehen würden, aber bisher halten sie sich erstaunlich gut und versuchen, uns mit Gewalt aus den Südmondruinen zu vertreiben.\n\nEs ist an der Zeit, ein paar Schädel zu zertrümmern. Macht Euch auf und zeigt diesen Elfen, dass mit uns nicht zu scherzen ist!", sourceObjective = "Tötet 10 Ruinenjäger der Blutelfen.", completion = "Das wird es der Horde zweimal zeigen! Die Geschichte der Zwerge in Ruhe zu lassen und keine zerbrechlichen Sofaliebhaber in den Kampf zu schicken!", sourceObjectiveStatus = "unverified-source-field" }
quests[25560] = { id = 25560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eierwelle", description = "Ohne Verteidiger sind die Eier der Feuerlande angreifbar.\n\nSchwingt Euch erneut in die Lüfte und zerschmettert diese Eier! Rauscht einfach über sie hinüber, um sie zu zerbrechen. Sucht in jeder Ritze, Felsspalte und Seitenhöhle nach ihnen. Schnell!", sourceObjective = "Legt eine Zwielichtfeuerlanze an und fliegt Avianas Wächter. Zerstört 40 Eier der Feuerlande, indem Ihr über sie rauscht. Drückt die Taste 'Flattern', damit Euer Reittier mit den Flügeln schlägt!", completion = "Ein entscheidender Schlag!", sourceObjectiveStatus = "unverified-source-field" }
quests[25561] = { id = 25561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wägen - äh, Boote - einkreisen", description = "Die Feuer mögen unter Kontrolle sein, aber die Piraten der Südmeerfreibeuter machen sich trotzdem bereit, um den Turbodampfer einzunehmen!\n\n{name}, Ihr müsst zurück zu Mazzer Schrottschrauber und auf Euer Boot. Benutzt die Kanone, um sie zu versenken, bevor es zu spät ist!", sourceObjective = "Versenkt 15 Ruderboote der Südmeerfreibeuter.", sourceObjectiveStatus = "unverified-source-field" }
quests[25562] = { id = 25562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wägen - äh, Boote - einkreisen", description = "Die Feuer mögen unter Kontrolle sein, aber die Piraten der Südmeerfreibeuter machen sich trotzdem bereit, um den Turbodampfer einzunehmen!\n\n{name}, Ihr müsst zurück zu Griznak und auf Euer Boot. Benutzt die Kanone, um sie zu versenken, bevor es zu spät ist!", sourceObjective = "Versenkt 15 Ruderboote der Südmeerfreibeuter.", sourceObjectiveStatus = "unverified-source-field" }
quests[25564] = { id = 25564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfschwimmer von Sturmwind", description = "Ihr habt uns einen großen Dienst erwiesen, {class}, also werde ich Euch ein kleines Geheimnis verraten. Die Männer, die Ihr heute gerettet habt, gehören nicht zu den normalen Truppen von Sturmwind.\n\nWir sind Teil einer Sondertruppe von Elitesoldaten, die nicht nur hierher geschickt wurden, um uns gegen die Horde zu behaupten, sondern auch, um die massiven geologischen Störungen vom Meeresgrund in der Nähe zu untersuchen.\n\nIch erzähle Euch das, weil unsere streng geheime Ausrüstung unten in den Schiffswracks hier liegt.\n\nDiese Ausrüstung muss dringend geborgen werden!", sourceObjective = "Findet 6 Teile einer Kampfschwimmerausrüstung aus Sturmwind.", progress = "Konntet Ihr die Ausrüstung sicherstellen, {class}?", completion = "Es scheint alles in Ordnung zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25565] = { id = 25565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprachfragmente", description = "Wir haben den ersten richtig großen Fund seit Jahren hier in den Südmondruinen gemacht. Meine Jungs haben Steintafeln ausgegraben, auf denen alte Schriften zu finden sind. \n\nDie Glyphen auf den Tafeln sind uns gänzlich fremd, aber sie könnten mit den Wandschriften der Titanen zusammenhängen, die wir auch gefunden haben.\n\nStellt Euch nur vor, was dieser Fund bedeuten könnte!\n\nGeht für mich zu den Südmondruinen und helft uns, die Tafeln zu sammeln. Die anderen Jungs können nicht von dort weg, weil die Blutelfen sonst den Platz einnehmen werden!", sourceObjective = "Sammelt 5 uralte Hieroglyphen.", progress = "Habt Ihr die Tafeln?", completion = "Seht Euch das an... es ist kein Trollisch, kein Qiraji, nur ein Geheimnis, das gelüftet werden will.\n\nBei Euch sind die Tafeln vorab sicher. Es ist an der Zeit, in die Ruinen aufzubrechen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25566] = { id = 25566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geheimnisse Uldums", description = "Ich habe diese Ruinen jahrelang erforscht, um den Eingang zu finden. Wir haben sogar einen Teil der Tore eingerissen, nur um undurchdringbare Mauern darunter zu finden. Jetzt hat der Kataklysmus da drinnen wahrscheinlich alles komplett zerstört, aber in erster Linie hat er für uns etwas geöffnet, was uns verschlossen war!\n\nEuch soll diese Ehre zukommen, <Junge/Mädchen>: Begebt Euch nach Innen und seht, ob es noch Sachen gibt, die nicht zerstört wurden. Aber seid vorsichtig... wir können nicht wissen, wer oder was sich da drinnen noch befindet.", sourceObjective = "Sucht in der Vorkammer von Uldum nach einem unzerstörten Artefakt.", completion = "Die Truhe liegt ungestört hier und wurde seit Tausenden von Jahren nicht mehr geöffnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25574] = { id = 25574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flammen von oben", description = "Dank Eurer Arbeit haben wir grob die Richtung bestimmen können, aus der die Eindringlinge kommen.\n\nJetzt müssen wir nur noch ihr Lager außer Gefecht setzen und ihre Vorhaben hier auf dieser Seite von Nordrassil durchkreuzen.\n\nNehmt dieses Horn. Damit könnt Ihr einen unserer Smaragddrachen herbeirufen, der hinabstürzen und diesen Schattenhammerkultisten eine kleine Kostprobe der Flammen geben wird, die sie so wahnsinnig verehren.", sourceObjective = "Sucht das Lager des Schattenhammers nördlich von Nordrassil und benutzt Tholos Horn.", progress = "Ist es schon getan, {name}?", completion = "Ausgezeichnet, {name}. Das sollte die Angriffe ein für alle Mal aufhalten, sobald wir diesen Elementaren den Garaus gemacht haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25575] = { id = 25575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschmiedet aus Schatten und Flammen", description = "Die Waffen, die der Schattenhammer gegen uns einsetzt, werden von Schmiedemeister Pyrendius in diesen Hallen gefertigt. In der Hand seines Trägers gleitet das Metall durch Rüstungen wie durch Butter. Doch sobald ein anderer die Waffen in den Händen hält, wird der Stahl brüchig und zerbirst.\n\nUnd so sei es, {name}. Ich sehe lieber, wie diese verfluchten Waffen in tausend Stücke zerspringen, als dass sie unserem Feind geliefert werden.\n\nSucht nach den Waffenkisten des Schattenhammers in diesen Höhlen und zerschlagt sie!", sourceObjective = "Zerstört 10 Waffenkisten des Schattenhammers.", completion = "Gut, gut. Nichts gefällt mir besser als mit anzusehen, wie das Werk unserer Feinde vernichtet wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[25576] = { id = 25576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn des Wolfsahnen", description = "Da sind wir tief im Reich des Feuergottes und was finden wir? Ragnaros' kleine Marionetten, die sich abrackern, um seinen Willen zu erfüllen.\n\nDiese Arbeiter der Dunkeleisenzwerge vervollständigen und verpacken die Waffen, die der Schattenhammer bei seiner Eroberung des Hyjal einsetzen möchte. Es ist mir egal, ob sie aus freien Stücken hier sind oder ob sie einer Gehirnwäsche unterzogen und hierher verschleppt wurden. Sie sind und bleiben Feinde unseres geliebten Wolfsahnen und müssen dafür mit dem Leben bezahlen.", sourceObjective = "Tötet 12 Arbeiter der Dunkeleisenzwerge.", completion = "Tot? Gut. Sie haben ihr Schicksal selbst besiegelt, als sie sich mit Ragnaros und seinem Königreich des Feuers verbündet haben.\n\nLasst ihre Körper hier unten zu Asche zerfallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25577] = { id = 25577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerschmettert die Kerne", description = "Diese sengenden Wächter sind der Inbegriff der Blutrünstigkeit! Wir vernichten sie, doch schon ein paar Minuten später entflammen sie wieder aus der Asche.\n\nIch glaube, dass es eine Möglichkeit gibt, sie für immer zu zerstören. Doch dazu benötigen wir jemanden, der sich zu ihren vordersten Reihen durchschlägt.\n\n{name}, tötet die sengenden Wächter und bringt ihre Kerne zu den Ambossen in der Nähe. Zerschmettert sie auf den Ambossen des Schattenhammers und vernichtet sie für immer!", sourceObjective = "Besorgt 8 schwelende Kerne von sengenden Wächtern und zerschmettert sie dann auf den Ambossen des Schattenhammers.", completion = "Tolle Leistung!\n\nEs gab eine Zeit, in der Abenteurer diese Kerne sammelten, um daraus mittelmäßige feuerresistente Rüstungen herzustellen. Aber vorerst bin ich einfach nur froh, dass Ihr diese Ausgeburten ein für alle Mal vernichtet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25578] = { id = 25578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Nordrassil", description = "Ich bringe Fandral schnell zur Mondlichtung. Ich hoffe, dass ich bald zurück bin, um in der Schlacht helfen zu können.\n\nMeldet Euch in der Zwischenzeit bei Ysera und berichtet ihr von den aktuellen Entwicklungen.", sourceObjective = "Sprecht mit Ysera in Nordrassil auf dem Hyjal.", completion = "Alysras Entscheidung war vielleicht nicht die weiseste, {name}. Aber wir haben keine Zeit, um uns darüber Gedanken zu machen.\n\nIch bringe wichtige Erkenntnisse vom Smaragdgrünen Traum.", sourceObjectiveStatus = "unverified-source-field" }
quests[25579] = { id = 25579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überraschungsangriff", description = "Unsere Flucht aus der Muschel blieb sicher nicht unbemerkt, aber entweder wurden die Naga in den Ruinen nicht informiert oder sie sehen in uns keine Bedrohung. Ich habe nicht vor, diese Gelegenheit ungenutzt zu lassen. Wir werden jetzt gleich zuschlagen.\n\nIhr müsst Euch für mich in den unteren Bereich der Ruinen im Westen schleichen und so viele ihrer Patrouillen ausschalten, wie Ihr nur könnt. Wir können nicht riskieren, dass diese Patrouillen herausfinden, dass wir diese Höhle besetzt haben. Stellt sicher, dass keiner entkommt.", sourceObjective = "Tötet 10 Patrouillen der Azsh'ir.", completion = "Ausgezeichnete Arbeit, {class}.\n\nIch werde ein paar unserer eigenen Patrouillen losschicken um sicherzustellen, dass keine weiteren Naga in Sichtweite dieser Höhle gelangen. Wir sollten den Bereich noch in dieser Stunde gesichert haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25580] = { id = 25580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnelles Handeln", description = "Ich habe mir die Freiheit genommen, schon vorab die Lage auszuspähen. Die Naga wissen vielleicht nicht, wo wir sind, aber sie sind dennoch auf Eindringlinge vorbereitet.\n\nAbgesehen von ihren Patrouillen haben sie magische Überwachungsgeräte aufgestellt, die sie vor ungebetenen Gästen warnen. Zum Glück scheinen sie Quantität der Qualität vorzuziehen. Daher habt Ihr Zeit, sie zu zerstören, bevor jemand auf ihren Alarm reagieren kann.\n\nIch vertraue darauf, dass Ihr das erledigt, bevor unsere Soldaten eintreffen.", sourceObjective = "Zerstört 8 Überwacher der Azsh'ir.", completion = "Gut gemacht, {name}. Und genau rechtzeitig. Der Admiral hat gerade ein paar weitere Männer ausgesandt. Starke Kämpfer, zweifelsohne, aber ich bezweifle, dass sie so aufmerksam und geschickt sind wie Ihr.\n\nWir können uns glücklich schätzen, dass Ihr hier wart, als es bergab ging. Ich vermute stark, dass Ihr auch in Zukunft eine große Rolle spielen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25581] = { id = 25581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach der Vergangenheit", description = "Hört mal... {name}, richtig? Ich brauche Eure Hilfe. Ich weiß schon, fast alle in dieser Höhle denken, dass wir uns im Augenblick um nichts als unser eigenes Überleben kümmern sollten, aber ich bin nicht bereit, meine Ahnen so einfach außer Acht zu lassen.\n\nIch möchte nur, dass Ihr, wenn Ihr ohnehin schon in der Stadt seid, nach bedeutenden Objekten Ausschau haltet. Die Statuen interessieren mich ganz besonders.", sourceObjective = "Untersucht die 4 unversehrten Statuen in den Gärten von Vashj'ir.", completion = "Vielen Dank, dass Ihr diese Sache ernst genommen habt.\n\nDies ist einer der ersten unstreitigen Belege für andere Mitglieder der Familie Vashj. Sehr interessant. Und ich habe bis jetzt noch nie von den beiden Personen gehört, die Ihr erwähnt habt.\n\nSo viel von unserer Geschichte ging während der großen Zerschlagung verloren. Es ist ganz schön aufregend, eine Gelegenheit zu bekommen, einen Teil davon wieder aufzudecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[25582] = { id = 25582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein besserer Standort", description = "Diese Höhle ist unsere einzige Zuflucht. Es ist keine Hilfe unterwegs. Was immer geschieht, diese Höhle muss geschützt bleiben, sonst werden wir alle hier unten sterben.\n\nWir brauchen einen Vorposten, von dem aus wir die Angriffe starten können. Etwas, das wir verteidigen können.\n\nIm östlichen Teil der Ruinen auf der untersten Ebene solltet Ihr die nördlichen Gärten, die Passage unter der Hauptstruktur im Westen der Gärten und die Gebäudegruppe in der südöstlichen Ecke der Ruinen unter den Brücken erkunden.\n\nBringt mir alle Informationen, die Ihr finden könnt.", sourceObjective = "Späht den nördlichen Teil der Gärten von Quel'Dormir, den Tunnel unter den Ruinen im Westen der Gärten und die Gebäude im Süden der Gärten aus. Bleibt auf der untersten Ebene der Ruinen.", completion = "Das sind hilfreiche Informationen. Ihr habt scharfe Augen, {class}.\n\nEs klingt so, als ob das Gebäude unter der Terrasse am anderen Ende der Ruinen einen guten Vorposten abgeben könnte. Ich werde sofort ein paar Männer losschicken, die die Verteidigungsanlagen vorbereiten. Wir werden uns so schnell wie möglich da drüben neu aufstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25583] = { id = 25583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Schlachtfeld", description = "<Überall um Euch herum liegen Relikte der wilden Schlacht. Die Nagaskelette überraschen Euch nicht, aber die Waffen und Überreste ihrer offensichtlichen Gegner dafür viel mehr.>\n\n<Inmitten der Knochen entdeckt Ihr ein auffälliges Stück Metall, das aus einem der Schädel herausragt. Es ist schwer zu sagen, zu welcher Art Waffe das Metall einst gehört haben mag, aber es steht weit genug hervor, dass Ihr es als Beweis mitnehmen könnt.>\n\n<Irgendjemand in der Höhle ist an dieser Erkenntnis sicher interessiert.>", sourceObjective = "Bringt das Bruchstück zurück zum Stillen Strand.", progress = "Ja, {class}?", completion = "Wirklich interessant.\n\nDie Überreste, die Ihr beschreibt, klingen stark nach den Meervrykul, auf die wir in Nordend getroffen sind. Ich bezweifle stark, dass sie bereit sind, ein Bündnis mit uns einzugehen. Egal, wie gut die Gründe sein mögen. Dennoch kann diese Information uns bestimmt in der Zukunft helfen.\n\nWenn die Zeit es zulässt, werde ich weiter darüber nachdenken. Bis dahin vielen Dank, dass Ihr mich darauf aufmerksam gemacht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25584] = { id = 25584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr der Ahnen", description = "Es ist unerlässlich, dass wir jeden einzelnen Schrein der Ahnen zurückerobern, {name}.\n\nFolgt der Straße westlich des Saftgrünen Dickichts in die Wolfsschlucht.\n\nWir haben dort ein paar Agenten postiert. Helft ihnen, wo Ihr könnt, und macht Euch auf den Weg zum ersten Schrein.\n\nDer Wolfsgott trug bei den Elfen den Namen Goldrinn und bei den Orcs den Namen Lo'Gosh. Er wird uns im Kampf gegen den Feind ein mächtiger Verbündeter sein.", sourceObjective = "Sprecht mit Oomla Weißhorn in der Wolfsschlucht auf dem Hyjal.", completion = "Ysera hat Euch geschickt? Gut! Wir können hier dringend Hilfe brauchen.\n\nWir werden die Schreine der Ahnen nie zurückgewinnen können, solange der Schattenhammer die Straßen unter seiner Kontrolle hat. Irgendwie müssen wir gegen diese Flut ankämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25585] = { id = 25585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kanonen erstummen lassen", description = "Jetzt können wir uns endlich um die verfluchten Kanonen auf dem Felsen östlich von hier kümmern.\n\nNehmt doch bitte Euer Boot und fahrt damit zum Südmeerstützpunkt. Ihr werdet dort die Kanonen finden, die auf uns feuern.\n\nDie Piraten haben aber vom Ingenieurswesen keine Ahnung. Es sollte also recht einfach sein, die Kanonen zu verstopfen - dann sollten sie einfach explodieren.", sourceObjective = "Zerstört 8 Stützpunktkanonen.", completion = "Sie schießen immer noch, aber schon viel weniger! Yiiiippiiiiiiiiiiiiiiiiiiiiie!", sourceObjectiveStatus = "unverified-source-field" }
quests[25586] = { id = 25586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kanonen erstummen lassen", description = "Jetzt können wir uns endlich um die verfluchten Kanonen auf dem Felsen östlich von hier kümmern.\n\nNehmt doch bitte Euer Boot und fahrt damit zum Südmeerstützpunkt. Ihr werdet dort die Kanonen finden, die auf uns feuern.\n\nDie Piraten haben aber vom Ingenieurswesen keine Ahnung. Es sollte also recht einfach sein, die Kanonen zu verstopfen - dann sollten sie einfach explodieren.", sourceObjective = "Zerstört 8 Stützpunktkanonen.", completion = "Sie schießen immer noch, aber schon viel weniger! Yiiiippiiiiiiiiiiiiiiiiiiiiie!", sourceObjectiveStatus = "unverified-source-field" }
quests[25587] = { id = 25587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atempause", description = "Bitte, {race}! Ihr müsst mir helfen!\n\nDie Naga, Haie und dann dieses schreckliche Monster, das unser Schiff angegriffen hat... Ich bin nur knapp dem Tod entronnen.\n\nIch kann eine Höhle erkennen, die vielleicht sicher ist, aber ich wage mich nicht dorthin bis ich sicher weiß, dass dort Luft ist.\n\nKönntet Ihr nachschauen, ob alles in Ordnung ist?", sourceObjective = "Untersucht den Schmugglerschmiss im Tang'tharwald und signalisiert Adarrah dann, dass sie sicher hineingehen kann.", completion = "Ich kann Euch nicht genug danken, {race}.\n\nIch hoffe nur, dass dieser ganze Alptraum ein glückliches Ende findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25588] = { id = 25588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wenig Vergeltung", description = "Ich glaube, es ist an der Zeit, ein wenig Vergeltung zu üben. Das kann man mir kaum übel nehmen, nachdem sie mich in dem Plumpsklo eingesperrt hatten, um mich zu ertränken?!\n\nEs wird sich für Euch lohnen, wenn Ihr für mich zum Südmeerstützpunkt am östlichen Steilhang reist, und für mich Rache nehmen könntet.", sourceObjective = "Tötet 15 Piraten der Südmeerfreibeuter in Südemeerstützpunkt.", completion = "Das wird diesen gemeinen Hunden eine Lektion erteilen! Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25589] = { id = 25589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wenig Vergeltung", description = "Ich glaube, es ist an der Zeit, ein wenig Vergeltung zu üben. Das kann man mir kaum übel nehmen, nachdem sie mich in dem Plumpsklo eingesperrt hatten, um mich zu ertränken?!\n\nEs wird sich für Euch lohnen, wenn Ihr für mich nach Südmeerstützpunkt am östlichen Steilhang reist, und für mich Rache nehmen könntet.", sourceObjective = "Tötet 15 Piraten der Südmeerfreibeuter in Südemeerstützpunkt.", completion = "Das wird diesen gemeinen Hunden eine Lektion erteilen! Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25590] = { id = 25590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist Wizzel?", description = "Hey, {name}, Ihr habt meinen Bruder Wizzel auch nicht gesehen, oder?\n\nIch weiß nur, dass die Piraten ihn gefangen genommen haben! Er hatte wohl vor, ihnen irgendwelchen Ingenieurskram zu verkaufen.\n\nKönnt Ihr bitte in Südmeerstützpunkt östlich von hier nach ihm suchen? Ich befürchte, dass der nichtsnutzige Goblin Flämmer, mit dem er immer unterwegs ist, ihn in Schwierigkeiten gebracht hat!", sourceObjective = "Findet Wizzel Kupferbolz in Südmeerstützpunkt in Tausend Nadeln.", completion = "Hey! Holt mich hier raus!", sourceObjectiveStatus = "unverified-source-field" }
quests[25591] = { id = 25591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerkuppel: Erbitterter Zweikampf", description = "Wir haben eine Sonderanfrage erhalten! Ich habe hier eine Notiz von einer Megs Schredderschrek, die den Käfig betreten und etwas aus der Welt schaffen möchte.\n\nSie hat Euch als Wunschpartner angegeben, {name}. Ein Fan Eurer alten Erfolge? Oder vielleicht kennt Ihr Euch von woanders?\n\nIch würde an Eurer Stelle nicht absagen. Das klingt nach einem wunderbaren Finale...", sourceObjective = "Besiegt Kelsey Stahlfunken.", completion = "Fantastisch. Ich werde Euch selbst vielleicht einmal zu einem Duell herausfordern.", sourceObjectiveStatus = "unverified-source-field" }
quests[25592] = { id = 25592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff aus der Tiefe", description = "Ich konnte ein paar von den Überlebenden in die Höhle helfen, aber so langsam wird die Lage da draußen brenzlig. Als ob wir nicht schon genug Probleme hätten, schleichen sich jetzt auch noch diese leuchtenden Murlocs aus der nahegelegenen Spalte an und überfallen die gestrandeten Überlebenden.\n\nDie Männer da oben sind Krieger und werden sich nicht ohne Kampf ergeben, aber nach dieser verdammten Muschel sind sie alle ganz schön mitgenommen.\n\nWenn Ihr noch ein wenig Atem in Euren Lungen habt, geht nach oben und löscht ein paar dieser Murlocs aus. Höllschreis Augen ruhen auf Euch.", sourceObjective = "Tötet 10 Strauchdiebe der Rotkiemen.", completion = "Ihr wisst wirklich, was Ehre bedeutet, {class}. Ihr erfüllt Höllschrei mit Stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[25593] = { id = 25593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gepanzerte Rettung", description = "Viele haben es noch nicht in die Höhle geschafft. Bestimmt sind sie an den Rändern des Grats über uns gestrandet.\n\nWir haben ein paar Spiralungpanzer auf dem Weg hierher gefunden. Sie erzeugen zwar nicht viel Sauerstoff, aber er hat gereicht, um uns zur Höhle zu bringen.\n\nIch muss hier unten bleiben, um die Ankömmlinge zu zählen und sie wieder auf die Beine zu bringen. Tut mir einen Gefallen und sammelt diese Spiralungpanzer. Bringt sie zu meinen Männern oben auf dem Grat und gebt ihnen einen fixen Tritt in den Hintern, damit sie sich hier hinunter bewegen.", sourceObjective = "Sammelt 8 Spiralungpanzer und gebt sie gestrandeten Überlebenden von Nespirah.", completion = "Danke, {class}. Ihr habt Euch als äußerst nützlich erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25594] = { id = 25594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garstige Krebse", description = "Das war dieser verdammte Krebs!\n\nUnd ich dachte, all das Training durch den Marsch hierher macht mich richtig stark! Meine Ausrüstung wurde immer leichter und leichter. Aber nein! Dieser Krebs hat ein Loch in meine Tasche geschnitten und all meine Teile sind auf dem ganzen Weg hierher rausgefallen.\n\nBitte, helft einem gutaussehenden Goblin, ja? Geht und sammelt meine fehlenden Teile ein. Ich bin mir sicher, dass diese hinterhältigen, bösartigen kleinen Krebse auch welche davon gestohlen haben.", sourceObjective = "Sammelt 12 von Fiascos fehlenden Teilen.", progress = "Unterschätzt nie die Anziehungskraft von Glitzerkram.", completion = "Schön, dass Ihr leicht verdientes Gold erkennt, wenn es Euch über den Weg läuft. Es war mir eine Freude, mit Euch Geschäfte zu machen, Kumpel.", sourceObjectiveStatus = "unverified-source-field" }
quests[25595] = { id = 25595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was zum Essen", description = "Wollten sie uns zu Tode hungern?! Gefangenen keine Nahrung zu geben ist einfach niederträchtig.\n\nWir müssen diesen Soldaten etwas Essbares geben. Die einfachste Möglichkeit besteht wohl in diesen riesigen Schnappkieferbarschen. Ein paar von denen werden unseren Hunger auf Fleisch sicher ein paar Tage stillen können.\n\nWenn Ihr mir einige bringt, sorge ich dafür, dass sie zubereitet und gerecht verteilt werden.", sourceObjective = "Sammelt 8 Stück Fleisch eines Schnappkieferbarschs.", progress = "Bei all diesen knurrenden Mägen klingt es, als hielte sich ein Monster in dieser Höhle versteckt. Das macht mich ganz schön nervös.", completion = "Jetzt zu meinem Teil der Vereinbarung. Ich sorge sofort dafür, dass das hier zubereitet und verteilt wird.\n\nWir beide müssen uns später weiter unterhalten. Ich brauche Hilfe, die mir diese Soldaten einfach nicht bieten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[25596] = { id = 25596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist Flämmer?", description = "Hey, {name}, Ihr habt unseren Büchsenmacher Flämmer auch nicht gesehen, oder?\n\nIch weiß nur, dass die Piraten ihn gefangen genommen haben! Er hatte wohl vor, ihnen irgendwelche Waffen zu verkaufen.\n\nKönnt Ihr bitte im Südmeerstützpunkt östlich von hier nach ihm suchen? Ich befürchte, dass der nichtsnutzige Gnom Wizzel Kupferbolz, mit dem er immer unterwegs ist, ihn in Schwierigkeiten gebracht hat!", sourceObjective = "Findet Flämmer in Südmeerstützpunkt in Tausend Nadeln.", completion = "Hey! Holt mich hier raus!", sourceObjectiveStatus = "unverified-source-field" }
quests[25597] = { id = 25597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommandant Jarod Schattensang", description = "Nur einmal gab es einen Kommandanten, der in der Lage war, Halbgötter und Sterbliche gleichermaßen anzuführen.\n\nSein Name war Jarod Schattensang. Seine Führungsqualitäten waren so überragend, dass Cenarius und die anderen Ahnen sich aus freien Stücken seinem Befehl unterstellt haben.\n\nEr galt viele Jahre als verschollen. Keiner wusste, was mit ihm geschehen war. Bis jetzt.\n\nEr wird in einem Lager des Schattenhammers in der Flüsternden Schlucht gefangen gehalten.\n\nEure Aufgabe besteht darin, ihre Reihen zu unterwandern und Jarod zu befreien. Sprecht mit dem, den sie Ortell nennen, am Flüsternden Pass im Südosten.", sourceObjective = "Sprecht mit Elementarist Ortell am Flüsternden Pass.", completion = "Oh hallo! Ich bin froh, dass sie jemanden mit Eurem Können für dieses Unterfangen geschickt haben.\n\nDieser Auftrag erfordert viel Fingerspitzengefühl. Wir können nicht riskieren, dass Kommandant Schattensang getötet wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[25598] = { id = 25598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einer geht noch", description = "Jetzt, da Ihr mich in Sicherheit gebracht habt, muss ich Eure Freundlichkeit leider noch etwas weiter strapazieren.\n\nDer Kapitän unseres Schiffes, Samir, ist immer noch da draußen. Und auch Mack. Ich bin mir sicher, dass sie es zum Meeresgrund geschafft haben, aber ich konnte nicht sehen, was dann aus ihnen geworden ist.\n\nOhne ihre Hilfe könnte ich es an einem Ort wie diesem einfach nicht aushalten.\n\nIch habe sie in einem Tanggeflecht westlich des Ortes, an dem Ihr mich gefunden habt, aus den Augen verloren.\n\nBitte, beeilt Euch! Sie können noch nicht weit sein...", sourceObjective = "Findet Samir und Mack.", completion = "Was würde ich nur ohne Euch machen, {race}!\n\nIch mag es mir nicht einmal vorstellen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25599] = { id = 25599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aschenmaul, der Portalmeister", description = "Der Schattenhammer verwendet diese und andere Korridore dieser Art, um Vorräte von den Elementarebenen nach Azeroth zu bringen. Um diese Passagen zu versiegeln, müssen wir wissen, wie sie gebaut sind.\n\nSucht den Foliant der Öffnungen, den die Elementare verwenden, um die Tore zwischen den Ebenen zu öffnen.\n\nDer Portalmeister Aschenmaul sollte einen bei sich tragen. Ihr müsst ihn töten. Aber Vorsicht! Er hat wahrscheinlich den ein oder anderen Trick auf Lager...", sourceObjective = "Tötet Aschenmaul und findet den Foliant der Öffnungen.", progress = "Der Foliant! Habt Ihr ihn gefunden?", completion = "Das ist der Foliant, von dem wir so viel gehört haben?\n\n<Jordan hievt die Steintafel hoch und schaut sie sich an.>\n\nIch verstehe… Wie gut, dass ich ein wenig von der Elementarschrift lesen kann. Ich mache mich gleich an die Übersetzung. In der Zwischenzeit gibt es ein weiteres Problem, um das wir uns kümmern müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25600] = { id = 25600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmiedemeister Pyrendius", description = "Eine entsetzlich bösartige Macht hat sich mitten im Herzen dieser Höhle niedergelassen, {name}. Schmiedemeister Pyrendius hat viele der verfluchten Waffen, die der Schattenhammer auf seinen Beutezügen oben verwendet, selbst geschmiedet.\n\nBevor wir die Feuerlande verlassen... muss Pyrendius sterben.\n\nEr wird sicher nicht leicht zu besiegen sein, aber wenn ich den Folianten recht verstehe, können wir kurz kleine Tore zum Meeresschlund öffnen, dem Reich des Wassers. Lockt Pyrendius auf eine Portalrune und aktiviert sie, um ihn zu schwächen.", sourceObjective = "Tötet Schmiedemeister Pyrendius. Lockt ihn auf die Portalrunen und benutzt sie, um ihn zu schwächen.", completion = "Es ist vollbracht! Wir werden diese Flammenhölle hinter uns versiegeln und lassen den Schattenhammer die Leichen finden, die wir hinterlassen haben. Ohne Euch hätten wir das nicht geschafft, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25601] = { id = 25601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klassenprimus", description = "Damit ist die Sache klar, \"{name}damus\"! Ihr seid der Klassenprimus!\n\nIhr habt die Ehre, zu einer Masse der fanatischsten, blutdürstigsten und nachweislich geisteskrankesten Leute dieses Planeten zu sprechen.\n\nGeht und meldet Euch bei Eurem Instrukteur, um alle Details zu erhalten. Aber vergesst nicht: Euer Ziel ist es, die Feindschaft zwischen den Ogern am Sitz der Auserwählten und den anderen, weniger privilegierten Rassen zu schüren.\n\nWenn alles gut läuft, werden wir während des darauf folgenden Aufruhrs Jarod hier heraus schmuggeln.", sourceObjective = "Sprecht mit Instrukteurin Mylva an der Schmiede der Unterwerfung auf dem Hyjal.", completion = "Da seid Ihr ja, Kunrebidamus. Ich wollte etwas mit Euch besprechen.\n\nIch habe von dem unglücklichen Vorfall gehört, dem Euer armer Freund Okrog zum Opfer fiel.\n\n<Mylva schaut nach links, dann nach rechts. Schließlich nickt sie und zwinkert Euch verschmitzt zu.>\n\nIhr seid ein besserer Schüler, als ich dachte.", sourceObjectiveStatus = "unverified-source-field" }
quests[25602] = { id = 25602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der zündende Funke", description = "Mack ist immer noch bewusstlos und ich fürchte, dass wir ihn verlieren, wenn wir dieses Feuer nicht in Gang bringen. Da das Holz feucht geworden ist, brauchen wir einen speziellen Zünder.\n\nIn der Nähe befindet sich ein verlassenes Lager. Dort findet Ihr ein Fass mit Sprengstoff. Alleine schaffe ich es nicht bis dorthin.\n\nKönntet Ihr es für uns hierherschleppen? Für Mack?", sourceObjective = "Besorgt Euch das Pulverfass von Budds Ausgrabung.", progress = "Habt Ihr den Sprengstoff aus dem Lager geholt, {class}?", completion = "Ausgezeichnet!\n\nMal schauen, ob das für unsere Zwecke geeignet ist…\n\nTretet zurück, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25607] = { id = 25607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Där Gnomcordär", description = "Diese Goblins ekeln misch an. Die dreckische Goblinteschnique ist jeder Gnomenteschnique unterlegen, abär...\n\n<Professor Xakxak seufzt.>\n\nDas ist die letzte Teil von die Puzzle! Isch kann misch nischt bauen die Gnomcordär, wenn isch nischt 'aben etwas von die dreckische Goblinteschnique!\n\nIhr müsst ge'en in die Osten nach \"Stinkwerk\" und 'olen von ihnen etwas von die dreckische Goblinteschnique! Ihr werdet finden sie bei die Goblinteschniquer.\n\n<Professor Xakxak lacht spöttisch.>\n\nGoblinteschniquer? Was das sollen sein?\n\n<Professor Xakxak zuckt mit den Schultern.>\n\nEin Oxymoron?", sourceObjective = "Holt 8 Stücke dreckige Goblintechnologie.", progress = "Wo ist die Schrott? 'abt Ihr es?", completion = "Ah, die Schrott 'aben angekommen! Das ist die letzte Teil von die Puzzle! Jetzt isch muss machen fertisch! Achtüng, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25608] = { id = 25608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brandrodung", description = "Der Sieg ist möglich, {name}.\n\nDieses Portal ist nicht nur dazu da, um Cenarius durch den Traum zurückzubringen. Denkt darüber nach, {name}. Sobald das Tor durch den Smaragdgrünen Traum geöffnet ist, können unsere Truppen sich darüber frei zur Mondlichtung, nach Nordrassil und sogar an den strategisch gut gelegenen Wyrmruhtempel bewegen.\n\nAlles, was Ysera braucht, ist Zeit. Es liegt an Euch, die Streitmächte des Schattenhammers daran zu hindern, sich in der Flüsternden Schlucht zusammenzuziehen und uns vom Osten her anzugreifen.\n\nNehmt einen der Smaragddrachen und versetzt ihnen einen empfindlichen Schlag!", sourceObjective = "Schwingt Euch auf einen Smaragddrachen und tötet 40 Einheiten des Schattenhammers und 5 Zwielichtdrachen.", progress = "Ihr seid zurückgekehrt, {name}.", completion = "Ausgezeichnete Arbeit, {name}. Vielleicht können wir ja doch noch gewinnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25609] = { id = 25609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versunkene Schätze", description = "Tony Zweihauer, der Piratenadmiral, hat den Schlüssel für den Käfig - und ist von Ogern bewacht, die Ihr nicht töten können werdet!<Wizzel heult noch ein bisschen und schaut plötzlich nach oben. Man kann sehen, dass ihm eine Idee gekommen ist.>\n\nIch hab's! Was ist Piraten wichtiger, als alles andere? Sogar wichtiger als Grog? Genau... Schätze!\n\nSie hatten einst ein Schiff voller Schätze, das von einem riesigen Walhai versenkt wurde. Die Schätze sind überall im Illusionsschlund verteilt, nordwestlich von hier.\n\nGeht, und holt die Schätze ein!", sourceObjective = "Sammelt 8 versunkene Schatzkisten.", progress = "Oh Mann, habt Ihr etwa schon alle versunkenen Schatzkisten?", completion = "Oh, wie schön - seht Euch nur diese Beute an!\n\nMoment... bringt das mal näher her!", sourceObjectiveStatus = "unverified-source-field" }
quests[25610] = { id = 25610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versunkene Schätze", description = "Tony Zweihauer, der Piratenadmiral, hat den Schlüssel für den Käfig - und ist von Ogern bewacht, die Ihr nicht töten können werdet!<Wizzel heult noch ein bisschen und schaut plötzlich nach oben. Man kann sehen, dass ihm eine Idee gekommen ist.>\n\nIch hab's! Was ist Piraten wichtiger, als alles andere? Sogar wichtiger als Grog? Genau... Schätze!\n\nSie hatten einst ein Schiff voller Schätze, das von einem riesigen Walhai versenkt wurde. Die Schätze sind überall im Illusionsschlund verteilt, nordwestlich von hier.\n\nGeht, und holt die Schätze ein!", sourceObjective = "Sammelt 8 versunkene Schatzkisten.", progress = "Ihr habt schon alle versunkenen Schatzkisten?", completion = "Oh, wie schön - seht Euch nur diese Beute an!\n\nMoment... bringt das mal näher her!", sourceObjectiveStatus = "unverified-source-field" }
quests[25611] = { id = 25611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr aus den Feuerlanden", description = "Ich werde die restlichen Anhänger Goldrinns durch das Tor scheuchen und dieses Portal hinter uns versiegeln.\n\nDer Rest unserer Streitkräfte auf dem Hyjal will sicher von unserem Sieg erfahren. Kehrt zu Ian Duran zurück und lasst ihn wissen, was wir entdeckt und wie wir triumphiert haben!\n\nTretet einfach durch das Portal, um auf den Hyjal zurückzukehren.", sourceObjective = "Kehrt zu Ian Duran am Schrein von Goldrinn auf dem Hyjal zurück.", completion = "Sie bringen Verstärkung direkt über die Elementarebenen auf den Hyjal? Das erklärt natürlich einiges!\n\nGoldrinn ist gewiss stolz auf Euch, weil Ihr dieses Flammentor versiegelt habt, {name}, aber vielleicht gibt es noch mehr Portale, die versiegelt werden müssen. Ihr solltet auch die anderen Schreine untersuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25612] = { id = 25612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr aus den Feuerlanden", description = "Ich werde die restlichen Anhänger Lo'Goshs durch das Tor scheuchen und dieses Portal hinter uns versiegeln.\n\nDer Rest unserer Streitkräfte auf dem Hyjal will sicher von unserem Sieg erfahren. Kehrt zu Takrik Wutheuler zurück und lasst ihn wissen, was wir entdeckt und wie wir triumphiert haben!\n\nTretet einfach durch das Portal, um auf den Hyjal zurückzukehren.", sourceObjective = "Kehrt zu Takrik Wutheuler am Schrein von Goldrinn auf dem Hyjal zurück.", completion = "Sie bringen Verstärkung direkt über die Elementarebenen auf den Hyjal? Das erklärt natürlich einiges!\n\nLo'Gosh ist gewiss stolz auf Euch, weil Ihr dieses Flammentor versiegelt habt, {name}, aber vielleicht gibt es noch mehr Portale, die versiegelt werden müssen. Ihr solltet auch die anderen Schreine untersuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25613] = { id = 25613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tut Euch selbst einen Gefallen", description = "Also diese Nachtelfen haben einen verzweifelten Hilferuf an uns geschickt, der sich so anhörte:\n\n<Gnombus verstellt seine Stimme, um wie eine Frau zu klingen.>\n\n\"Bitte kommt und helft uns! Die große, gemeine Horde hat Goblins! Oh, wir kommen mit Goblins nicht klar! Sie ziehen uns an den Haaren und bringen uns zum Weinen!\"\n\nGut, also, hier sind wir nun.\n\nDas erste, was ich gemacht habe, war ihre Luftverteidigung mit einigen meiner neuen Heckenschützengewehre auf Vordermann zu bringen. Das Problem ist... Sie benutzen keine Schusswaffen. Tut Euch selbst einen Gefallen und helft ihnen, ok? Ihr findet sie südlich von hier.", sourceObjective = "Sprecht mit Kalen Freipfeil am Volltrefferposten im Steinkrallengebirge.", completion = "<Kalen seufzt.>\n\nWir benutzen Schusswaffen ganz ohne Probleme, mein Freund. Gegen KANONEN habe ich allerdings etwas...", sourceObjectiveStatus = "unverified-source-field" }
quests[25614] = { id = 25614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der einzige Weg nach unten ist im Leichensack", description = "Am Himmel wimmelt es nur so von schwerbewaffneten Orcs, die auf noch schwerer gepanzerten Windreitern sitzen. All unsere Bemühungen, sie vom Himmel zu holen sind gescheitert. Unsere Pfeile prallen normalerweise einfach von diesen widerwärtigen Kreaturen ab. Wenn es uns gelingen sollte, einen abzuschießen, benutzen die Orcs ihre Goblinfallschirme und landen sicher auf dem Boden.\n\nIhr müsst die Heckenschützenkanonen von Gnombus benutzen und damit erst die Windreiter des Kriegshymnenklans und danach die Orcs an den Fallschirmen abschießen.\n\nDer einzige Weg nach unten ist im Leichensack.", sourceObjective = "Tötet 8 Schwadronskommandanten des Kriegshymnenklans.", completion = "Ausgezeichnete Arbeit, {name}. Die Gnomtechnologie ist zwar leicht nervtötend, aber ziemlich wirksam. Jetzt sollten der Weg zur Scherwindfeste frei sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25615] = { id = 25615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zur Sternenstaubspitze zurück", description = "Jägerin Jalin wird erfreut sein zu hören, dass der Weg zur Scherwindfeste jetzt frei ist. Bitte kehrt zur Sternenstaubspitze zurück und informiert sie über unseren Erfolg. Sie wird mit ziemlicher Sicherheit noch mehr Arbeit für Euch haben, da der Weg jetzt frei ist.\n\nVielen Dank und viel Glück, <mein Freund/meine Liebe>.", sourceObjective = "Kehrt zu Jägerin Jalin an der Sternenstaubspitze im Eschental zurück.", completion = "Jetzt, da die Luft rein ist, sind unsere Hippogryphen in der Lage, sich frei ins Steinkrallengebirge zu bewegen. Gut gemacht, {name}!\n\nUnd jetzt wenden wir uns wichtigeren Dingen zu. \n\nWas Ihr am Volltrefferposten erlebt habt, war nur ein Beispiel für die Vernichtung, die Höllschrei hinter sich zurücklässt. Als Kriegshäuptling der Horde hat Höllschrei Kalimdor zum Territorium der Horde erklärt. Alle, die sich der Horde widersetzen, werden vernichtet.\n\nWir sind die letzte Verteidigungslinie von Kalimdor. Wenn wir fallen, fällt Kalimdor. Die Horde muss aufgehalten werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[25616] = { id = 25616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllschreis Vermächtnis", description = "Begebt Euch über den Steinkrallenpass ins Steinkrallengebirge und lauft in Richtung der schwelenden Bäume. Sucht Verbrenner von Krom'gar, die den Wald zerstören und tötet so viele Ihr könnt! Aber Vorsicht, die Verbrenner sind mächtige Orcs. Wenn Ihr sie mit normalen Mitteln angreift, bedeutet das wahrscheinlich Euren Tod. Zerstört die Ölkanister auf ihren Rücken und sie werden von den Flammen verschlungen!\n\nWenn Ihr Erfolg habt, meldet Euch bei Schildwache Heliana an der Scherwindmine. Sie wird neue Befehle für Euch bereithalten.", sourceObjective = "Tötet 10 Verbrenner von Krom'gar.", completion = "Jetzt, da Ihr Euch um die Verbrenner von Krom'gar gekümmert habt, kann der Wald vielleicht wieder nachwachsen. Allein die Zeit kann die Wunden heilen, die die Horde hinterlassen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[25617] = { id = 25617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Schlund!", description = "Oben am Gewittersims hat der Schattenhammer ein riesiges Flammentor errichtet. Ich weiß nicht, wohin es führt. Ich weiß nur, dass es nicht zu dieser Welt gehört und ich es nicht betreten kann. Und alle meine anderen Anhänger, die hineingegangen sind, kamen nie wieder heraus.\n\nIch möchte, dass Ihr dieses Reich betretet und meine Klauen und Zähne darin seid. Tretet durch das Flammentor. Wenn er noch lebt, dann trefft Euch auf der anderen Seite mit Jordan Olafson. Er wird Euch etwas geben, mit dem Ihr meine Macht in diesem Reich nutzen könnt.\n\nSeid mutig, {name}. Findet heraus, wohin das Flammentor führt, und vernichtet alles, was Ihr dahinter findet.", sourceObjective = "Durchschreitet das Flammentor oben am Gewittersims auf dem Hyjal und sprecht mit Jordan Olafson auf der anderen Seite.", completion = "Ah, Ihr seid also der Champion, so wie Lo'Gosh es versprochen hat. Eure Augen täuschen Euch nicht. Ihr habt die Feuerlande betreten, eine Elementarebene aus geschmolzenem Stein und Feuer. Daher ist unsere Arbeit etwas eingeschränkt.\n\nLegt Eure Streitigkeiten mit der Allianz auf Eis. Hier lauern schon genug Gefahren.\n\nUnd nehmt das hier. Mit Lo'Goshs Fangzahn könnt Ihr in den Feuerlanden die Macht der Ahnen nutzen. Verwendet ihn weise!", sourceObjectiveStatus = "unverified-source-field" }
quests[25618] = { id = 25618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Schlund!", description = "Oben am Gewittersims hat der Schattenhammer ein riesiges Flammentor errichtet. Ich weiß nicht, wohin es führt. Ich weiß nur, dass es nicht zu dieser Welt gehört und ich es nicht betreten kann. Und alle meine anderen Anhänger, die hineingegangen sind, kamen nie wieder heraus.\n\nIch möchte, dass Ihr dieses Reich betretet und meine Klauen und Zähne darin seid. Tretet durch das Flammentor. Wenn er noch lebt, dann trefft Euch auf der anderen Seite mit Jordan Olafson. Er wird Euch etwas geben, mit dem Ihr meine Macht in diesem Reich nutzen könnt.\n\nSeid mutig, {name}. Findet heraus, wohin das Flammentor führt, und vernichtet alles, was Ihr dahinter findet.", sourceObjective = "Durchschreitet das Flammentor oben am Gewittersims auf dem Hyjal und sprecht mit Jordan Olafson auf der anderen Seite.", completion = "Ah, Ihr seid also der Champion, so wie Goldrinn es versprochen hat. Eure Augen täuschen Euch nicht. Ihr habt die Feuerlande betreten, eine Elementarebene aus geschmolzenem Stein und Feuer. Daher ist unsere Arbeit etwas eingeschränkt.\n\nLegt Eure Streitigkeiten mit der Horde auf Eis. Hier lauern schon genug Gefahren.\n\nUnd nehmt das hier. Mit Goldrinns Fangzahn könnt Ihr in den Feuerlanden die Macht der Ahnen nutzen. Verwendet ihn weise!", sourceObjectiveStatus = "unverified-source-field" }
quests[25619] = { id = 25619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederbesetzung", description = "An Kvaldir zum Töten mangelt es hier nicht. Offensichtlich hat unser Angriff sie ganz schön aus der Bahn geworfen. Die Stadt war so lange verlassen, dass sie wahrscheinlich nicht damit gerechnet haben, auf Gegenwehr der Naga zu stoßen.\n\nÜber ihren Anführer haben wir bisher noch nichts erfahren. Ich bin mir sicher, dass wir diesen Feigling noch früh genug aus seinem Loch hervorlocken können, wenn wir seine Leute weiter abschlachten.\n\nWollen wir fortfahren?", sourceObjective = "Tötet 10 Verteidiger der Kvaldir in den Ruinen von Vashj'ir.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", progress = "Ich habe Geschichten von der Wildheit dieser Kvaldir gehört, aber bis jetzt scheint das nur heiße Luft zu sein.", completion = "Ha! Ihr hattet wohl Recht. Dieser zerbrochene Dreizack scheint Euch gute Dienste zu leisten. Ich schätze, ich werde heute nicht zu sehen bekommen, wie Ihr etwas mit bloßen Klauen zu Tode reißt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25620] = { id = 25620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die ehrwürdige Lady", description = "Die ehrwürdige Lady sendet Euch eine Botschaft. Sie erwartet Euch auf der anderen Seite der Tempelgärten.\n\nWenn Ihr das Bedürfnis verspürt, die heldenhaften Taten Eures treuen Waffenbruders Azjentus zu erwähnen, bitte, tut Euch keinen Zwang an. Ich werde Eure Bewunderung für mich nicht als Schwäche auslegen.\n\nDoch jetzt halte ich Euch nicht länger auf. Die Dame wartet.", sourceObjective = "Sprecht mit Lady Naz'jar am nördlichen Ende der Gärten von Quel'Dormir.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", completion = "Ah, meine Kriegsmaid, da seid Ihr ja. Die Kriegerkaste spricht nur noch von Euren Siegen auf dem Schlachtfeld. Und das, wo wir unsere Bemühungen, die Stadt einzunehmen, doch gerade erst begonnen haben.\n\nIhr habt mir bisher treu gedient und mich mit Stolz erfüllt. Möge die Königin Euch ihre Gunst gewähren, damit dies auch in Zukunft so sei.", sourceObjectiveStatus = "unverified-source-field" }
quests[25621] = { id = 25621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldversuch: Gnomcorder", description = "Die Gnomcordär ist fertisch! Jetzt wir müssen machen eine Test!\n\nIhr müsst ge'en nach die Steinkrallengebirge in die Südenosten und ge'en über die Steinkrallenpass bis zu die dreckische Goblinbohrmaschin'. Isch werde aktivieren die Gnomcordär wenn Ihr 'abt erreischt Eure Ziel!Ihr erlernt:", sourceObjective = "Begebt Euch ins Steinkrallengebirge und geht den Steinkrallenpass Richtung Süden entlang, bis Ihr die große Goblinbohrmaschine findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25622] = { id = 25622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burn, Baby, Burn!", description = "Diese Verbrennär von die Orcs 'aben schlimme Waffen um zu brennen die Wald niedär! Ihr müsst sie töten und nehmen die Flammenwerfär. Wenn Ihr 'abt die Flammenwerfär, Ihr müsst suchen nach die Vorräte von die Kriegs'ymnenklan und benutzen die Flammenwerfär für abzufackeln!\n\nVerbrennt sie alle und isch werde Eusch belohnen! Ja, die Gnomcordär kann transportieren Dinge.\n\nWartet! 'ört Ihr das? Isch glaube, eine Orc is in die Näh'! Vorsischt!", sourceObjective = "Bringt einen Flammenwerfer des Kriegshymnenklans von einem Verbrenner von Krom'gar an Euch und benutzt ihn, um 8 Vorräte des Kriegshymnenklans zu zerstören.", completion = "<Der Gnomcorder summt laut.>\n\nWunderbar. Wie versprochen - VOILA, 'ier ist Belohnung für Eusch!\n\nJetzt isch 'aben eine Neuigkeit, die Ihr könntet finden interessant.", sourceObjectiveStatus = "unverified-source-field" }
quests[25623] = { id = 25623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Schlund!", description = "{name}, da seid Ihr ja! Goldrinn hat eine Aufgabe, die nur sein Champion erfüllen kann. Oben am Gewittersims hat der Schattenhammer ein riesiges Flammentor errichtet. Wir wissen nicht, wohin es führt, aber Goldrinn kann es nicht betreten. Der Ahn möchte, dass Ihr seine Klauen und Zähne seid.\n\nTretet durch das Flammentor und sprecht auf der anderen Seite mit Jordan Olafson. Er wird Euch etwas geben, mit dem Ihr Goldrinns Macht in diesem Reich nutzen könnt. Findet heraus, wohin das Flammentor führt!", sourceObjective = "Durchschreitet das Flammentor oben am Gewittersims auf dem Hyjal und sprecht mit Jordan Olafson auf der anderen Seite.", sourceObjectiveStatus = "unverified-source-field" }
quests[25624] = { id = 25624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Schlund!", description = "{name}! Lo'Gosh braucht Euch. Oben am Gewittersims hat der Schattenhammer ein riesiges Flammentor errichtet. Wir wissen nicht, wohin es führt, aber keiner, der es betreten hat, ist je zurückgekommen. Lo'Gosh möchte, dass Ihr hindurchgeht und seine Klauen und Zähne seid.\n\nTretet durch das Flammentor und sprecht auf der anderen Seite mit Jordan Olafson. Er wird Euch etwas geben, mit dem Ihr Lo'Goshs Macht in diesem Reich nutzen könnt. Findet heraus, wohin das Flammentor führt!", sourceObjective = "Durchschreitet das Flammentor oben am Gewittersims auf dem Hyjal und sprecht mit Jordan Olafson auf der anderen Seite.", completion = "Ah, Ihr seid also der Champion, so wie Lo'Gosh es versprochen hat. Eure Augen täuschen Euch nicht. Ihr habt die Feuerlande betreten, eine Elementarebene aus geschmolzenem Stein und Feuer. Daher ist unsere Arbeit etwas eingeschränkt.\n\nLegt Eure Streitigkeiten mit der Allianz auf Eis. Hier lauern schon genug Gefahren.\n\nUnd nehmt das hier. Mit Lo'Goshs Fangzahn könnt Ihr in den Feuerlanden die Macht der Ahnen nutzen. Verwendet ihn weise!", sourceObjectiveStatus = "unverified-source-field" }
quests[25626] = { id = 25626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visionen der Vergangenheit: Aufstieg aus der Tiefe", description = "Was Ihr mir vorhin von den Naga erzählt habt, lässt mir keine Ruhe mehr. Wer sind diese Verbündeten, die sie rufen? Denken sie wirklich, sie könnten den Gezeitenjäger besiegen?\n\nDie Flucht aus dieser Höhle ist eine ganz schöne Erleichterung, aber unser Ziel hier bleibt das gleiche. Ich hoffe, dass Ihr bereit seid, ein letztes Mal die Antworten bei der Kriegsmaid zu suchen.\n\nEs kann nur einen Ort geben, an den sie das Artefakt gebracht haben: den Tempel oben auf den Ruinen. Sicher wird er gut beobachtet. Seid daher vorsichtig.", sourceObjective = "Werdet Zeuge der letzten Geschichte der Kriegsmaid, indem Ihr ihre gebrochene Klinge im Tempel von Quel'Dormir benutzt.", completion = "Diener des alten Gottes? Dann haben sich zwei sehr gefährliche Feinde miteinander verbündet. Vielleicht ist es doch nicht so abwegig, dass sie den Gezeitenjäger töten können.\n\n{name}, das dürfen wir nicht zulassen. Wenn Azshara den Gezeitenjäger besiegt und seine Macht an sich reißt, kann wahrscheinlich keiner auf den Meeren gegen sie bestehen.\n\nWenigstens ist der erste Schritt eindeutig. Wir müssen dieses Untier vernichten, das unsere Schiffe zerstört hat. Unsere Marine war mutig genug, eine neue Flotte hierher zu bringen. Vielleicht haben sie ja einen Plan.", sourceObjectiveStatus = "unverified-source-field" }
quests[25627] = { id = 25627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abreibung für Zweihauer", description = "Diese Schätze sind alle nicht echt, aber die Knüppler im Unterschlupf werden den Unterschied nicht erkennen, so blöd, wie Oger sind!\n\nHier ist der Plan: Ihr begebt Euch in den Admiralsunterschlupf und verteilt diese \"Schätze\" an alle Oger, die Euch über den Weg laufen. Dann müsst Ihr Euch nur noch um Tony Zweihauer kümmern.\n\nSo bekommt Ihr den Schlüssel zum Käfig in null Komma nichts!", sourceObjective = "Erhaltet den rostigen Käfigschlüssel.", progress = "Was ist hier los? Holt Ihr mich hier raus?", completion = "Ja, ja... sicherlich war Euer kleines Abenteuer in die Höhle sehr interessant.\n\nWarum unterhalten wir uns nicht bei einem Drink auf dem Turbodampfer in Ruhe darüber, wenn Ihr es noch schafft, mich hier rauszulassen?", sourceObjectiveStatus = "unverified-source-field" }
quests[25628] = { id = 25628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abreibung für Zweihauer", description = "Diese Schätze sind alle nicht echt, aber die Knüppler im Unterschlupf werden den Unterschied nicht erkennen, so blöd, wie Oger sind!\n\nHier ist der Plan: Ihr begebt Euch in den Admiralsunterschlupf und verteilt diese \"Schätze\" an alle Oger, die Euch über den Weg laufen. Dann müsst Ihr Euch nur noch um Tony Zweihauer kümmern.\n\nSo bekommt Ihr den Schlüssel zum Käfig in null Komma nichts!", sourceObjective = "Erhaltet den rostigen Käfigschlüssel.", progress = "Was ist hier los? Holt Ihr mich hier raus?", completion = "Ja, ja... sicherlich war Euer kleines Abenteuer in die Höhle sehr interessant.\n\nWarum unterhalten wir uns nicht bei einem Drink auf dem Turbodampfer in Ruhe darüber, wenn Ihr es noch schafft, mich hier rauszulassen?", sourceObjectiveStatus = "unverified-source-field" }
quests[25629] = { id = 25629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hand der Lady", description = "Kriegsmaid!\n\nSucht nach meiner Ehrenwache auf dem Schlachtfeld und nehmt ihnen ihre Feinde ab. Sie müssen sofort zurückkehren, um die Priesterinnen zu beschützen.\n\nIch kümmere mich um den Eingang. Beeilt Euch!", sourceObjective = "Besiegt die Gegner von 8 Mitgliedern der Ehrenwache der Naz'jar und übergebt ihnen ihre neuen Befehle.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", progress = "Als die Kämpfe ausbrachen, habe ich meine Ehrenwache losgeschickt. Sie sind besser ausgerüstet, um mit dem Chaos dieser Schlacht umzugehen und ich bedarf kaum ihrer Hilfe.", completion = "Gut gemacht, Kriegsmaid.\n\nIch sehe nach der östlichen Brücke. Ihr müsst Euch um den Tempel kümmern. Das Ritual darf nicht unterbrochen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25630] = { id = 25630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Feuer des Hyjal", description = "Seht Ihr das, {name}? Vom Bergrücken südwestlich von hier… steigen Schwaden schwarzen Rauchs in den Himmel auf.\n\nDer Hyjal brennt.\n\nWenn die Feuer schon so hoch oben am Berg angekommen sind, bedrohen sie sicher auch den Hain von Aessina und unsere Streitkräfte dort.\n\nSprecht mit Laina Nachthimmel in der Nähe des Hains von Aessina. Als ich zuletzt von ihr hörte, bemühte sie sich, den Angriff abzuwehren.", sourceObjective = "Sprecht mit Laina Nachthimmel in der Nähe des Hains von Aessina auf dem Hyjal.", completion = "Kann das warten, {class}? Die Schlacht steht schlecht für uns.\n\nOh, Ihr seid hier, um zu helfen. Ich hoffe, Ihr mögt es heiß…", sourceObjectiveStatus = "unverified-source-field" }
quests[25637] = { id = 25637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf den Ruf des Tiefenlords", description = "Tiefenlord Zin'jatar hat uns berichtet, dass der Anführer der Kvaldir sich gezeigt hat. Begebt Euch zu ihm. Er befindet sich am gegenüberliegenden Ende der Terrasse über uns, auf der mittleren Ebene der Ruinen: Die Terrasse von Nar'shola.\n\nTötet alle Kvaldir, die Euch im Weg stehen. Wir möchten, dass der Widerhall dieser Niederlage in ihren Köpfen gellt, auf dass sie es nicht wagen, zurückzukehren und unser Vorhaben hier zu stören.\n\nEuer hingebungsvoller Einsatz bleibt nicht unbemerkt, meine Kriegsmaid. Geht und wisst, dass Ihr meinen Segen habt.", sourceObjective = "Tötet 16 Kvaldir auf der Terrasse von Nar'shola, der mittleren Ebene der Ruinen.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", completion = "Wie schön, dass Ihr Euch mir anschließt, Kriegsmaid. Kampfgeräusche untermalten Eure Ankunft. Welch süßer Klang in meinen Ohren.", sourceObjectiveStatus = "unverified-source-field" }
quests[25638] = { id = 25638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verzweifelte Bitte", description = "Die Nachricht in dieser Flasche ist nass aber immer noch lesbar.\n\nDer Schreiber behauptet, aus einem Nagagefängnis unter dem Meer entkommen zu sein.\n\nEr fürchtet deutlich um sein Leben. Ihr fragt Euch, ob es sich dabei um einen Eurer kürzlich entführten Schiffskameraden handeln könnte.\n\nDa Ihr nicht wisst, wie Ihr den Flüchtling finden sollt, beschließt Ihr, Euren Fund Erunak zu zeigen.", sourceObjective = "Bringt die durchnässte Notiz zu Erunak am Tiefgang.\n\nBereitgestellter Gegenstand:", completion = "Wenn sie noch am Leben ist, kann ich diese arme Seele vielleicht finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25640] = { id = 25640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer frei: Scherwindmine!", description = "Wir 'aben entdeckt die Ort von die große Goblinbomb', die Ihr 'abt gefunden in Silberwindzuflucht.\n\nIhr Eusch erinnern an Boog? Die Gnom, die Ihr 'abt gerettet von die Orcwagen? Er und Minx 'aben gefunden die Bomb' in die Scherwindmine. Ihr müsst ge'en dort'in toute de suite... sofort, {name}! Sie werden warten auf Eusch.", sourceObjective = "Sprecht mit Boog dem \"Zahnradflüsterer\" an der Scherwindmine im Steinkrallengebirge.", completion = "Schön, Euch wiederzusehen, {name}. Danke für die Rettung in Eschental. Sehr schade um die ganzen Gnome, die wir verloren haben.\n\nSeid Ihr bereit, an die Arbeit zu gehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[25641] = { id = 25641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muiseknachschub", description = "Ich habe alles getan, was ich für Euch tun konnte. Aber ich bin noch nicht mächtig genug, um mit etwas mächtigerem als Hippogryphenmuisek zu arbeiten - vor dem Desaster, das dadurch entstehen könnte, verschone ich Euch zuerst.\n\nWährend Ihr beschäftigt wart, habe ich den Hippogryphenmuisek fertiggestellt. Bringt es zu meinem Meister, dem Hexenmeister Uzer'i in Camp Mojache. Er kann damit mächtige Waffen herstellen und hoffentlich wird er von meinen bisherigen Leistungen beeindruckt sein.", sourceObjective = "Bringt das Gefäß für Hippogryphenmuisek zu Hexendoktor Uzer'i in Camp Mojache in Feralas.", progress = "Ihr kommt mir bekannt vor...", completion = "Gute Arbeit, in der Tat... von meiner eigenen Tochter hätte ich allerdings auch nicht weniger erwartet. Sie wird noch eine gute Hexe werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25642] = { id = 25642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schaut ihnen nicht in die Augen", description = "Zieht Euren Kopf ein, {name}. Wir wollen keine ungebetene Aufmerksamkeit auf uns lenken.\n\nAnscheinend beladen die Orcs den Ballon mit irgendeinem Erz aus der Mine. Geht dort hinein und nehmt den Orcs das Erz weg. Bringt mir alles, das ihr tragen könnt und ich werde es zur Untersuchung zum Professor schicken.\n\nBevor Ihr geht noch ein Ratschlag: Ihr könnt die Krom'gar leicht umgehen, weil sie (1) dumm wie Bohnenstroh sind und (2) nichts sehen können, wenn sie Erz tragen. Natürlich müsst Ihr sie töten, um an das Erz zu kommen.", sourceObjective = "Sammelt 10 Proben azurblaues Eisenerz ein.", progress = "Bringt mir die Erzproben!", completion = "Ich hoffe, das hat Euch nicht zu viel Mühe bereitet. Mit diesen Proben sollten wir in der Lage sein herauszufinden, was sie mit dem Erz und der großen Bombe vorhaben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25643] = { id = 25643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Graunebelruinen", description = "Ich werde von Visionen heimgesucht, {name}. Visionen eines großen Machtsymbols, das in die Hände eines dunklen Wesens fällt. Ich sehe ein Amulett, von den uralten Elfen gehalten... das in Vergessenheit geraten ist und alles in seiner Umgebung in Ruinen verwandelt, bis die Dämonen es durch Betrug und Bosheit erhalten.\n\nJede Nacht schleichen sich diese Bilder wieder und wieder in meine Träume. Die Geister schicken uns eine Warnung. Ich bin zu alt und die Kriegerhelden des Lagers sind damit beschäftigt, uns zu beschützen. Ich bitte Euch, folgt meinen Visionen in Richtung Süden zu den Graunebelruinen und macht das Amulett ausfindig.", sourceObjective = "Sucht in den Graunebelruinen nach dem Amulett, das der Weise Bleichlauf beschrieben hat.", completion = "<Als Ihr Euch dem Podest nähert, merkt Ihr, dass es leer ist. Kälte füllt den Raum und eine leise Stimme ertönt...>", sourceObjectiveStatus = "unverified-source-field" }
quests[25644] = { id = 25644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zwielichtei", description = "Dieses Ei ist anders als alles, was Ihr je gesehen habt. Die durchsichtige Schale scheint das Licht um sie herum zu brechen.\n\nDaneben findet Ihr eine Nachricht, die die Ankunft einer fruchtbaren Brutmutter im Zirkel des Aszendenten beschreibt.\n\nVielleicht solltet Ihr Aronus das hier zeigen.", sourceObjective = "Bringt das reine Zwielichtei zu Aronus an den Toren von Sothann auf dem Hyjal.\n\nBereitgestellter Gegenstand:", completion = "Ihr habt richtig gehandelt, mir dies zu bringen, {name}. Dies ist eine große Bedrohung für uns, der wir uns unverzüglich und furchtlos stellen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25645] = { id = 25645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zum Weisen Bleichlauf zurück", description = "Das sanfte Leuchten bei dem Podest wird heller und Ihr könnt eine einfache Kette erkennen, die dort zurückgelassen wurde. Das muss das Amulett sein, wegen dem Euch der Weise Bleichlauf hergeschickt hat...", sourceObjective = "Bringt das Graunebelamulett zum Weisen Bleichlauf.", progress = "Ihr seid zurückgekehrt. Was habt Ihr gefunden?", completion = "Ich bin ein Narr... ich wurde in die Irre geleitet. Dies ist nur ein rostiges Stück Schmuck - meine Visionen haben sich zweifellos bewahrheitet.\n\nVergebt mir, {name}. Ich werde dafür beten, dass Ihr über diese Dämonin siegen werdet, so wie Ihr über Verinias gesiegt habt, solltet Ihr sie jemals wiedertreffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25646] = { id = 25646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säuberung der Scherwindmine", description = "Die Horde hat die Scherwindmine eingenommen. Ich bin nicht sicher, was diese Orcs hier herausschleppen oder warum sie hier sind, aber ich weiß, das kann nichts Gutes bedeuten. Geht dort hinein und schaltet die Führung aus. Ohne die Goblinaufseher werden diese Peons noch nutzloser sein.\n\nWährend Ihr dort drin seid, haltet die Augen offen, ob Ihr noch weitere Informationen findet, was die Horde dort in den Minen treibt.\n\nViel Glück.", sourceObjective = "Tötet 6 Vorarbeiter der Scherwindmine.", completion = "Gute Arbeit, ich konnte ihre schrillen Schreie von hier aus hören! Ihr habt den ganzen Ort auf den Kopf gestellt!\n\nHabt Ihr noch weitere Informationen über die Vorgänge in der Mine gefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[25647] = { id = 25647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unleserlicher Orcbrief", description = "Ihr habt ein Pergament mit einem beeindruckenden Hordensiegel darauf gefunden. Leider ist der Rest des Dokuments vollkommen unverständlich, weil es auf Orcisch ist.\n\nBringt den Brief zu Boog. Vielleicht weiß er etwas damit anzufangen!", sourceObjective = "Bringt den unleserlichen Orcbrief zu Boog dem \"Zahnradflüsterer\" an der Scherwindmine im Steinkrallengebirge.", progress = "Was habt Ihr da für mich?", completion = "<Boog nimmt Euch den Brief ab und studiert ihn.>\n\nInteressant.\n\n<Boog riecht an dem Pergament.>\n\nHrm... Beunruhigend...\n\n<Boog faltet das Papier auf der Hälfte und schaut Euch an.>\n\nIch verstehe absolut gar nichts von dem, was da geschrieben steht - wenn es überhaupt geschrieben ist. Könnte auch Klopapier sein. Riecht auf jeden Fall so.", sourceObjectiveStatus = "unverified-source-field" }
quests[25648] = { id = 25648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jenseits von Durotar", description = "Hmpfff ... Eure Dienste werden anscheinend anderswo benötigt. Ag'tor Blutfaust sucht nach Rekruten, die die Unternehmungen der Horde in Azshara nördlich von Orgrimmar unterstützen.\n\nIhr habt sicherlich noch Arbeit hier in Durotar und ich hörte, dass man Euch bald um Hilfe im Brachland bitten wird. Also ich an Eurer Stelle würde nirgendwo hingehen, aber wenn Ihr unbedingt das Schicksal herausfordern wollt... Azshara wartet.", sourceObjective = "Meldet Euch bei Ag'tor Blutfaust am Hinteren Tor von Orgrimmar in Azshara.", completion = "Gut, Ihr seid hier. Willkommen in Azshara, der Bühne für den nächsten Akt der ruhmreichen Zukunft der Horde. Und jetzt an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25649] = { id = 25649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minx wird's schon richten", description = "Die gute Nachricht ist, dass Minx fließend Orcisch spricht und sie ist in der Nähe. Geht zurück in die Mine und findet sie. Sie ist wahrscheinlich etwas tiefer in der Mine und steht nutzlos herum.\n\nVergesst das Pergament nicht.", sourceObjective = "Bringt den unleserlichen Orcbrief zu Minx in der Scherwindmine im Steinkrallengebirge.", progress = "Was habt Ihr da für mich?", completion = "<Minx nimmt Euch den Brief ab und studiert ihn.>\n\nOha.\n\n<Minx riecht an dem Pergament.>\n\nIst ja widerlich!\n\n<Minx faltet das Papier auf der Hälfte und schaut Euch an.>\n\nDie gute Nachricht ist - es ist kein Klopapier. Die schlechte Nachricht ist, dass die Tinte auf diesem Papier eine Mischung aus Kododung und Blut ist. Und das ist noch nicht das Schlimmste...", sourceObjectiveStatus = "unverified-source-field" }
quests[25650] = { id = 25650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle des Oberkommandos", description = "Bei dem Brief handelt es sich um Befehle des Hordenoberkommandos. Jemand mit Namen Oberanführer Krom'gar hat angeordnet, dass diese Mine \"ausgeräumt\" werden soll, um einen Splitter von etwas zu erhalten, das \"azurblaues Eisenerz\" heißt. Wahrscheinlich erhält man diesen Splitter, wenn man das Erz abbaut.\n\nEs wird noch schlimmer. Sie haben vor, diesen azurblauen Splitter mit Sprengstoffen in der riesigen Bombe zu vermischen und dann die Scherwindfeste in die Luft zu jagen.\n\nWir dürfen keine Zeit mehr verlieren, {name}! Nehmt diese Übersetzung des Briefs und kehrt zu Boog zurück! Er wird wissen, was als Nächstes zu tun ist.", sourceObjective = "Bringt den übersetzten Orcbrief zu Boog dem \"Zahnradflüsterer\" an der Scherwindmine im Steinkrallengebirge.", progress = "Nun? Was steht da?", completion = "<Schweißperlen laufen Boog über die viel zu große Stirn, während er den übersetzten Brief liest.>\n\nDas ist übel. Richtig, richtig übel. Ihr müsst Lord Brachweiher in der Scherwindfeste warnen.\n\nWas zur…? Er BEWEGT sich! Der Goblinballon hebt ab! Wir kommen zu spät!", sourceObjectiveStatus = "unverified-source-field" }
quests[25651] = { id = 25651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh süßer Wahnsinn!", description = "Also, ich habe nachgedacht…\n\nWenn jemand total durchgeknallt ist, weiß er das dann?\n\nIch könnte zum Beispiel schwören, dass ich ein Fass mit Schießpulver von den Kanonenkugeln hier gesammelt habe, aber es ist einfach unauffindbar.\n\nIch erinnere mich noch genau daran, wie ich die Kanonenkugeln von den Gilblins westlich von hier stibitzt habe.\n\nVielleicht stimmen die Gerüchte ja... vielleicht habe ich wirklich nicht mehr alle Tassen im Schrank.", sourceObjective = "Sammelt 50 gestohlene Kanonenkugeln auf Gurboggels Fels und von Hamsterern der Gilblin. Benutzt die Kanonenkugeln, um ein Fass mit Schießpulver herzustellen.", progress = "Ihr wollt nichts mit mir zu tun haben, {race}.\n\nIch bin ein bisschen… meschugge.", completion = "Mein Schießpulver!\n\nIhr habt es gefunden! Ich bin also doch nicht verrückt!", sourceObjectiveStatus = "unverified-source-field" }
quests[25652] = { id = 25652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschlagnahmt den Ballon!", description = "Wir dürfen keine Zeit verlieren, {name}. Ihr müsst diesen Heißluftballon beschlagnahmen und aufhalten!\n\nWie? Keine Ahnung! Wir haben keine Zeit, uns um Details zu streiten! Schnappt Euch die Strickleiter und klettert hinauf! Dann prügelt einfach auf alles ein, wenn Ihr drin seid!\n\nWenn Ihr den Ballon irgendwie anhalten könnt und überlebt, meldet Euch bei Lord Brachweiher in der Scherwindfeste im Westen.\n\nViel Glück, wir alle zählen auf Euch. Wenn Ihr mich jetzt entschuldigen wollt, ich muss um MEIN LEBEN RENNEN!", sourceObjective = "Fahrt mit dem Heißluftballon von Krom'gar und versucht zu verhindern, dass er die Scherwindfeste zerstört.", completion = "Unglaubliche Geschichte, mein Freund. Wenn ich es nicht mit eigenen Augen gesehen hätte, würde ich Euch nicht glauben. Ihr habt dem Ballon so viel Schaden zu gefügt, dass Ihr diese Unholde zum Rückzug gezwungen habt! Leider ist die Bedrohung noch längst nicht abgewendet! Wir haben den Angriff nur hinausgezögert. Es gibt noch viel zu tun, wenn wir die Horde davon abhalten wollen, das Steinkrallengebirge zu zerstören!", sourceObjectiveStatus = "unverified-source-field" }
quests[25653] = { id = 25653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ahnen sind mit uns", description = "Nemesis… vernichtet.\n\nIch fühle mich jung.\nMächtig.\nErleuchtet.\n\nSagt Ysera, dass meine Stärke ganz ihr gehört.\n\nDer Schattenhammer wird fallen.", sourceObjective = "Kehrt zu Ysera in Nordrassil auf dem Hyjal zurück.", completion = "Indem Ihr Tortolla von seiner letzten Last befreit habt, habt Ihr uns einen ausgezeichneten Verbündeten verschafft… und das letzte Stück unseres Plans.\n\nMacht Euch bereit, {name}. Der schwierigste Teil unserer Reise steht kurz bevor.\n\nWir werden den Kampf in ihre Feste tragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25654] = { id = 25654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkles Herz", description = "Edana Hasskralle ist die Königin der Harpyien der Nordschwingen, die in den Ruinen westlich von hier leben. Es ist ihr bösartiger Wille, der die Harpyien dazu anregt, ihre Nester inmitten der Ruinen unseres Volkes zu verteidigen.\n\nDie Harpyien können sie mit einem speziellen Horn rufen. Wenn man das Horn bei den Hasskrallensteinen im nördlichen Teil der Ruinen bläst, so erscheint Edana.\n\nZeigt diesen garstigen Kreaturen keine Gnade. Tötet Edana, und bringt mir ihr dunkles Herz.", sourceObjective = "Tötet Edana Hasskralle und erhaltet Edanas dunkles Herz.", progress = "Wir dürfen den Einfall der Harpyien in die Ruinen unserer Vorfahren nicht einfach hinnehmen.", completion = "Diese Länder werden endlich von der Bosheit der Harpyien befreit sein. Ich kann Euch nicht genug danken.", sourceObjectiveStatus = "unverified-source-field" }
quests[25655] = { id = 25655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wurmschwingenproblem", description = "Himmelsfürst Omnuron war viel zu nachgiebig mit den Harpyien der Wurmschwingen und hat ihnen sogar gestattet, sich auf diesem Berg niederzulassen. Einfach nur, weil es Wesen der Luft sind. Nun, {class}, nicht alle Wesen der Luft sind gleichrangig.\n\nAls die Angriffe auf den Hyjal begannen, verfielen die Wurmschwingen in Raserei. Sie sind direkt dort oben und greifen einen heiligen Schrein an, den sie einst verehrten.\n\nAber kein Grund zur Klage. Schließlich haben wir jetzt einen Grund, sie vom Hyjal zu vertreiben, oder?", sourceObjective = "Tötet 10 Harpyien der Wurmschwingen (Kreischerinnen oder Schnellklauen).", completion = "<Thisalee nickt zufrieden und ihre Augen leuchten.>\n\nEs ist großartig, nicht mehr an der kurzen Leine gehalten zu werden, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[25656] = { id = 25656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augen auf beim Eierklau", description = "Hinter diesen Angriffen der Wurmschwingen steckt ein Muster. Während einige Gruppen einen aufsehenerregenden Angriff auf den Schrein selbst durchführen, durchforsten andere die Nester in der Nähe und machen sich mit den Eiern aller fliegenden Wesen des Hyjal aus dem Staub.\n\nDiese Tiere stehen unter unserem Schutz. Bis wir herausgefunden haben, warum die Wurmschwingen das tun, müssen wir so viele Eier wie möglich vor ihren Klauen retten.", sourceObjective = "Sammelt 8 Hyjaleier.", progress = "<Thisalee säubert ihre Fingernägel mit einem Dolch. Sie schaut Euch erwartungsvoll an.>", completion = "Gut, das ist zumindest ein Anfang.\n\nDie Vögel, die diese Eier gelegt haben, werden sie nicht wieder annehmen. Wir werden die Küken als Waisen im Schrein aufziehen müssen. Wenn Aviana hier wäre, hätte sie diese Schandtat nie zugelassen.\n\nAber zurück zum Geschäft...", sourceObjectiveStatus = "unverified-source-field" }
quests[25657] = { id = 25657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da dap… Da dap...", description = "Da Ihr so nett zu mir wart, werde ich Euch in ein ganz besonderes Geheimnis einweihen.\n\nIch habe den größten Glitzerkram von allen gefunden, keine 50 Schritt von uns entfernt!\n\nNur eines steht noch zwischen Euch, mir und einem großen Vermögen, und das ist Nager.\n\nAber keine Sorge, ich habe einen Plan.\n\nNager liebt Maden, also habe ich eine davon mit Schießpulver gefüllt, als Falle sozusagen. Versteht Ihr?\n\nLasst sie einfach im Riff vor sich hin treiben. Sobald der Hai tot ist, sind wir reich!", sourceObjective = "Budd möchte, dass Ihr den präparierten Köder bei der rostigen Harpunenkanone im Skelettriff benutzt.", completion = "Beeindruckend!\n\nDa beobachtet man, wie die große weiße Bestie in die Tiefen davon schwimmt und fragt sich, ob es irgendetwas gibt, das ihn erledigen kann...", sourceObjectiveStatus = "unverified-source-field" }
quests[25658] = { id = 25658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Ewigkeit gebaut", description = "Herrin, ich habe eine Bitte der Hohepriesterin, die ich an Euch weitergeben soll. Viele der Verteidigungsanlagen der Stadt stammen noch aus der Zeit, lange bevor sie in den Wellen versank. Sie erneut zu aktivieren ist nicht schwer, wären da nicht die zahllosen Kvaldir, die uns im Weg sind.\n\nEs wurde uns berichtet, dass Ihr oben auf der Terrasse von Nar'shola kämpfen werdet. Ihr würdet meiner Herrin einen großen Dienst erweisen, wenn Ihr im Vorbeigehen diese Geräte einfach berühren könntet. Euer edles Geblüt sollte mehr als ausreichen, um sie zu reaktivieren.", sourceObjective = "Reaktiviert 6 Barrieren von Nar'shola.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", progress = "Die Hohepriesterin sendet Euch ihren Dank für Eure Hilfe bei unseren Pflichten.", completion = "Die Barrieren von Nar'shola funktionieren einwandfrei. Ich werde die Herrin der Gezeiten sofort über Eure Hilfe informieren.\n\nVielen Dank, edle Dame.", sourceObjectiveStatus = "unverified-source-field" }
quests[25659] = { id = 25659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unvergesslich", description = "Der Anführer der Kvaldir hat sein verrottendes, hässliches Gesicht nicht weit von hier den westlichen Gang entlang gezeigt. Wenn wir ihn jetzt töten, findet die Belagerung unserer geliebten Stadt durch die Kvaldir endlich ein Ende.\n\nVorsicht, Kriegsmaid, denn er ist alles andere als ein Schwächling. Es stehen viele Kvaldir unter seinem Befehl. Einige Meerhexen der Sira'kess wurden losgeschickt, um ihn während Eures Angriffs zu schwächen, aber wenn Ihr zulasst, dass seine Kvaldir sie angreifen, werden sie unterbrochen.\n\nZeigt keine Gnade, Kriegsmaid.", sourceObjective = "Tötet Varkul den Unerbittlichen.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", completion = "<Der General der Kvaldir bricht besiegt zusammen.>\n\n<Damit hat Lady Naz'jar die Ruinen von Vashj'ir erobert. Ihre eigentlichen Ziele kennt Ihr nicht, aber es ist klar, dass die Naga aus einem bestimmten Grund hierhergekommen sind.>\n\n<Ihr seid Euch sicher, dass der Schlüssel zum Sieg über die Naga in dieser Vision liegt. Wenn Ihr weitermachen könntet, würdet Ihr sicher die Antworten finden, aber die Magie der Wellensprecherin wird schwächer und Ihr verliert die Verbindung zur Kriegsmaid.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25660] = { id = 25660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgt", description = "Ihr meint wohl, ich lasse Euch für meinen Tod einfach so gehen, hm? Sicherlich nicht! Ich habe mein Piratenhandelsimperium mit nichts nicht aufgebaut, um Euch dabei zuzusehen, wie Ihr mich tötet.\n\nIhr werdet mir dabei helfen, wieder zum Leben zu finden. Findet meine Exfrau Ajamon im Norden des Stützpunkts. Immer der Nase nach - sie wird mit Sicherheit bei dem stinkenden Kessel sein.", sourceObjective = "Sprecht mit Ajamon Geistrufer in Südmeerstützpunkt in Tausend Nadeln.", completion = "Was wollt Ihr denn? Oh nein, ganz sicher nicht. Ich sehe, dass Ihr Tonys Geist bei Euch habt, und damit will ich wirklich nichts zu tun haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[25661] = { id = 25661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit ein bisschen Hilfe...", description = "Nun gut, ich werd' Euch helfen. So leicht wird er nicht darum kommen, mir Alimente zu zahlen! Un' außerdem muss er sich ja bald auch noch um das Kind kümmern, das er mit meiner Schwester zeugen musste!\n\nZuers' brauchen wir die Innereien seiner besten Freunde; das sind wohl die Kapitäne.\n\nGeht und stattet den drei einen Besuch ab.", sourceObjective = "Erhaltet Gruseldollys Herz, Seebär Fajardos Lungen und Lilly Landrattes Leber.", progress = "Wir brauchen ein frisches Herz, Lungen, und eine Leber. Die von seinen Kapitänen werden wohl ausreichen müssen, obwohl sie sicher nicht die frischsten sind.", completion = "<Ajamon verzieht ihr Gesicht, als sie sieht, in welchem Zustand die Organe sind.>\n\nEs geht wohl nicht anders. Ist ja nicht so, als hätte er viele Freunde gehabt. Nicht wahr, Zweihauer?", sourceObjectiveStatus = "unverified-source-field" }
quests[25662] = { id = 25662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreit unsere Schwestern", description = "Gestern Morgen habe ich eine Schwadron Jägerinnen auf eine Mission zur Scherwindklippe geschickt, damit sie Informationen über die Bewegungen der Horde im Steinkrallengebirge beschaffen. Nach Geheimdienstinformationen sind sie alle gefangen genommen worden, einschließlich der Schwadronsführerin, Jägerin Illiona.\n\nGeht nach Osten zur Scherwindklippe und tötet Infanteristen von Krom'gar, die die Klippe eingenommen haben. Nehmt ihnen die Schlüssel ab, mit denen man die Hordenkäfige, in denen unsere Schwestern sitzen, öffnen kann.\n\nTut Euer Bestes, um Illiona zu finden, sobald Ihr die Jägerinnen befreit habt.", sourceObjective = "Bringt 5 Käfigschlüssel der Horde an Euch, um 5 gefangene Jägerinnen freizulassen.", completion = "Wir haben nicht viel Zeit. Um mich hier herauszuholen, müsst Ihr Kriegsfürst Roktrog ausschalten. Er hat den Schlüssel für dieses Gefängnis.", sourceObjectiveStatus = "unverified-source-field" }
quests[25663] = { id = 25663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Gabe für Aviana", description = "Obwohl die Wächterin aller geflügelten Wesen nicht mehr körperlich unter uns weilt, höre ich sie manchmal in den rauschenden Blättern flüstern.\n\n{name}, wir verlangen viel von Euch, um diesen Berg zu beschützen. Doch bevor Ihr weitermacht, nehmt Euch einen Augenblick Zeit für die Andacht.\n\nBringt diese Nektargabe zu Avianas Grabkreis, einem Steinkreis direkt jenseits des Haupteingangs zum Schrein. Vielleicht helfen ein paar Augenblicke alleine mit der Erinnerung an Aviana Euch dabei, Euren Geist zu schärfen.", sourceObjective = "Benutzt den heiligen Nektar an Avianas Grabkreis.", progress = "<Der Geist erscheint immer wieder in Eurer Vision und verschwindet gleich darauf, als ob er hier und gleichzeitig woanders wäre.>", completion = "<Ein geflüstertes Flehen ertönt in Eurem Kopf.>\n\nWieder geboren zu werden, aber in Dunkelheit…\n\nIch wurde geraubt.\n\n<Der Geist scheint aufgewühlt, wird jedoch stumm, als das Bild wieder schwindet.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25664] = { id = 25664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gebet und ein Flügel", description = "Ein Gesicht mit Schwingen? Kann es etwa sein…?\n\n{name}, wir haben keine Zeit zu verlieren. Vielleicht habt Ihr mit Aviana selbst gesprochen, die versucht, zu uns zurückzukehren.\n\nIch benötige etwas aus Avianas Vergangenheit, um mit ihr Kontakt aufnehmen zu können. Hoch oben auf dem Gebirgskamm, der diesen Schrein überblickt, findet Ihr eine Reihe von riesigen Nestern. Sie gehören Blaithe, einem uralten Raubvogel, der einst ihr Gefährte war. Seit zehntausend Jahren vergeht er vor Kummer und hat dadurch seinen Verstand verloren.\n\nKlettert auf einen seiner Horste und benutzt diesen Lockruf, um ihn herbeizurufen. Tötet Blaithe und bringt mir eine seiner Federn.", sourceObjective = "Benutzt den riesigen Vogellockruf an einem von Blaithes Nestern oben am Rand der Welt. Tötet Blaithe und sammelt eine seiner uralten Federn.", progress = "Habt kein schlechtes Gewissen wegen Blaithes Verfassung. Der Kummer hat diesem Wesen vor Jahrhunderten die Seele geraubt. Er war nur noch ein Schatten seiner selbst, eine Bestie voll zügellosen Zorns.", completion = "Das war keine schöne Aufgabe, {name}, aber sie musste erledigt werden.\n\nWenn Aviana wirklich wieder zum Leben erweckt werden kann, kann Blaithe vielleicht eines Tages Dank Eurer Taten auch zurückkehren.\n\nUnd jetzt lasst uns sehen, ob wir mit unserer lange verlorenen Wächterin Kontakt aufnehmen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[25665] = { id = 25665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gesuch aus dem Jenseits", description = "<Ihr versteht nicht, worum der Geist Euch so dringend anfleht, aber vielleicht kann Choluna ja herausfinden, was hier vor sich geht.>\n\n<Sprecht mit Choluna innerhalb des Schreins!>", sourceObjective = "Kehrt zu Choluna im Schrein von Aviana auf dem Hyjal zurück.", completion = "Langsam, {class}! Ihr seht aus, als hättet Ihr einen Geist gesehen…", sourceObjectiveStatus = "unverified-source-field" }
quests[25666] = { id = 25666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht Euch die Hände schmutzig", description = "Lasst Euch nicht täuschen, {race}. Dieser Hai ist ganz schön gewitzt. Man überlebt hier unten nicht so lange, wenn man nicht das gewisse Etwas an Grips hat.\n\nIch will damit nur sagen, dass er sich sicher nicht so leicht reinlegen lässt. Wir müssen unseren Ansatz ein wenig überdenken.\n\nIch werde Euch jetzt noch nicht mit Details langweilen. Sammelt zunächst ein paar Innereien von diesen gigantischen Meeresraupen.\n\nMeint Ihr, Ihr schafft das?", sourceObjective = "Sammelt 5 schmierige Madeneingeweide von gigantischen Meeresraupen in der Nähe von Harrisons Ausgrabung.", sourceObjectiveStatus = "unverified-source-field" }
quests[25667] = { id = 25667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wendigos erlegen", description = "Die Wendigos im Graufelsbau südwestlich der Stadt sind uns schon lange ein Dorn im Auge. Ihre Kraft reicht zwar nicht aus, Kharanos direkt zu bedrohen, aber sie stellen Reisenden, Gebirgsjägerpatrouillen und Nachschubtransporten nach.\n\nIch werde meine Beobachter aus dem Graufelsbau abziehen, da ich sie an der Trollfront brauche. Würde es Euch etwas ausmachen, meinen Leuten bei der Verkleinerung des Wendigobestands zu helfen? Wenn sie nicht mehr so viele sind, können sie uns nicht länger angreifen.", sourceObjective = "Tötet 10 Wendigos im Graufelsbau. Ihr könnt Wendigos oder junge Wendigos töten.", completion = "Jetzt, da Ihr Euch um die Wendigos gekümmert habt, können wir unsere Bemühungen auf die Trolle der Frostmähnen im Osten konzentrieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[25668] = { id = 25668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlene Vorräte", description = "Die Frostmähnen machen im Osten Ärger und die Wendigos spüren unsere Schwäche und werden mit ihren Überfällen immer dreister. Nur einer von vier Nachschubkarren ist in letzter Zeit hier sicher angekommen. Die Wendigos haben sich mit dem Rest davongemacht und bewahren alles im Graufelsbau, einer Höhle südwestlich von hier, auf. Wenn Ihr bereit seid, dorthin zu gehen und die gestohlenen Vorräte wiederzubeschaffen, wären Euch alle Einwohner der Stadt und die Gebirgsjäger, die Kharanos verteidigen, zutiefst dankbar.", sourceObjective = "Bergt 6 gestohlene Versorgungsgüter aus dem Graufelsbau.", progress = "Habt Ihr etwas von den vermissten Vorräten gefunden?", completion = "Gut gemacht, {name}. Die Gebirgsjäger werden froh sein zu hören, dass die halben Rationen der Vergangenheit angehören. Sie benötigen all ihre Kräfte, um gegen die Frostmähnen zu kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25669] = { id = 25669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es rappelt im Säge... Werk", description = "Seid bereit, {name}! Der Kriegsfürst kommt! Tötet ihn und nehmt seinen Schlüssel an Euch. Benutzt diesen Schlüssel, um mich freizulassen.\n\nWenn wir es hier heraus schaffen, meldet das Folgende bei Lord Brachweiher in der Scherwindfeste:\n\nDie Horde hat ihre Pläne, die Scherwindfeste zu zerstören, dank der Taten eines unserer Helden abgebrochen. Jetzt beabsichtigen sie, die Bombe zum Kriegsnarbental zu bringen und auf unsere Armeen abzuwerfen, die dort gegen die Horde kämpfen.\n\nSie müssen aufgehalten werden!", sourceObjective = "Tötet Kriegsfürst Roktrog und befreit Jägerin Illiona, indem Ihr Jägerin Illionas Käfigschlüssel benutzt.", completion = "Ein Held hat also ihre Pläne vereitelt, die Scherwindfeste zu zerstören, huh? Der Held wart Ihr, {name}. Ihr seid der Stolz der Allianz!\n\nAnscheinend habt Ihr uns allen ein wenig Zeit verschafft. Ich muss Pläne schmieden für den Kampf, der vor uns liegt. Geht zu den anderen Einwohnern der Scherwindfeste und bietet ihnen Eure Dienste an. Ich werde Euch rufen, wenn ich bereit bin, unsere Verteidigungsstrategie ins Leben zu rufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25670] = { id = 25670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DA-dap-DA-dap-DA-dap", description = "Der alte Nager ist uns jetzt sicher auf den Fersen.\n\nZu Eurem Glück denke ich wie ein Hai.\n\nNager kocht vor Zorn und wir werden das zu unserem Vorteil nutzen.\n\nHier, ich habe auf meiner Schatzjagd diese Kette gefunden. Bindet sie an die Harpunenkanone.\n\nWenn Nager Euch sieht, wird er bestimmt vor Wut überschnappen. Und dann schlagen wir zu!\n\nIhr versucht, ihn alle zu machen und ich schleiche mich währenddessen dort hinein und schnappe mir den Glitzerkram.\n\nSchnell, {class}, bevor seine Zähne wieder nachwachsen!", sourceObjective = "Benutzt Budds Kette bei der rostigen Harpunenkanone im Skelettriff. Feuert die Harpune ab, wenn Nager sich über der Kanone befindet.", completion = "Es ist wirklich nicht so schlimm, wie es aussieht…", sourceObjectiveStatus = "unverified-source-field" }
quests[25671] = { id = 25671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde ausdünnen", description = "Die Zahl der Horde wächst, da Verstärkung aus dem Eschental und aus Azshara eintrifft. Diplomatie bringt bei diesen Unholden nichts. Das ist Höllschreis Horde und Höllschreis Horde will unser Blut! Wir werden nicht untätig herumsitzen und zulassen, dass sie unser Land einnehmen und unsere Leute töten. Wir müssen handeln!\n\nWir müssen die Horde ausdünnen! Betrachtet das als Eure tägliche Pflicht.\n\nGeht hinaus ins Steinkrallengebirge und tötet so viele Hordemitglieder, wie Ihr könnt. Zeigt ihnen, dass die Allianz sich nicht ergeben wird!", sourceObjective = "Tötet 20 beliebige Soldaten der Horde im Steinkrallengebirge.", completion = "Gut. Ihr Blut klebt an Höllschreis Händen. Schickt genug von ihnen in Leichensäcken zurück nach Orgrimmar und die Bevölkerung der Horde wird vielleicht reagieren.\n\n<Lord Brachweiher lacht.>\n\nWem will ich etwas vormachen? Sie sind Monster!", sourceObjectiveStatus = "unverified-source-field" }
quests[25672] = { id = 25672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kadaversammlung", description = "Diese Organe hier sind schon mal ein guter Anfang, aber wir brauchen echt noch viel mehr anderes Zeugs. Normalerweise könnte man von der Familie was nehmen, aber es sind nur noch ich und Tony, der Sohn meiner Schwester übrig, und er ist es echt nicht wert!\n\nWir müssen also 'n Ersatz finden - 'ne Menge Kadaver, um genau zu sein!\n\nUnten in der Schimmernden Tiefe sind tonnenweise welche zu finden; die sind da, seit das Wasser alles überflutet hat. Hat alle Kreaturen dort getötet, das Wasser. Geht dorthin und bringt mir ein paar der Kadaver.", sourceObjective = "Sammelt 10 Kreaturenkadaver.", progress = "Mensch, Ihr müsst mir end viele von den Kadavern bringen! Sonst werden wir seinen törichten Geist nie loswerden!", completion = "Oh, das is' widerlich!\n\nAber wenigstens haben wir's bald. Nur noch eine Kleinigkeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[25673] = { id = 25673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfach Alice fragen", description = "Herr Baunzer ist krank, <Onkel/Tante>. Kannst du ihm helfen? Du musst nur seinen Hut und seine Batterien finden, dann wird es ihm viel besser gehen. Ich würde sie ja selbst holen, aber ich kann Herrn Baunzer nicht alleine lassen!\n\nSein Hut wurde von den fiesen Typen der Venture Co. drüben am Wasserrad gestohlen und seine Batterien sind irgendwo in der Scherwindklippe versteckt. Du musst nur sehr gründlich nach ihnen suchen.\n\nWürdest du freundlicherweise Herrn Baunzers Sachen zurückholen, damit er den Fieslingen in der Horde eine Lektion erteilen kann?", sourceObjective = "Findet die BD-816 Kriegsmaschine, mechanisiertes Feuer, mechanisiertes Eis und mechanisierte Luft.", progress = "Herr Baunzer ist so traurig. Wir müssen ihn glücklich machen!", completion = "<Alice klatscht aufgeregt in die Hände.>\n\nHerr Baunzer, alles wird wieder gut! Hurrah!\n\n<Alice setzt fachmännisch alle Teile, die Ihr eingesammelt habt, in Baunzer ein.>\n\nOh, Herr Baunzer! Ich wusste es!", sourceObjectiveStatus = "unverified-source-field" }
quests[25674] = { id = 25674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergebener Stolz", description = "Dies hier ist eigentlich eine alte Orcstadt... eine der ältesten in Azeroth. Also, das war sie - bis die Oger uns hinausgedrängt haben.\n\nDie heutige Horde weigert sich, von Ogern besiegt zu werden. Meine Truppen und ich haben die Stadt mit Gewalt eingenommen und die Oger, die einmal hier gelebt haben, arbeiten jetzt als Sklaven. Jetzt fängt die Arbeit erst richtig an.\n\nIhr seht stark genug aus, aber ich will Beweise. Tötet einen der Oger, die uns immer noch belagern und kehrt zu mir zurück.", sourceObjective = "Tötet einen Wegelagerer der Schreckensfelsoger in der Feste Schreckensfels.", completion = "Gut gemacht, {race}. Ihr habt bewiesen, dass Ihr einen Oger niederstrecken könnt...eine beachtliche Leistung. Jetzt lasst uns doch mal sehen, ob Ihr eine Eisenmine der Allianz ebenfalls ausschalten könnt...", sourceObjectiveStatus = "unverified-source-field" }
quests[25675] = { id = 25675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogergefechte", description = "Ich habe Eure Handschrift da unten gesehen, {race}. Wie würde es Euch gefallen, noch weitere Oger zu jagen?\n\nWir haben nur diejenigen versklavt, derer wir habhaft werden konnten. Die meisten starken Oger brüten immer noch im Schreckensfelsposten und planen unser Ableben. Unsere Wachen können vereinzelte Angriffe aus dem Hinterhalt abwehren, aber wir haben uns noch nicht gut genug verschanzt und würden unter einem gut geführten Angriff schnell zusammenbrechen.\n\nGeht nach Süden zum Schreckensfelsposten und überbringt eine Nachricht, {name}. Tötet die stärksten Oger, bevor sie auf dumme Gedanken kommen.", sourceObjective = "Tötet 6 Raufer der Schreckensfelsoger und 5 Hexenmeister der Schreckensfelsoger.", completion = "Ihr habt Eure Sache heute gut gemacht, {name}. Ihr habt uns nicht nur Zeit bis zum nächsten Ogerangriff verschafft, sondern auch einige der Gefangenen eingeschüchtert, sodass sie jetzt härter arbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25676] = { id = 25676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitten ins Herz", description = "Wir haben keine Hoffnung, die Mine von Nethergarde von der Allianz zurückerobern zu können... wenigstens noch nicht. Nethergarde wird gut verteidigt und ihre Nachschubrouten sind bewährt und stark. Unser Ziel ist es daher, ihrer Wirtschaft zu schaden. Wir können die Mine nicht mit Gewalt einnehmen, aber mit präzisen Einschnitten können wir die Wirtschaftlichkeit der Mine stark einschränken.\n\nIch werde dafür sorgen, dass meine Leute vor der Mine ein Ablenkungsmanöver ausführen. Geht nach Osten, schleicht Euch in die Mine und sprecht mit Rofilian Dane über Eure Rolle.", sourceObjective = "Meldet Euch bei Rofilian Dane in der Mine von Nethergarde in den Verwüsteten Landen.", completion = "Endlich lässt sich hier mal ein Verantwortlicher blicken. Ich hoffe, Ihr habt Euch locker gemacht... Zeit für ein kleines Tänzchen, Partner.", sourceObjectiveStatus = "unverified-source-field" }
quests[25677] = { id = 25677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles meins!", description = "Überall in dieser Höhle findet Ihr unbewachte Erzhaufen, die nur darauf warten, dass man an ihnen herumpfuscht. Am liebsten würden wir das Erz natürlich stehlen, aber dazu benötigt man Minenwagen, Schutz und Arbeiter - drei Dinge, die wir nicht haben. Also werden wir stattdessen die Schürfarbeiten mit ein wenig hochgradig ätzender Säure vereiteln.\n\nNehmt diese Flasche - VORSICHTIG - und träufelt den Inhalt auf diese Erzhaufen. Denn wenn wir das Erz nicht haben können, sollen sie es auch nicht haben.", sourceObjective = "Benutzt das konzentrierte Lösemittel auf 6 Erzhaufen in der Mine von Nethergarde.", completion = "Es gibt doch nichts Besseres, als einen richtig fetten Tritt in die Geldbörse, nicht wahr, ihr Allianzdummköpfe?!", sourceObjectiveStatus = "unverified-source-field" }
quests[25678] = { id = 25678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wählt Euer Schicksal", description = "Es kostet die Allianz ungefähr fünfzig Goldstücke, einen Minenarbeiter auszubilden, zweihundert, um einen Ingenieur auszubilden und dreihundert für einen Vorarbeiter. Jeder Allianzdummkopf, den wir töten ist nicht nur ein militärischer Sieg, es ist auch ein finanzieller Sieg.\n\nJetzt geht dort hinunter und vernichtet ihre Arbeiter!", sourceObjective = "Tötet 8 Minenarbeiter von Nethergarde, 3 Ingenieure von Nethergarde und 3 Großknechte von Nethergarde.", completion = "Hervorragende Arbeit Mir gefällt, wie Ihr an die Dinge herangeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25679] = { id = 25679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Berg hinein", description = "Die nächste Phase findet an einem noch tiefer gelegenen Ort in der Mine statt. Sprecht mit Tak'arili für Eure nächste Aufgabe. Folgt einfach den Schienen der Minenwagen nach Südosten um die Kurve herum. Ihr werdet ihn am Eingang zu den höher gelegenen Kammern der Mine sehen.\n\nEs war mir ein Vergnügen, mit Euch Geschäfte zu machen, {name}", sourceObjective = "Meldet Euch bei Tak'arili tiefer in der Mine von Nethergarde in den Verwüsteten Landen.", completion = "Gut, Ihr seid schon hier. Bleibt eine Weile, kleiner {race}. Wir werden mit der Allianz ein paar Spielchen treiben.\n\nIch liebe meinen Job, Mann.", sourceObjectiveStatus = "unverified-source-field" }
quests[25680] = { id = 25680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So sind wir nicht", description = "Das Wichtigste zuerst... sieht so aus, als ob wir ein Problem hätten. Die Minenarbeiter in dem Stollen rechts laufen herum wie ein Haufen aufgescheuchter, kopfloser Hühner. Ich kann nur vermuten, dass sie zu tief gegraben und etwas Unschönes gefunden haben... einen Dämon, ein Elementar oder irgendein Tentakelbiest.\n\nTak'arili mag keine Überraschungen. Findet heraus, was das Problem ist und kümmert Euch darum, dann können wir wie geplant weitermachen.", sourceObjective = "Findet und tötet das, was die Minenarbeiter in der Mine von Nethergarde so erschreckt hat.", completion = "Also war es ein Dämon? Diese Minenarbeiter haben noch nie einen Dämonen gesehen? Wir sind in den Verwüstete Landen, Mann! Dämonen sind überall!\n\n<Tak'arili seufzt.>\n\nNaja... wenden wir uns dem guten Zeug zu, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[25681] = { id = 25681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einige Leute muss man einfach töten", description = "Wenn Ihr durch den Tunnel vor uns geht, der nach Westen führt, kommt Ihr direkt zum Büro von Chefausgrabungsleiter Hondo. Er ist hier der Obermotz und Tak'arili hat gehört, dass er ein richtig guter Minenarbeiter ist. Deshalb muss er sterben.\n\nEs gibt nur ein Problem: der Weg dorthin ist VOLL mit diesen lästigen Lakaien aus Nethergarde. Deshalb müsst Ihr Euch verkleiden. Hüpft in diese Kiste hier und schleicht Euch den Weg hinunter. Hoffentlich erregt Ihr nicht zu viel Verdacht auf dem Weg zu Eurem Opfer.", sourceObjective = "Tötet Chefausgrabungsleiter Hondo. Benutzt die unverdächtige Kiste, um Euch unterwegs zu tarnen.", completion = "Gute Arbeit, Mann! Ohne Hondo sind die Jungs hilflos. Die Mine wird schon bald uns gehören!", sourceObjectiveStatus = "unverified-source-field" }
quests[25682] = { id = 25682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission abgeschlossen", description = "Wir sind hier fertig, Mann. Wir müssen nur noch einen Bericht an Okrilla schicken. Habt Ihr gerade etwas vor?", sourceObjective = "Liefert den Minenbericht von Nethergarde bei Okrilla in der Feste Schreckensfels in den Verwüsteten Landen ab.", progress = "Ihr seid zurückgekehrt, {name}?", completion = "<Okrilla überfliegt den Bericht.>\n\nBeeindruckend, {name}. Ich hätte mich zwar nicht in dieser Kiste versteckt, aber sonst habt Ihr Eure Sache tapfer und bewundernswert gemacht. Die Schlacht, die wir heute gewonnen haben, wird uns nicht unmittelbar zugutekommen, aber der Schaden, den Ihr der Allianz zugefügt habt, wird über lange Zeit anhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25683] = { id = 25683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schreckensfelssenke", description = "Ich meinte das, was ich gesagt habe, {race}. Ihr habt mir geholfen, jetzt gebe ich weiter, was ich weiß.\n\nVor Kurzem machte ein Dämonenjäger kurz hier Halt. Er ging nach Süden und sprach von Dämonen. Eigentlich hätte ich den Nachtelfen sofort getötet, aber er schien nicht der übliche Allianzabschaum zu sein und jeder, der Dämonen tötet, ist in dem Moment nützlich für mich.\n\nIhr solltet Euch bei Lynnore und Drazial melden, zwei Blutmagier, die ich in die Richtung entsandt habe. Sie haben ihr Lager hinten in einer Ogerhöhle aufgeschlagen.", sourceObjective = "Meldet Euch bei Blutmagierin Lynnore hinten in der Schreckensfelssenke in den Verwüsteten Landen.", completion = "Okrilla hat Euch geschickt? Okrilla da Killa?\n\n<Lynnore hört sich Eure Geschichte an.>\n\nEr hieß Loramus? Es tut mir leid, aber wir haben Euren Dämonenjäger nicht gesehen... Aber wir haben Möglichkeiten, ihn zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25684] = { id = 25684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stimmt den Blutstein ab", description = "Ich gebe zu, dass wir nicht gerade den... vorteilhaftesten Ort für unsere Studien ausgewählt haben, besonders, wenn vorüberziehende Abenteurer den Wunsch haben, unbehelligt einzutreten und wieder hinauszugehen. Unsere Übereinkunft mit den Ogern ist recht wackelig und ich fürchte, wir können sie nicht dazu bewegen, Euch nicht anzugreifen, wenn Ihr Euch nähert.\n\nIch kann Euch allerdings gestatten, Euch mit einem der Blutsteinteleporter zu verbinden. Legt einfach Eure Hände auf den Stein zu meiner Rechten und Ihr werdet aus der Höhle herausteleportiert. Dann benutzt den Stein draußen, um wieder hereinzuteleportieren!", sourceObjective = "Verbindet Euch mit den Blutsteinteleportern in der Schreckensfelssenke.", progress = "Der Verbindungsvorgang ist einfach, und er wird sich ganz bestimmt auf die Dauer bezahlt machen.", completion = "Ausgezeichnet. Jetzt, da das aus dem Weg ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[25685] = { id = 25685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der erste Schritt", description = "Damit wir das Ritual, um das Ihr gebeten habt, durchführen können - und vielleicht noch weitere Rituale in Zukunft - benötigen wir Blut. Die Verwüsteten Lande sind voller Reagenzien, die wir für unsere Blutmagie brauchen... es ist nur eine Frage der richtigen Zusammenstellung.\n\n<Lynnore berät sich schnell und kurz mit Drazial.>\n\nBasilisken und Hyänen, zu gleichen Teilen. Und wir benötigen viel davon. Geht nach Osten ins Zentrum der Verwüsteten Lande. Und vergesst nicht - Ihr könnt den Teleporter benutzen!", sourceObjective = "Besorgt 9 Phiolen mit Blut einer Kicherfanghyäne und 9 Phiolen mit Blut eines Rotsteinbasilisken.", progress = "Mit Ogerblut kommt man nicht sehr weit. Habt Ihr es?", completion = "<Lynnore beäugt das Blut hungrig.>\n\nMehr als genug - und immer noch warm! Dann lasst uns das Ritual beginnen, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[25686] = { id = 25686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutritual", description = "Unser Ziel ist es, den Dämonenjäger Loramus Thalipedes zu finden. Lasst mich wissen, wenn Ihr bereit seid, das Blutritual zu beginnen. Dann zieht Euch einen Schritt zurück.", sourceObjective = "Sprecht mit Blutmagierin Lynnore, um das Blutritual zu beginnen.", progress = "Das Ritual ist noch nicht abgeschlossen.", completion = "Das Blutritual war ein voller Erfolg - ich kann ganz deutlich sehen, wo Loramus sich in diesem Moment befindet. Das heißt, ich kann sehen, wo seine Leichenteile sich befinden...", sourceObjectiveStatus = "unverified-source-field" }
quests[25687] = { id = 25687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht irgendeine Leiche", description = "Loramus Thalipedes ist tot. Nun, das nehme ich zurück... das ist nur eine Annahme meinerseits, aber ich weiß, dass sein Körper in drei Teilen ruht.\n\n<Lynnore denkt kurz nach.>\n\nWenn Ihr mir die drei Teile bringt, haben wir noch eine Chance. Alle drei Teile sind in der Nähe... die Schreckensfelsoger haben sie in ihren Höhlen versteckt. Um genau zu sein ist ein Teil in der Truhe, den Vorsprung hinter mir hinunter...", sourceObjective = "Findet Loramus' Kopf, Loramus' Torso und Loramus' Beine.", progress = "Vertraut mir - egal, was mit Loramus geschehen ist, wir können es beheben. Die Grenzen der Blutmagie sind bisher noch nicht ausgelotet.", completion = "Ich verstehe...ja, damit können wir arbeiten.\n\n<Lynnore schaut auf den Kopf des Nachtelfen.>\n\nLoramus Thalipedes, Dämonenjäger. Ich freue mich darauf, Euch kennenzulernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25688] = { id = 25688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Altar der Stürme", description = "Oben auf den Klippen über unserer gemütlichen Höhle befindet sich ein mächtiger Altar. Ein mächtiger DÄMONISCHER Altar, der von Kultisten bewacht wird, aber dennoch sehr große Kräfte birgt. Wenn Ihr es schafft, ihn zu erreichen, könnt Ihr damit Loramus zu uns zurückbringen.\n\nDer Altar wird wahrscheinlich Euren Bemühungen widerstehen, also müsst Ihr Loramus' Leichnam während des Rituals beschützen. Bringt den Dämonenjäger hinterher zu mir zurück.", sourceObjective = "Bringt Loramus' Leichnam zum Altar der Stürme, dann beschützt ihn während des Rituals.", completion = "Ihr... Ihr seid ein Narr! Was habt Ihr getan?", sourceObjectiveStatus = "unverified-source-field" }
quests[25689] = { id = 25689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zeit ist knapp", description = "Ich jagte einen Dämonen mit Namen Razelikh. Grol, sein Ogerhauptmann, griff mich an. Er hat mich auf dem falschen Fuß erwischt und ich starb - genau wie Grol.\n\nRazelikh hat vor, in die Verwüsteten Lande zurückzukehren und sie mit seinen Dämonen zu überwältigen. Sogar jetzt bereitet er sich darauf vor, seine Legionen zusammenzurufen, damit sie uns auslöschen.\n\n<Der Dämonenjäger zieht schnell eine Rune hervor und übergibt sie Euch.>\n\nBringt das hier zu Wazzik am Dunklen Portal im Südosten. Er wird Euch führen. Schnell! Wir haben nicht viel Zeit!", sourceObjective = "Bringt die disharmonische Rune zu Behüter Wazzik am Dunklen Portal in den Verwüsteten Landen.", progress = "Kenne ich Euch, guter {race}??", completion = "Wie bitte? LORAMUS?!\n\nOh verflixt, sprecht leise, ja? Wenn mein Boss herausfindet, dass ich für Loramus gearbeitet habe, wisst Ihr, wie schnell ich dann auf meinen vier Buchstaben lande?\n\n<Wazzik nimmt Euch die Rune ab, drückt sie gegen seine Brust, schließt seine Augen und nickt.>\n\nNun, Ihr habt nicht gelogen. An die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25690] = { id = 25690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auch Blutmagier müssen essen", description = "Entgegen dem allgemeinen Irrglauben trinken Blutelfen Blutmagier KEIN Blut. Wir essen normale Speisen wie jeder andere auch - etwas, das in der hintersten Ecke einer Ogerfeste schwierig zu bekommen ist.\n\nDie Aschmähneneber im zentralen Tal der Verwüsteten Lande sind zumindest ohne Weiteres essbar, da man ihr Fleisch nicht kochen muss. Würdet Ihr diese Eber jagen und unsere Nahrungsvorräte wieder aufstocken?", sourceObjective = "Besorgt 5 Aschmähnensteaks von Aschmähnenebern in den Verwüsteten Landen.", progress = "Ich bin ausgehungert! Wenn Ihr Euch nicht beeilt, sehe ich mich noch gezwungen, unsere Reagenzien zu trinken.", completion = "Die sind perfekt, {name}. Lynnore und ich werden in den nächsten Tagen gut zu essen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25691] = { id = 25691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verkohlte Granit des Dunklen Portals", description = "Loramus will, dass wir - äh, IHR - Granitsplitter aus den Felsbrocken um das Dunkle Portal herum sammelt. Ich weiß nicht, wofür er die Steine braucht, aber ich habe da so meinen Verdacht und der ist nicht angenehm.\n\nBenutzt diese Spitzhacke und sucht nach kleinen, zutage getretenen Steinen am Rand des Explosionskraters um das Portal.", sourceObjective = "Besorgt 24 verkohlte Granitsplitter.", progress = "Sprecht leise, ja?", completion = "Ich hoffe, das ist es, was er braucht. Wir haben wahrscheinlich nicht mehr die Zeit, dass Ihr noch einmal zurückkehrt und noch mehr schürft.", sourceObjectiveStatus = "unverified-source-field" }
quests[25692] = { id = 25692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das abscheuliche Blut der Dämonen", description = "Thalipedes möchte mehr Blut. Für mich persönlich sieht das Zeug nicht einmal aus wie Blut - eher wie flüssige Verwesung - aber das ist ohne Belang.\n\nZum Glück für Euch ist das Gebiet um das Dunkle Portal voller Dämonen. Höllenbestien, Teufelshunde und Teufelswachen - sie alle haben das, was Ihr benötigt in reichlichen Mengen.", sourceObjective = "Besorgt 7 Flaschen mit abscheulichem Dämonenblut.", progress = "Uff, was stinkt hier so? Seid Ihr das, oder das Blut?", completion = "Ihr habt ohne jeden Zweifel Dämonenblut gefunden.\n\nVon Loramus' Bitte einmal abgesehen, bin ich sicher, dass Dar'toon für Eure Bemühungen sehr dankbar ist. Sie haben schon seit einiger Zeit Schwierigkeiten, mit diesen Ablenkungen der Dämonen zurechtzukommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25693] = { id = 25693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbesserung des Steins", description = "<Wazzik packt die letzten Materialien in ein ordentlich umwickeltes Päckchen.>\n\nDas ist alles, was Loramus von uns verlangt hat. Wenn Ihr ihn seht, denkt daran, ihm zu sagen, dass ich eine große Hilfe war. Ich fürchte, er wird meinen Anteil hieran nicht erkennen.", sourceObjective = "Bringt Wazziks Paket zu Loramus Thalipedes in der Schreckensfelssenke in den Verwüsteten Landen.", progress = "{class}... Ihr kehrt zurück...", completion = "Das reicht. Wenn Ihr Wazzik noch einmal seht, sagt ihm, dass er befriedigend gearbeitet hat. Ich werde dafür sorgen, dass die Blutmagier sich an die Arbeit machen und das Steinmesser des Versiegelns herstellen. Jetzt sind Fragen unnötig. Alles wird sich zu seiner Zeit klären.\n\nSolange sie arbeiten, habe ich eine andere Aufgabe für Euch zu erledigen. Um genau zu sein sind es drei Aufgaben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25694] = { id = 25694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückendeckung", description = "Den einzigen Grund, warum Ihr mich neben Soldaten der Allianz stehen seht, ist der, dass unsere Pflicht unsere Feindschaft überwiegt - und sei es noch so gering. Man hat uns die Aufgabe übertragen, das Dunkle Portal vor unerwünschten Reisenden zu schützen. Der kürzlich aufgetretene Kataklysmus hat uns besonders verwundbar für Angriffe gemacht. Wir haben bereits Berichte über schwarze Drachen in der Gegend gehört...\n\nDa meine Leute sich auf ihre Pflichten konzentrieren müssen, brauchen wir jemanden, der die Dämonen im Zaum hält. Um das Portal herum werdet Ihr drei Hauptleute der Dämonen finden. Tötet sie.", sourceObjective = "Tötet Jarroc Flügelriss, Shahandana und Gomegaz.", completion = "Wir wissen Eure Arbeit zu schätzen, Soldat.\n\n<Der Kriegsfürst lehnt sich zu Euch hinüber und flüstert:>\n\n{race}, wenn Ihr noch interessiert seid, ich habe noch eine kleine Aufgabe für Euch...", sourceObjectiveStatus = "unverified-source-field" }
quests[25695] = { id = 25695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachhut", description = "<Kriegsherr Dar'toon spricht sehr leise.>\n\nIch habe Befehle von... oben... für die Ihr genau der Richtige seid. Ich habe gesehen, dass die Allianz regelmäßig einen Blick in den Stapel Papiere dort auf dem Fass wirft. Ich möchte, dass Ihr Euch diese Papiere anschaut und herausfindet, was sie vorhaben. Meine Pflicht und mein Posten erlauben mir nicht, solch eine fragwürdige Aufgabe durchzuführen - aber Ihr seid ein Neuankömmling und könntet unbemerkt hineinschlüpfen...", sourceObjective = "Untersucht die Pläne der Allianz am Dunklen Portal, ohne erwischt zu werden.", completion = "Ihr seid sicher, dass Euch niemand beobachtet hat? Gut.\n\n<Dar'toon hört aufmerksam Eurem Bericht über die Informationen, die Ihr gesehen habt, zu.>\n\nHmpf... das ist ziemlich harmloses Zeugs. Entweder ist die Allianz dumm genug, NICHTS gegen uns unternehmen zu wollen... oder sie verstecken ihre Informationen besser, als ich erwartet habe. Wie auch immer - gut gemacht, Soldat.", sourceObjectiveStatus = "unverified-source-field" }
quests[25696] = { id = 25696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonnenschleiers Exkursionstrupp", description = "Ach richtig – ich habe vor ein paar Tagen eine Nachricht von jemandem erhalten. Das archäologische Institut oder so ähnlich? Sie suchen jemanden, der... etwas tun soll...\n\n<Der Kriegsherr durchwühlt einige Papiere.>\n\nAh, hier ist es! Ja, Rohan Sonnenschleier vom archäologischen Institut sucht fähige Abenteurer, die ihm bei einer archäologischen Expedition in den Süden helfen sollen.\n\nHier, nehmt das mit. Warum geht Ihr nicht und sprecht mit dem Elfen?", sourceObjective = "Meldet Euch bei Rohan Sonnenschleier bei Sonnenschleiers Exkursionstrupp in den Verwüsteten Landen.\n\nBereitgestellter Gegenstand:", completion = "Willkommen, Reisender. Danke, dass Ihr Euch auf meinen Aufruf hin gemeldet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25697] = { id = 25697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Amulett von Allistarj", description = "Als mein Meister mir half, meine Augen herauszunehmen, gab er mir das Geschenk der Sicht - einer Sicht, die weit besser ist, als Eure oder die dieser blutsüchtigen Elfen. Meine Sicht erlaubt mir, Gegenstände mit dämonischer Macht zu sehen, so wie das Amulett von Allistarj.\n\nAllistarj selbst ist tot, aber er hat sein Amulett in einer Schatzgrube in der Schlangenschlinge im Osten eingeschlossen. Zusammen mit anderen Amuletten wird dieses Relikt uns Zugang zu Razelikhs Behausung verschaffen.", sourceObjective = "Besorgt das Amulett von Allistarj aus der Schlangenschlinge in den Verwüsteten Landen.", progress = "Alistarj hat einen Teil seiner selbst in dem Amulett hinterlassen. Sogar jetzt kann ich seine Bosheit spüren.", completion = "<Lynnore untersucht das Amulett.>\n\nEr war ein Erzmagier, das spüre ich. Ich werde das Amulett für Euch aufbewahren, während Ihr die anderen sucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25698] = { id = 25698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Amulett von Sevine", description = "Das Amulett von Sevine befindet sich weit im Osten in Händen eines Murlocs, auf einer Klippe mit Ausblick über die Havarieküste. Wie es in den Besitz dieses Murlocs gelangt ist, entzieht sich meiner Kenntnis, aber ich kann mit Sicherheit sagen, dass Ihr es dort finden werdet.\n\nIch fühle eine stärkere Verbindung mit Sevine als mit den anderen Dienern Razelikhs - möglicherweise, weil sie den Altar der Stürme erbaut hat, auf dem Ihr mich wiederbelebt habt. Bringt ihr Amulett mit den anderen zu Lynnore.", sourceObjective = "Besorgt das Amulett von Sevine von Salzflopper in den Verwüsteten Landen.", progress = "Sevines Amulett - zusammen mit den anderen können wir die Anhöhe des Entweihers erreichen.", completion = "<Lynnore wiegt das Amulett in der Hand.>\n\nEin Kriegsherr... und ein mächtiger noch dazu. Ich werde das hier behalten, bis die Zeit reif ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25699] = { id = 25699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Amulett von Grol", description = "Grol - der Oger, der mich auseinandergerissen hat.\n\n<Loramus lacht.>\n\nOffensichtlich ist Grols Leichnam durch mehrere Hände gegangen, seit wir zusammen gestorben sind, aber er ist nicht länger bei den Ogern. Seine Leiche ist zusammen mit seinem Amulett der Macht in einem Schiffswrack vor der Havarieküste im Osten. Sein Amulett ist das letzte - sobald sie vereint sind, werden die drei uns Zugang zu Razelikh gewähren und darin liegt unsere Chance, diesen Wahnsinn zu beenden.", sourceObjective = "Besorgt das Amulett von Grol von der Havarieküste in den Verwüsteten Landen.", progress = "Das dritte Amulett von Razelikhs drittem Hauptmann.", completion = "<Lynnore umklammert das Amulett.>\n\nEr war ein mächtiger Krieger. Ich werde das Amulett behalten, bis Loramus bereit ist, fortzufahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[25700] = { id = 25700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loramus Thalipedes wartet", description = "Die Verzauberung auf diesen Amuletten war nicht besonders kompliziert. Zusammengefügt wird ihre Macht Euch Zugang zu Razelikh, dem Erschaffer des Amuletts, verschaffen.\n\nIch bin bereit, dieses Ritual für Euch und Loramus durchzuführen. Sprecht noch einmal mit mir, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Blutmagierin Lynnore, um an ihrem Ritual teilzunehmen.", completion = "Wie es aussieht, sind wir bereit, uns unserem Dämonen zu stellen, {name}. Wir haben den Segen des Amuletts, wir haben das Steinmesser und ich allein weiß den wahren Namen des Dämonen: Rakh'likh. Zusammen könnte das genügen, den Entweiher zu besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25701] = { id = 25701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr seid Rakh'likh, Dämon", description = "Held, hört gut zu.\n\nZunächst müssen wir nach Nordosten zum tödlichen Pförtner reisen, der auf uns am nördlichen Fuß der Anhöhe des Entweihers wartet. Der Pförtner wird uns dann oben auf die Anhöhe schicken. Sobald wir dort sind, brauche ich Eure Hilfe, um Razelikh zu besiegen, denn ich fürchte, dass ich nicht stark genug bin, um ihn alleine zu schlagen.\n\nWas noch wichtiger ist - Ihr müsst das Steinmesser halten und nicht benutzen, bevor ich es Euch sage. Dieses Messer wird Razelikhs Seele in ihrem neuen, ewigen Gefängnis festsetzen.\n\nWenn wir Erfolg haben, sprecht mit Wazzik.", sourceObjective = "Sprecht mit dem tödlichen Pförtner nördlich der Anhöhe des Entweihers. Wenn Ihr oben auf der Anhöhe angelangt seid, zerstört Razelikhs Körper und benutzt dann das Steinmesser des Versiegelns, um seine Seele gefangen zu nehmen.", completion = "Ich verstehe. Also hatte Loramus das die ganze Zeit so geplant.\n\nIch hatte den richtigen Verdacht, aber ich denke, ich wollte es nicht glauben. Und jetzt ergibt seine letzte Anweisung an mich auch einen Sinn:\n\nEr sagte mir, ich solle Euch eins hiervon auswählen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25702] = { id = 25702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuhause... Weg... Naga...", description = "<Der Murloc hat Schwierigkeiten, Eure Sprache zu sprechen.>\n\nSteinteich... angegriffen. Naga kommen, einnehmen Dorf, Dorfbewohner.\n\nSalzflopper entkommen, andere nicht. Geht Süden, sprecht mit Häuptling Neptool. Vielleicht er überlebt.", sourceObjective = "Salzflopper hat Euch gebeten, mit Neptool, Häuptling der Steinteichmurlocs, zu sprechen.", completion = "<Der Murlocgeist schaut Euch traurig an.>\n\nSalzflopper hat keine Schande über sich gebracht, indem er wegrannte. Schaut hinter mich und seht selbst.\n\nDer Steinteich hatte keine Chance gegen den Angriff der Naga.", sourceObjectiveStatus = "unverified-source-field" }
quests[25703] = { id = 25703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gräueltaten", description = "<Obwohl seine Lippen sich nicht bewegen, könnt Ihr spüren, dass der Murlochäuptling mit Euch spricht.>\n\nDie Naga der Blutbrandung und die Steinteichmurlocs haben miteinander gelebt, solange wir denken können. Wir hatten unsere Meinungsverschiedenheiten, aber wir haben uns nie gegenseitig provoziert. Warum haben sie sich dann nur gegen uns gewandt?\n\n<Neptool wirft einen Blick über seine Schulter auf seine früheren Dorfbewohner.>\n\nSeht Ihr, was sie jetzt tun? Sie versklaven uns, opfern uns und zwingen uns, gegeneinander zu kämpfen. Ich werde sie aufhalten, {race}... und Ihr werdet meine Waffe sein.", sourceObjective = "Tötet 10 Barbaren der Blutbrandung und 10 Verzauberinnen der Blutbrandung.", completion = "Ihr habt Eure Sache gut gemacht, tapferer {class}. Ich bin erfreut, aber noch nicht zufrieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25704] = { id = 25704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verrückte Magus", description = "Es bleibt nur noch eine Sache, die zu tun ist. Ihr müsst in Tonys Anwesenheit jemand mit einem großen Mojo töten.\n\nNein, nicht mich!\n\nDer alte Magus Tirth is' verrückt geworden, als er versucht hat, das Wasser aufzuhalten, als der Kataklysmus hereinbrach. Jetzt sucht er die Gegend südlich vom Stützpunkt heim.\n\nNehmt diesen Seelenstab und benutzt ihn auf seinem Leichnam. Dann bringt Tony zurück, und wir verfrachten ihn zurück in seinen Körper.\n\nIhr könnt mein Geistportal für den Weg benutzen.", sourceObjective = "Extrahiert die Seele von Tirth, dem verrückten Magus.", completion = "Jetzt werden wir Tony Zweihauer zurück ins Leben bringen. Seid ihr dann beide soweit, Mann?", sourceObjectiveStatus = "unverified-source-field" }
quests[25705] = { id = 25705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falsche Götzen", description = "Neptulon der Gezeitenjäger ist unser Gott. Er war auch der Gott der Blutbrandung, aber anscheinend haben sie ihm den Rücken gekehrt. Jetzt verehren sie nur noch Azshara, ihre Nagakönigin. Ihr werdet die Abbilder Azsharas überall in ihren Siedlungen sehen, die aus Seestein gemeißelt wurden.\n\n<Der Murlocgeist betrachtet Eure Waffe.>\n\nDie Waffe wird reichen. Durchbohrt damit die Götzen der Azsh'ir. Man muss sie daran erinnern, dass unser Vater Neptulon der einzige ist, der wirklich die Meere regiert.", sourceObjective = "Zerstört 8 Götzen der Azsh'ir auf den Roten Weiten.", completion = "Ihr macht einen alten Murloc stolz, {race}.\n\nDanke und mögen die Wellen immer an Euren Füßen plätschern.", sourceObjectiveStatus = "unverified-source-field" }
quests[25706] = { id = 25706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neptools Rache", description = "Noch so viele Nagatode werden den Stamm des Steinteichs nicht wieder zurückbringen, aber die Menge der Rache wird den Geistern meines Volkes helfen, leichter ihre Ruhe zu finden.\n\nViele der mächtigeren Angehörigen der Blutbrandung haben eine Feste in den Höhlen im Nordwesten errichtet. Tötet sie im Namen Steinteichs. Die anderen Angehörigen der Blutbrandung haben hier auf unserem Strand Gladiatorenbecken und Azsh'ir Altäre errichtet, wo sie mein Volk gegeneinander kämpfen lassen und ihren falschen Gott verehren. Tötet sie im Namen des Gezeitenjägers.", sourceObjective = "Tötet 8 Akolythen der Blutbrandung, 8 Zeloten der Blutbrandung, 4 Glücksspieler der Blutbrandung und 4 Götzendiener der Blutbrandung.", completion = "Das letzte Mitglied des Steinteichs kann heute als Geisel genommen und morgen getötet werden, Landwandler... aber sie werden die Unterwelt in dem Wissen durchqueren, dass ein tapferer {race} ihren Tod rächte. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[25707] = { id = 25707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zukunft des Steinteichs", description = "Die Steinteichkaulquappen, die sich noch auf dieser Kiste befinden, scheinen müde, verängstigt und beinahe vertrocknet zu sein. Sie müssen zum Wasser gebracht werden und zwar schnell.\n\nWenn Ihr diese Kiste vielleicht über den Strand in das Verbotene Meer weit jenseits der Küste der Roten Weiten ziehen könntet, dann haben sie eine Chance zu entkommen und die Steinteichmurlocs können vielleicht weiterleben...", sourceObjective = "Zieht die Verlassene Kiste der Blutbrandung zum Verbotenen Meer vor der Küste der Roten Weiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25708] = { id = 25708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefallene Freunde", description = "Laut Eurem Bericht klingt es nicht so, als gäbe es viele Überlebende… nur rastlose Geister. Wir müssen ihnen wenigstens zu ihrer letzten Ruhe verhelfen.\n\n<Enohar nimmt einen tiefen Schluck Schwarzbier aus ihrem Krug.>\n\nKehrt zurück zur Havarieküste und vernichtet die Geister der Worgen, die dort ihr Unwesen treiben. Dadurch befreit Ihr sie von dieser Welt, sodass sie in die nächste weiterziehen können.", sourceObjective = "Tötet 13 ertrunkene Gilneer an der Havarieküste, um ihre Geister zu befreien.", completion = "<Enohar nimmt einen Schluck aus ihrem frisch aufgefüllten Krug.>\n\nAye, das habt Ihr gut gemacht, Junge. Ihr erfüllt die Allianz mit Stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[25709] = { id = 25709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein paar Schwanzfedern ausreißen", description = "Die gestrandeten Schiffe bereiten mir jedoch noch weitere Sorgen. Sie locken unglaublich viele Geier an. Sie haben zwar die Knochen schon sauber gepickt, aber wir können nicht zulassen, dass sie die Leichen unserer Freunde noch weiter entehren.\n\nBevor ich Braumeister wurde, war ich Jäger. Hier, nehmt diesen Bogen und vor allem diese Pfeile. Ich habe sie mit einer Tinktur benetzt, die diesen Knochenpflückern eine unangenehme Überraschung bereiten sollte.", sourceObjective = "Benutzt Enohars explosive Pfeile, um 20 Schwanzfederknochenpflücker an der Havarieküste zu töten.", completion = "Es ist eine Tragödie, was sich da an der Havarieküste abgespielt hat. Und es waren nicht einmal Soldaten, sondern nur brave Bürger auf der Suche nach einem neuen Zuhause.\n\nIch glaube, wir haben alles getan, was wir konnten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25710] = { id = 25710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unwichtige Ablenkungen", description = "Nethergarde hat seit Jahren unerschütterlich dem Ansturm der Dämonen, die dieses Land heimsuchen, standgehalten. Unsere Wache endet nie, unsere Wachsamkeit lässt nie nach und unsere Tapferkeit ist unermesslich.\n\nWir haben diese Lande verteidigt, seit das Portal sich öffnete, aber jetzt hat dieses Hordengeschmeiß die Frechheit, sich uns in den Weg zu stellen? Wir haben SIE genauso beschützt wie uns selbst!\n\n<Lungertz mustert Euch.>\n\nSchauen wir mal, ob Ihr für den Kampf taugt. Tötet einen der Hordenspäher der Okril'lon, die an unseren Grenzen nagen.", sourceObjective = "Tötet einen Späher der Okril'lon außerhalb von Burg Nethergarde in den Verwüsteten Landen.", progress = "Was ist los - zu viel Angst, zu kämpfen?\n\nIch hätte es besser wissen müssen, als einem außenstehenden {class} wie Euch zu vertrauen. Man überlässt die Verteidigung von Nethergarde lieber seinen eigenen Leuten.", completion = "Hmm... nicht schlecht. Ihr seid schneller als die meisten meiner Leute. Bleibt in der Nähe, {name}... Vielleicht habe ich doch noch Verwendung für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25711] = { id = 25711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schaltet die Okril'lon aus.", description = "Die Horde ist eine Landplage, derer wir uns entledigen werden, aber es ist schwieriger als erwartet. Ihr müsst dem ein Ende setzen.\n\nWestlich von Nethergarde übt die Hauptstreitmacht der Okril'lon Druck auf unsere Verteidigung aus. Im Moment besetzen sie die Mine von Nethergarde, wollen in die Versorgungslager vordringen und zum Schluss die Burg einnehmen. Ihr müsst sie dezimieren und ihren Vormarsch aufhalten, {name}.", sourceObjective = "Tötet 9 Infanteristen der Okril'lon beim Versorgungslager von Nethergarde.", completion = "Ihr seid ein Gewinn für die Allianz und die Kirin Tor, {name}. Gut gemacht.\n\nMit der Zeit werden unsere Streitkräfte die Mine zurückerobern und diese Hunde der Horde aus den Verwüsteten Landen vertreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25712] = { id = 25712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herrscher von Nethergarde", description = "Lungertz ist ein starker Anführer, aber er ist stolz. Er untertreibt den Druck, den die Horde wirklich auf uns ausübt. Ohne unsere Mine... Nethergarde ist mittellos.\n\nWir müssen die Streitkräfte der Horde JETZT aus dem Versorgungslager entfernen. Dazu müssen wir ihren Kommandanten, Hauptmann Metlek, töten. Er ist kein überragender Anführer und zieht es vor, Befehle aus den hinteren Linien heraus zu bellen, aber dennoch könnte sein Tod uns den Sieg verschaffen, den wir brauchen.", sourceObjective = "Tötet Hauptmann Metlek am Versorgungslager von Nethergarde.", completion = "Danke, {name}. Dank Eurer Bemühungen bin ich zuversichtlich, dass wir mit der Zeit die Mine von Nethergarde zurückerobern können.", sourceObjectiveStatus = "unverified-source-field" }
quests[25713] = { id = 25713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht ihre Waffen zunichte", description = "Sagt einmal... {name}, nicht wahr? Ich habe einen Vorschlag für Euch, der Explosionen beinhaltet. Interessiert?\n\nIch konnte nicht anders, als Eure Unterhaltung mit dem Rüstmeister anzuhören. Wisst Ihr... Ich arbeite an einer Sprengvorrichtung. Sie ist anderen Lebewesen gegenüber nicht sehr wirksam, aber verheerend gegen Artillerie. Wenn Ihr wieder hinausgeht, um diesen Orcs einen Besuch abzustatten, findet ein paar Vorräte der Feinde und probiert dieses Ding einmal aus. Wer weiß... vielleicht mögen sie ja auch Explosionen.", sourceObjective = "Benutzt Butterblumes Handgranate gegen 8 Waffenkisten der Okril'lon im Versorgungslager von Nethergarde.\n\nHaltet einen Sicherheitsabstand, wenn Ihr die Granaten verwendet, damit Ihr Euch nicht selbst in die Luft sprengt.", completion = "Aaah, das Geräusch, wenn Dinge \"bumm\" machen erfreut mein Herz und lässt es schneller schlagen. Ihr habt diesem Gnom den Tag versüßt, {name}", sourceObjectiveStatus = "unverified-source-field" }
quests[25714] = { id = 25714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behüter Mahar Ba", description = "Es ist Zeit für Euch, den Behüter aufzusuchen. Er ist in letzter Zeit etwas übellaunig und ich weiß nicht genau, warum.\n\nGeht oben auf den Magierturm und meldet Euch bei ihm. Ich habe hier keine Arbeit für Euch, aber ich bin sicher, dass er welche hat.", sourceObjective = "Meldet Euch bei Behüter Mahar Ba im Magierturm von Burg Nethergarde.", completion = "Meine Mitarbeiter haben das Richtige getan, Euch zu mir zu schicken. Ich habe ein Problem, das eine Bedrohung für das Sanktum von Nethergarde darstellen könnte. Ich brauche jemanden, der fähiger ist als die meisten anderen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25715] = { id = 25715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein genauerer Blick", description = "Wir haben schon unzählige Schiffe an der Küste im Südosten vorbeiziehen sehen und nie ist etwas Auffälliges passiert. Doch vor einigen Tagen warf ein Sturm mehrere Schiffe an die Küste, wo sie nun gestrandet liegen.\n\nIch würde einen Krug Nethergarde Bitter wetten, dass es Schiffe der Horde sind, wenn ich Nethergarde Bitter nicht so sehr lieben würde. Ich kann Euch jedoch mit Gold bezahlen, wenn Ihr Euch diese Schiffe genauer anseht und mir davon berichtet.", sourceObjective = "Späht die gestrandeten Schiffe an der Havarieküste in den Verwüsteten Landen aus.", progress = "Was gibt es Neues von der Havarieküste, {name}?", completion = "Ihr habt Worgen gesehen? Das klingt nicht gut.\n\nWorgengeister? Das klingt sogar noch schlimmer.\n\nDas waren keine Schiffe der Horde… das waren gilnearische Schiffe! Und sie waren sicher auf dem Weg nach Surwich am Ende des Besudelten Walds. Das ergäbe zumindest Sinn.\n\nWir müssen ihnen helfen, {name}! Die Worgen sind unsere Verbündeten!", sourceObjectiveStatus = "unverified-source-field" }
quests[25716] = { id = 25716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kultisten an der Schwelle", description = "Möglicherweise seid Ihr schon einigen Kultisten der Schattenanbeter begegnet, die in Höhlen südwestlich von Nethergarde hausen. Sie stellen keine direkte Bedrohung für unsere Burg dar, aber ich fürchte, dass sie etwas Furchtbares planen, das Eure Vorstellungskraft übersteigt.\n\nDie rangniederen Mitglieder tragen Zauberfokusse, die eine Antwort enthalten könnten. Bringt mir einige intakte davon her, wenn Ihr sie den Kultisten aus den Händen reißen könnt.", sourceObjective = "Besorgt 6 intakte Zauberfokusse eines Schattenanbeters von Zauberklingen der Schattenanbeter und Okkultisten der Schattenanbeter in den Verwüsteten Landen.", progress = "Die Kultisten werden sich nicht so einfach von ihren Fokussen trennen. Tötet sie schnell, bevor sie Eure Absicht erahnen.", completion = "Geschickt gemacht, {name}. Jetzt werden wir sehen, ob mein Verdacht berechtigt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25717] = { id = 25717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dämonen und der Druide", description = "Das archäologische Institut konzentriert sich auf das Auffinden und Bewahren magischer Artefakte. Diese Exkursion konzentriert sich auf die dämonischen Artefakte, die dort verborgen sind, wo sich einst die Faulende Narbe befand.\n\nEin Worgendruide hat sich dort angesiedelt und lässt einen Wald wachsen. Allerdings scheint es ihm nicht so recht zu gelingen, da die Gegend immer noch von Dämonen verseucht ist.\n\nNun wie auch immer, der Wald steht unserer Exkursion im Weg, genau wie die Dämonen. Tötet die besudelten und kehrt zurück zu mir, damit wir uns um den Druiden kümmern.", sourceObjective = "Tötet 5 Verdammniswachenzerstörer, 5 Schreckenslordschänder, 5 verderbte Dunkelwaldtreants und 3 Teufelssporensumpflords im Besudelten Wald.", completion = "Ich danke Euch, {name}.\n\nIch sollte etwas ehrlicher zu Euch sein. Die Dämonen waren ein Ärgernis, aber sie sind nicht das eigentliche Problem. Dieser Worgendruide ist unser Problem", sourceObjectiveStatus = "unverified-source-field" }
quests[25718] = { id = 25718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man am besten weitermacht", description = "Dadurch, dass Ihr dort unten Dämonen getötet habt, bekamen unsere Späher genug Zeit, sich den Druiden einmal genauer anzusehen. Meine Informanten berichten mir, dass er Marl Wurmdorn heißt - er ist ein abtrünniger Druide aus Gilneas mit beachtlichen Kräften. Er wohnt in Maldraz, dem großen, verdrehten Baum mitten im Wald und irgendeine seltsame Kraft bewahrt ihn vor Unheil. Ob diese Kraft dämonischen oder natürlichen Ursprungs ist, müssen wir noch herausfinden.\n\nSprecht mit Elijah. Vielleicht hat er neue Informationen für Euch.", sourceObjective = "Meldet Euch bei Elijah Dämmerflug bei Sonnenschleiers Exkursionstrupp in den Verwüsteten Landen.", completion = "Rohan schickt EUCH, um seinen Druiden zu töten? Na schön.\n\nIhr solltet wissen: Marl Wurmdorn ist gleichermaßen Dämon wie Druide. Sogar ein Druide mit seiner Macht hat keine Chance gegen die dämonischen Energien, die dieses Land vollkommen durchziehen. Aber das ändert nichts daran, dass er für uns ein Hindernis ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25719] = { id = 25719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonisches Gefäß", description = "Es muss einen Weg geben, Wurmdorns Aufmerksamkeit zu erregen. Etwas, das seine Trance durchbricht. Etwas, das mit Sicherheit funktioniert.\n\nDie wenigen Wildtierarten, die es geschafft haben, sich im Besudelten Wald anzusiedeln, sind zweifellos von den latenten Energien des Landes in Mitleidenschaft gezogen. Eure Aufgabe ist es, ihre Kadaverteile einzusammeln und eine Möglichkeit zu finden, sie in ein Gefäß umzuwandeln. Egal ob Wurmdorns Trance druidischer oder dämonischer Natur ist, ein Gefäß mit besudeltem Tierfleisch, das groß genug ist, sollte in der Lage sein, diese zu durchbrechen.", sourceObjective = "Tötet besudelte Schwarzbären, besudelte Nachtpirscher und besudelte Kreischer im Besudelten Wald und versucht, ihre Kadaverteile zu einem dämonischen Gefäß zusammenzusetzen.", progress = "Dämmerflugs Plan ist gut. Habt Ihr das Gefäß, {name}?", completion = "Ausgezeichnet gemacht, {name}. Wir haben, was wir brauchen, um die Trance des Worgen zu durchbrechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25720] = { id = 25720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fall des Marl Wurmdorn", description = "Wurmdorns unnatürlicher Wald bedroht den Fortschritt unserer Exkursion. Unsere Spitzhacken zerbrechen an ihren Wurzeln, sein Moos überwuchert unsere Ausgrabungsstätten und seine Tiere greifen meine Leute an. Wenn es um Ausgrabungen geht, ist mir eine dämonenverseuchte Einöde allemal lieber als ein Wald.\n\nNehmt das dämonische Gefäß und benutzt es gegen Marl Wurmdorn, um ihn aus seiner Trance zu holen. Kehrt zu mir zurück, wenn er nicht mehr unter uns weilt.", sourceObjective = "Tötet Marl Wurmdorn bei Maldraz in den Verwüsteten Landen. Ihr könnt das dämonische Gefäß benutzen, um ihn aus seiner Trance zu holen.", completion = "Jetzt, da dieser Druide von der Bildfläche verschwunden ist, können wir uns wieder unseren Ausgrabungen zuwenden. Die Welt ist voller mächtiger Artefakte, {name}. Ihr müsst nur den Willen haben, das Notwendige zu tun, um sie zu bekommen.\n\nNehmt ruhig eins von diesen hier. Das Institut für Archäologie teilt immer gerne seine Schätze mit anderen Mitgliedern der Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[25721] = { id = 25721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kämpft gegen die Flut", description = "Ich bin hier, weil Muradin selbst wusste, dass diese Messstation jemanden braucht, der diese Schwachköpfe auf Trab bringt. Sie haben alle zu viel Angst vor den Wildtieren, um überhaupt etwas zu tun. Wenn ich will, dass sie ihren Allerwertesten hochbekommen, dann muss hier ein wenig aufgeräumt werden.\n\nZunächst einmal haben wir ein Problem mit Elementaren. Die Flut hat hier so ein Durcheinander angerichtet, dass selbst das Wasser hysterisch geworden ist.\n\nIch wette, Ihr habt noch nie einem ganzen See Sinn und Verstand eingeprügelt, aber genau das verlange ich jetzt von Euch. Ihr müsst diesen Elementaren richtig eine von mir verpassen.", sourceObjective = "Tötet 10 Flutelementare.", completion = "Wer hätte das gedacht. Es gibt tatsächlich jemanden hier, der Magni keine Schande macht - sein armes Herz aus Kies sei gesegnet.\n\nAllein dafür bekommt Ihr den ersten Schluck von dem Bier, mein Junge. Aber lasst Euch das nicht zu Kopfe steigen! Wir haben noch viel mehr verfluchte Arbeit zu tun und ich werde nicht dulden, dass Ihr vorzeitig schlapp macht!", sourceObjectiveStatus = "unverified-source-field" }
quests[25722] = { id = 25722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ablagerungen, mein Lieber", description = "Die Zerstörung des Steinwerkdamms war keine Kleinigkeit. Wir sind hier, um herauszufinden, wie schlimm der Schaden ist. Eine riesige Wassermenge ist hier durchgetobt und wenn diese die Erde zu sehr gestört hat, könnte uns noch Schlimmeres bevorstehen.\n\nWir können einiges aus den Sedimenten der überfluteten Gegend ablesen. Ich brauche so viele Erdproben wie möglich. Ich würde es wirklich sehr zu schätzen wissen, wenn Ihr dort hinausgehen und noch einige Proben für mich sammeln würdet.", sourceObjective = "Sammelt 8 Flutsedimentproben ein.", progress = "Dann lasst mal das Sediment sehen.", completion = "Ah ja. Die gute Nachricht ist, sie sind perfekt. Die schlechte Nachricht ist, dass ich - sogar betrunken, wie ich bin - erkenne, dass ihre Farbe nicht dem Mutterboden hier entspricht\n\nDas bedeutet, dass es nicht gut für diese Gegend aussieht, {name}. Aber wir müssen noch mehr Tests durchführen, bevor wir das Handtuch werfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25723] = { id = 25723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreschen bringt Glück", description = "Die hiesigen Wildtiere sind offenbar von der Flut vollkommen verstört. Dieses Moor war einmal voller Krokilisken, aber ich habe noch keinen einzigen gesehen.\n\nWas ich gesehen habe, sind Dreschadons. Die hat es hier noch nie gegeben, also muss die Flut sie direkt aus Loch Modan hergeschwemmt haben.\n\nZum Glück für uns sind sie viel leckerer als Krokilisken und mir gehen gerade die Vorräte aus. Bringt mir Dreschadonfleisch für das Lager und ich werde Euch gern dafür bezahlen.", sourceObjective = "Besorgt 8 Dreschadonbrocken von verirrten Dreschadons.", progress = "Sind sie fleischig? Schauen wir mal.", completion = "Herrlich. Die kann man bestimmt gut braten und dem Lager bleibt eine Woche Pilzkekse erspart.", sourceObjectiveStatus = "unverified-source-field" }
quests[25724] = { id = 25724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostmähnenaggression", description = "Der Kataklysmus hat das Gleichgewicht der Kräfte in Dun Morogh in Frage gestellt, {name}. Ohne Warnung tauchte eine Welle Troggs aus den Höhlen in der Nähe von Gnomeregan auf und hat die Trolle der Frostmähnen überrannt. Die Trolle sind seitdem immer weiter nach Osten gezogen.\n\nIm Nordwesten, oben am Schimmergrat, gab es immer eine gewisse Präsenz der Frostmähnen, aber seit der Abwanderung sind wir jetzt von Trollen umgeben. Wir können nicht zulassen, dass die Trolle diesen Umstand zu ihren Gunsten ausnutzen. Meine Leute werden im Osten die Stellung halten und Ihr führt einen Schlag gegen den Schimmergrat.", sourceObjective = "Tötet 5 Seher der Frostmähnen und 7 Schneeschreiter der Frostmähnen auf Schimmergrat.", completion = "Wir sollten in der Lage sein, unsere Bemühungen auf den Rest der Trolle im Osten zu konzentrieren, aber es gibt immer noch das Problem mit den Wendigos im Graufelsbau.", sourceObjectiveStatus = "unverified-source-field" }
quests[25725] = { id = 25725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moosbuschbeeren", description = "Wir haben genügend Vorräte, aber wir benötigen Arzneien. Das halbe Lager hat einen gewaltigen Kater und ein Heilmittel wäre jetzt angebracht.\n\nZum Glück kenne ich ein gutes Hausmittel, das mir von meiner lieben alten Mutter beigebracht wurde. Wir brauchen nur ein paar hiesige Zutaten.\n\nSeid so gut und sammelt für mich ein paar Beeren von Moosbüschen. Sie wachsen hauptsächlich am Wasser im Schatten, also schaut entlang der Küste und in der Nähe anderer Pflanzen.", sourceObjective = "Sammelt 15 Handvoll Moosbeeren.", progress = "Wie viele habt Ihr gefunden?", completion = "Die sind genau richtig. Die Jungs werden bald wieder auf den Füßen sein, sobald ich das hier in etwas Essbares verwandelt habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[25726] = { id = 25726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nivellierarbeiten", description = "Also gut, Ihr müsst mir helfen, mein Nivelliergerät zu finden.\n\nWas guckt Ihr so komisch? Richtig! Ich sagte mein Nivelliergerät! Das ist ein wichtiges Vermessungsinstrument!\n\nIch hab mir den Namen nicht ausgedacht, ok? Geht und schaut es nach! Ich habe es nur kurz auf einem Felsen liegen lassen und einer dieser furchtbaren Schlammlinge hat es verschlungen. Die kriechen überall hier herum, aber einer von ihnen müsste es noch in sich haben.", sourceObjective = "Findet ein Nivelliergerät bei einem schmierigen Schlammling.", progress = "Habt Ihr das Nivelliergerät gefunden?", completion = "Oh gut, es ist unbeschädigt! Vielen Dank.\n\nIhr, äh, solltet Euch dort vielleicht ein bisschen säubern.", sourceObjectiveStatus = "unverified-source-field" }
quests[25727] = { id = 25727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drungeld Finsterblick", description = "Der Dunkeleisenklan hier führt nichts Gutes im Schilde. Und wenn Euch das überrascht, seid Ihr noch dämlicher als die Papiertiger da in dem Zelt. Muradin kann ja diesen rußgeschwärzten Schwachköpfen in Eisenschmiede gegenüber Lippenbekenntnisse ablegen, aber hier draußen zählen die nichts.\n\nLetzte Nacht gab es einen Überfall auf das Lager und ein Überfall ist einer zu viel. Ihr Anführer ist ein stämmiger Kerl mit Namen Finsterblick und er versteckt sich in der Höhle am südlichen Ufer des Flusses.\n\nBringt mir Finsterblicks Bart als Beweis, dass er keine Bedrohung mehr für uns und Eisenschmiede darstellt.", sourceObjective = "Tötet Dungeld Finsterblick und nehmt seinen Bart an Euch.", progress = "Zeigt mal her!", completion = "Ein Glück, dass wir den los sind! Ich werde das fiese Ding später verbrennen, damit es uns nicht das Lager zustinkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25728] = { id = 25728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baunzers wilder Ritt", description = "Jetzt braucht Herr Baunzer nur noch einen Engel, der ihm als Navigator dient. Würdest du dieser Engel sein, <Onkel/Tante>? Mit deiner Hilfe können wir auf die Klippe hinaus und ganz ganz viele Hordies töten! Was sagst du? Ach bitte, <Onkel/Tante>! BITTE BITTE BITTE!\n\nWenn wir genug Hordies töten, kauft Lord Brachweiher uns allen ein Eis!", sourceObjective = "Tötet 20 Goblintechniker und 5 Goblinernter.", completion = "<Lord Brachweiher hustet.>\n\nDas ist merkwürdig.\n\nIhr habt da draußen mit dem Roboter gute Arbeit geleistet. Ihr habt mich ein wenig auf dem falschen Fuß erwischt. Ich wusste nicht, dass das kleine Mädchen so...\n\n<Lord Brachweiher zeigt auf seine Schläfe und macht kleine Kreise mit seinem Finger.>\n\nBesonders ist...\n\nNaja, ist ja egal, wie die Sache erledigt wird, nicht wahr? Habe ich recht?\n\nWahrscheinlich.\n\nWollt Ihr ein Eis?", sourceObjectiveStatus = "unverified-source-field" }
quests[25729] = { id = 25729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerenzo der Verräter", description = "<Der Gnomcorder springt mit lautem Surren an.>\n\nBitte kommen, {name}! Seid Ihr da? Isch 'abe gese'en auf die Karte, dass Ihr seid in die Nä' von die Felskesselsee Wasserrad, ist das rischtisch?\n\nOffenbar 'at die Venture. Co sisch einquartiert bei die Rad. Ihr müsst umschauen Eusch, wenn Ihr dort seid. Solltet Ihr se'en die verräterische Gnom mit die Name Gerenzo Pfeifzang, Ihr müsst ihn treten kräftisch in die 'intern für misch und Gnomeregan! Isch werde zahlen fürstlisch!", sourceObjective = "Tötet Gerenzo Pfeifzang.", completion = "<Der Gnomcorder summt laut.>\n\nWunderbar. Jetzt isch kann streischen noch eine Name von meine Liste.\n\nIsch werde misch melden wieder.\n\nXakxak Ende!", sourceObjectiveStatus = "unverified-source-field" }
quests[25730] = { id = 25730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "HÜTET EUCH VOR FELSKIEFER!", description = "Auf Befehl der Leute, die nicht an einem Stück von einem richtig großen Fisch verschlungen werden wollen, ist der Zutritt zum Felskesselsee VERBOTEN! Jemand hat beschlossen, einen riesigen, zwergenfressenden Fisch im See anzusiedeln.\n\nEs wird dringend empfohlen, dem See fernzubleiben. Solltet Ihr allerdings der heldenhafte Typ sein und noch ein paar Freunde haben, tut uns doch den Gefallen und tötet das verdammte Ding! Vielleicht kann ich dann hier angeln, nicht wahr?\n\nFalls es Euch wirklich gelingen sollte, sucht mich in der Scherwindfeste für eine Belohnung auf.\n\n-Der alte Eisenbock", sourceObjective = "Tötet Felskiefer und bringt Felskiefers riesigen Zahn an Euch.", progress = "Habt Ihr das Ungeheuer getötet?", completion = "Wer hätte das gedacht. Ihr habt das Ungeheuer tatsächlich erwischt? Nun, abgemacht ist abgemacht! Hier ist Eure Belohnung!", sourceObjectiveStatus = "unverified-source-field" }
quests[25731] = { id = 25731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Spatz in der Hand", description = "Es ist Zeit, dieser Sache auf den Grund zu gehen. Wir müssen die Matrone dieser Wilden befragen, Marion Wurmschwinge. Wir werden sie lebend fangen. Das ist der Plan:\n\nDie Harpyien kommunizieren mit Signalfeuern über den Gebirgskamm hinweg. Wenn wir eines davon löschen, wird Marion sicher kommen, um zu sehen, was damit los ist.\n\nKämpft mit ihr, um sie abzulenken, während ich mich von hinten anschleiche und sie mir schnappe. Die Fragen zu stellen überlasse ich dann Euch. Los, holen wir sie uns, {name}!", sourceObjective = "Löscht ein Harpyiensignalfeuer, um die Aufmerksamkeit Marion Wurmschwinges zu erregen. Kämpft mit ihr, bis Thisalee sie einfängt, und befragt die Harpyienmatrone dann.", progress = "Marion hat den Schrein hier früher oft besucht. Himmelsfürst Omnuron wollte den Harpyien eine Chance geben, aber ich habe ihr nie vertraut.", completion = "Also sind die Harpyien Werkzeuge einer Art von Drachen, \"Sethria\".\n\nAber was tun die Drachen mit diesen Eiern? Und was ist das für ein \"besonderes\" Ei, das Sethria so unbedingt will?\n\nIch verstehe es nicht, {name}. Ich habe einen Bericht an Himmelsfürst Omnuron weitergeleitet. Er wird wissen, was als Nächstes zu tun ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25732] = { id = 25732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hühnchen rupfen", description = "Wir haben es geschafft!\n\nNager ist erledigt und ich habe unseren Glitzerkram gefunden!\n\nDas sind gute Nachrichten.\n\nDas Kleinod ist verflucht und verwandelt jeden, der es berührt, in ein Skelett.\n\nDas sind schlechte Nachrichten.\n\nLaut diesen verfluchten Piraten kennt der König der Gilblin jedoch das Geheimnis, wie man diesen Fluch brechen kann.\n\nDas sind gute Nachrichten.\n\nIch kann aber keinen Fuß aus diesem Riff setzen, sonst bleibe ich auf ewig verflucht.\n\nDas sind schlechte Nachrichten.", sourceObjective = "Budd möchte, dass Ihr den Zinnplätter von König Gurboggel auf Gurboggels Fels besorgt.", progress = "Also, {race}…\n\nBrecht Ihr jetzt diesen Fluch oder was?", completion = "Das ist er?\n\nWie soll das denn den… Moment mal…", sourceObjectiveStatus = "unverified-source-field" }
quests[25733] = { id = 25733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pirscht von dannen", description = "Thelgenfelsen ist hier ein wichtiger Ort. Wir brauchen ihn, um dort den felsigen Untergrund und so was zu untersuchen.\n\nDa einem nichts im Leben leicht gemacht wird, gibt es am Thelgenfelsen riesige Höhlenpirscher. Sie sind so groß wie ein Zwerg und zweimal so hungrig. Wie ich schon sagte, diese modischen Kerle sind Forscher und keine Krieger, also wenn ich möchte, dass sie überhaupt etwas geschafft bekommen, müsst Ihr mir helfen, diese Viecher zu beseitigen.\n\nTötet so viele dieser Quälgeister, wie Ihr könnt und es soll Euer Schaden nicht sein, {name}.", sourceObjective = "Tötet 7 Höhlenpirscher und 7 Egelpirscher.", completion = "Gute Arbeit! Es würde mich nicht überraschen, wenn diese schrecklichen Dinger irgendwo da drin Eier abgelegt hätten, aber für den Moment reicht es.", sourceObjectiveStatus = "unverified-source-field" }
quests[25734] = { id = 25734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unten im Thelgenfelsen", description = "Ich bin jetzt nicht mehr ganz so wackelig auf den Beinen, also werde ich anfangen, das Nivelliergerät für meine letzten Messungen aufzubauen. Eins benötige ich noch von Euch.\n\nTief im Thelgenfelsen steht ein Seismograph, um alle Bewegungen der Erde aufzuzeichnen. Wenn sich seit der Katastrophe noch etwas bewegt hat, wird er es uns zeigen.\n\nDer Seismograph ist ganz unten in der Höhle. Findet ihn und bringt den Bericht, den er aufgezeichnet hat, zu mir.", sourceObjective = "Holt den seismischen Bericht von Thelgen aus Thelgenfelsen.", progress = "Dann schauen wir mal, was wir da haben, nicht wahr?", completion = "Wunderbar, mein Freund. Das dürfte alles sein, was wir brauchen. Schauen wir mal.", sourceObjectiveStatus = "unverified-source-field" }
quests[25735] = { id = 25735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pyrophorerz", description = "Telgenfelsen dort drüben ist so eine Art Wunder der Natur. Dort liegt die weltweit einzige bekannte Quelle von Pyrophorerz.\n\nDas Zeug ist selten, heiß begehrt und einfach nur lächerlich explosiv. Wenn man mit einer Spitzhacke aus Stahl daraufschlägt, gibt es ein Feuerwerk, das einen Raum voller Goblins vor Neid erblassen ließe.\n\nZum Glück habe ich für solche Gelegenheiten eine funkenresistente Spitzhacke erschaffen. Ich werde sie Euch leihen, wenn Ihr mir ein bisschen Pyrophorerz bringt. Natürlich bekommt Ihr auch etwas vom Gewinn ab.", sourceObjective = "Findet 8 Stücke Pyrophorerz.", progress = "Nun, Ihr seht so aus, als ob Euch kein Haar gekrümmt wurde.", completion = "Großartig! Wunderschön, dieses Erz.\n\nGut, dass Ihr Eure Spitzhacke nicht verloren habt. Die letzte Person, die ich dort hinausgeschickt habe, hat das untere Ende auf dem Boden aufschlagen lassen - und der Teil ist nicht funkensicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[25736] = { id = 25736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Flutwellenkern", description = "Das ist alles, was von dem riesigen Elementar, der Euch angegriffen hat, übrig geblieben ist: eine schäumende Kugel des Wassers, die sich weiter Eures Griffes zu entziehen versucht.\n\nForba wäre über einen weiteren Beweis, dass Ihr noch eine Bedrohung vom Lager abgewendet habt, sicherlich erbaut.", sourceObjective = "Bringt den Flutwellenkern zu Forba Fliesmeißel.", progress = "Häh? Was habt Ihr da?", completion = "Das Ding hat ja immer noch Kampfeswillen! Erstaunlich!\n\nIhr seid zäh, {name}. Ich weiß das zu schätzen. Ich würde sagen, dass eine Belohnung angebracht ist, bevor Ihr fortgeht.\n\nTut weiterhin Euer Bestes für Eisenschmiede, verstanden? Und solltet Ihr jemals meiner Schwester begegnen, grüßt sie von mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[25737] = { id = 25737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorsichtige Verhandlungen", description = "Nach dem, was ich über diese Wassergoblins weiß, sollte das funktionieren.\n\nIch habe aus den Gegenständen, die Ihr mir zusammengeplündert habt, eine Haizahnkette gebastelt. Es ist nicht nur ein hübsches Schmuckstück, sondern auch eine Erinnerung an Nagers Tod. Schwer zu sagen, wie viele Gilblins dieses Monster bei lebendigem Leib verschlungen hat.\n\nBietet dem Anführer der Gilblins die Halskette an. Als Tausch benötige ich ein Artefakt, das als Zinnplätter bekannt ist.\n\nUnd beeilt Euch, <Bursche/Mädel>. Ich beginne schon, mein Fleisch zu vermissen...", sourceObjective = "Sprecht mit König Gurboggel.", sourceObjectiveStatus = "unverified-source-field" }
quests[25739] = { id = 25739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn die Horde Euch nicht erwischt...", description = "<Hauptmann Kosak hustet schwach.>\n\nWar unterwegs zum Weberpass, kam vom Basislager der Nordwachtexpedition im Süden. Hinterhalt. Nicht von Horde. Spinnen. Große, hässliche, haarige, gemeine Spinnen.\n\nDutzende in die Flucht geschlagen, vielleicht Hunderte. Konnte nicht mehr zählen. Überwältigt von der Königin. Hat ein Stück aus mir herausgebissen. Bin nur um ein Haar lebend entkommen. Sterbe vielleicht.\n\nMehr meiner Leute sind unterwegs. Muss sicheren Durchgang gewährleisten. Tötet Spinnenkönigin.\n\n<Hauptmann Kosak wird bewusstlos.>", sourceObjective = "Tötet Königin Silith.", completion = "<Hauptmann Kosak zwingt sich zu einem Lächeln.>\n\nMacht Euch um mich keine Sorgen. Jetzt, da der große Held die Spinnenkönigin getötet hat, wird alles gut.\n\nVerstärkung kann hier jetzt sicher passieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[25740] = { id = 25740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Fakten", description = "Der Drache Sethria muss aufgehalten werden. Wir wissen, dass sich ihr Nest im Süden an den südlichen Klippen des Hyjal befindet, aber das ist leider fast schon alles.\n\nIch habe Thisalee auf der Suche nach Fakten zu Sethrias Nest geschickt. Sie hat speziell um Eure Hilfe gebeten. Ihr scheint die junge Druidin schwer beeindruckt zu haben.\n\nTrefft Euch mit Thisalee direkt hinter dem Tunnel, der zu Sethrias Nest führt. Und vergesst nicht, wir sind hier auf der Suche nach Fakten. Tut bloß nichts Verrücktes!", sourceObjective = "Meldet Euch bei Thisalee am Eingang zu Sethrias Nest auf dem Hyjal.", completion = "Ah, {name}! Ich hatte gehofft, Euch hier draußen wiederzusehen.\n\nWas, Omnuron nennt dies eine \"Suche nach Fakten\"? Pah! Fakten findet man am besten bei Leichen.\n\nLasst uns etwas Schaden anrichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25741] = { id = 25741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf die Zukunft vorbereiten", description = "Vergiftete Reisende kommen um die Scherwindfeste immer häufiger vor. Gerade vor ein paar Tagen fiel ein Hauptmann der Nordwacht den Spinnen der Weberkuhle zum Opfer. Er wäre an dem Gift gestorben, wenn ich kein Gegengift gehabt hätte. Leider ist mein Vorrat an Gegengift beinahe erschöpft.\n\nWenn Ihr nach Süden in Richtung Weberkuhle unterwegs seid, würdet Ihr freundlicherweise einige Kluftmoosgiftbeutel für mich besorgen? Ihr solltet sie von Kluftmoosspinnen erhalten.", sourceObjective = "Besorgt 10 Kluftmoosgiftbeutel.", progress = "Habt Ihr die Giftbeutel, um die ich Euch gebeten hatte, bekommen?", completion = "Das dürfte uns auf absehbare Zeit mit Gegengift versorgen. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25743] = { id = 25743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entscheidungen, Entscheidungen", description = "Das ist keine magische Lösung für meinen Fluch! Das ist nur ein Hammer!\n\nIch bin vielleicht verrückt, aber ich bin nicht dumm.\n\nIch werde das hier AUF GAR KEINEN FALL benutzen, um meinen Glitzerkram kaputt zu machen! Nicht nach allem, was ich durchgemacht habe, um an ihn zu kommen!\n\n<Budd hält einen Moment inne, um nachzudenken.>\n\nAber das bedeutet, dass ich bis in alle Ewigkeit hier unten festsitze...\n\nUnd ich habe doch gerade erst gelernt, wie man segelt.\n\nOhhh... ich kann mich nicht entscheiden.\n\nHier, nehmt Ihr den Hammer. Ich stelle den Glitzerkram einfach auf den Boden und schaue weg.", sourceObjective = "Benutzt den Zinnplätter, um den Zinnpropheten zu zerstören.", completion = "Oh, wie schön hätte es sein können…", sourceObjectiveStatus = "unverified-source-field" }
quests[25744] = { id = 25744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhandlungen", description = "{name}, Ihr habt den Turbodampfer gut verteidigt! Ich habe noch eine andere Aufgabe, bei der Ihr mir helfen könnt.\n\nIch habe Crazzle Flinkspross und Kravel Kohlebart nach Nordosten geschickt, um mit den Überlebenden der Zentauren zu verhandeln, weil es in ihrer Heimat, den Spalthufanhöhen, ein Ölvorkommen gibt.\n\nIch glaube, dass diese stinkenden Halbpferde von diesem Vorkommen keine Ahnung haben, und wir werden versuchen, die Bohrrechte für das schwarze Gold so günstig wie möglich zu erhalten. Ich habe das Gefühl, dass Ihr Euch um die Verhandlungen kümmern solltet.\n\nWas haltet Ihr davon?", sourceObjective = "Sprecht mit Crazzle Flinkspross in Spalthufanhöhen in Tausend Nadeln.", completion = "<Crazzles Augen leuchten auf.>\n\nIch habe Kravel Kohlebart hochgeschickt, um mit den Häuptlingen zu verhandeln, aber jetzt da Ihr hier seid, werden wir die Bohrrechte in null Komma nichts erhalten!", sourceObjectiveStatus = "unverified-source-field" }
quests[25745] = { id = 25745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhandlungen", description = "{name}, Ihr habt den Turbodampfer gut verteidigt! Ich habe noch eine andere Aufgabe, bei der Ihr mir helfen könnt.\n\nIch habe Riznek und Rennstreckenleiter Zherin nach Nordosten geschickt, um mit den Überlebenden der Zentauren zu verhandeln, weil es in ihrer Heimat, den Spalthufanhöhen, ein Ölvorkommen gibt.\n\nIch glaube, dass diese stinkenden Halbpferde von diesem Vorkommen keine Ahnung haben, und wir werden versuchen, die Bohrrechte für das schwarze Gold so günstig wie möglich zu erhalten. Ich habe das Gefühl, dass Ihr Euch um die Verhandlungen kümmern solltet.\n\nWas haltet Ihr davon?", sourceObjective = "Sprecht mit Riznek in Spalthufanhöhen in Tausend Nadeln.", completion = "<Rizneks Augen leuchten auf.>\n\nIch habe Rennstreckenleiter Zherin hochgeschickt, um mit den Häuptlingen zu verhandeln, aber jetzt da Ihr hier seid, werden wir die Bohrrechte in null Komma nichts erhalten!", sourceObjectiveStatus = "unverified-source-field" }
quests[25746] = { id = 25746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sethrias Brut", description = "Unsere erste Aufgabe besteht darin, die Herde hier auszudünnen. An diesem Ort wimmelt es nur so von ihnen.\n\nTötet zunächst diese Drachkin und macht Euch erst später Gedanken darüber, warum wir hier sind.", sourceObjective = "Tötet 12 von Sethrias Dienern: Eine beliebige Kombination aus Zwielichtdrachkin oder Rüstungsschmieden der Zwielichtdrachkin.", completion = "Das scheint Euch zu liegen.\n\nIch mag Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25747] = { id = 25747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Blick nach vorne", description = "Der Admiral hat die Informationen, die Ihr für ihn gesammelt habt, genutzt, um einen Vorposten unter der Terrasse im Westen einzurichten. Er bereitet sich dort auf eine Art Angriff auf die Naga vor.\n\nIhr solltet sofort zu ihm gehen und ihm von den Massen berichten, die Ihr beobachtet habt. Unsere Streitmacht ist klein. Ich mache mir Sorgen um unsere Soldaten, wenn wir uns in einen waghalsigen Angriff stürzen.\n\nNehmt mein Seepferd. Es kennt den Weg.", sourceObjective = "Sprecht mit Admiral Dvorek unter der südlichen Terrasse in den Ruinen von Vashj'ir.\n\nBenutzt Wellensprecherin Valorens Seepferd, um den Vorposten schnell zu erreichen.", completion = "Schön Euch wiederzusehen, {class}. Ich dachte schon fast, wir hätten Euch bei dem törichten Botengang für die Wellensprecherin verloren.\n\nIst dabei wenigstens etwas herausgekommen?", sourceObjectiveStatus = "unverified-source-field" }
quests[25748] = { id = 25748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deutliche Ziele", description = "Ich verstehe. Eure Nachrichten sind düster, aber ich bin nicht ganz unvorbereitet auf eine solche Lage. Ich wusste, dass unser Plan riskant ist, solange wir die genauen Zahlen der Naga nicht kennen, aber zu diesem Zweck haben wir ja diesen Vorposten eingerichtet.\n\nIch will Euch nicht belügen, {class}. Wenn wir die Naga nicht beschäftigt halten, werden sie uns angreifen. Wir haben weder die Anlagen noch die Männer, um eine geeignete Verteidigung zu errichten, daher kommt das für uns nicht in Frage.\n\nWir brauchen mehr Zeit. Könnt Ihr ihre Reihen im Süden ein wenig ausdünnen?", sourceObjective = "Tötet 10 Naga der Streitmächte, die sich unter der südlichen Terrasse auf der Grundebene zusammenziehen.", completion = "Auch im Süden scheinen sich mehr Naga zusammenzuziehen, als unsere Berichte angenommen haben. Wir müssen uns beeilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25749] = { id = 25749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht ganz unvorbereitet", description = "Ich habe Euer Gespräch mit dem Admiral gehört. Ich weiß, dass das, was wir tun, wahnsinnig klingt, aber wir haben einfach keine andere Wahl. Dort in der Höhle sind Leute, die sich auf uns verlassen.\n\nIch habe Aufklärer auf den verschiedenen Klippen in der Gegend aufstellen lassen. Bei den ganzen verstreuten Nagaspähern in der Gegend geht ihnen die Munition rasend schnell aus. Könntet Ihr ihnen mehr Armbrustbolzen bringen, um uns etwas Zeit zu verschaffen?", sourceObjective = "Bringt 8 Schachteln mit Armbrustbolzen zu den Aufklärern der Allianz, die sich auf den Vorsprüngen unter der südlichen Terrasse befinden.", completion = "Ihr seid wahrscheinlich das zuverlässigste Wesen, das ich je getroffen habe. Ich wünschte, meine Männer wären nur halb so gründlich wie Ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[25751] = { id = 25751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausreichende Inspiration", description = "Hallo! Ich reiße mir hier alle Beine aus, um den Angriff des Admirals vorzubereiten. Er hat große Hoffnungen und hochtrabende Pläne, um alle möglichen Dinge hoch in die Luft zu jagen! … Oder eher hoch ins Wasser? Ja, wohl eher das.\n\nAber um Dinge in die Luft zu jagen, braucht man SPRENGSTOFF! Ich habe keinen Sprengstoff. Es ist traurig. Sehr traurig.\n\nAber ich wurde ausreichend inspiriert, um eine Lösung zu finden. Die Tangblasen, die von den Ruinen hängen, enthalten ein überraschend explosives Gas. Könntet Ihr etwas davon für mich sammeln? Oh bitte, bitte!", sourceObjective = "Sammelt 8 aufgedunsene Tangblasen, die unterhalb der südlichen Terrasse hängen.", progress = "Tick, tack, tick, tack. Immer in Eile. Keine Zeit für neue Errungenschaften. Was würde ich nur dafür geben, wieder ein Labor zu haben!", completion = "Ihr seid wirklich mutig! Ich habe gesehen, wie Ihr alle möglichen Arten von Murlocs, Naga und spitzzähnigen Fischen bekämpft habt, aber das war nichts im Vergleich hierzu! Wie Ihr Euch diese Tangblasen einfach so unter den Arm klemmt ist eine ganz neue Ebene der Furchtlosigkeit. BUMM! Ihr könntet jede Sekunde in die Luft gehen.\n\nIhr seid ein {race} nach meinem Geschmack.", sourceObjectiveStatus = "unverified-source-field" }
quests[25752] = { id = 25752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blitzangriff", description = "Wir haben alles, was wir für den Angriff brauchen.\n\nWenn das, was Ihr sagt, wahr ist, solltet Ihr Euch während des Angriffs lieber fest an Euer Reittier klammern. Es ist sehr unwahrscheinlich, dass jemand von uns, der auf das offene Meer gerät, den Naga davonschwimmen kann.\n\nTötet so viele wie möglich. Wir werden den Angriff führen und treffen uns dann oben auf der zerbrochenen Terrasse, sobald wir die Sprengsätze aufgebraucht haben. Hoffentlich sind dann nur noch so wenige übrig, dass wir sie auf die altmodische Art erledigen können.", sourceObjective = "Sprecht mit Ingenieur Hexasept außerhalb des Gebäudes, um Euch dem Überfall anzuschließen. Benutzt dann Euren improvisierten Sprengstoff, um 100 Soldaten der Azsh'ir, 20 Wellenkreischer der Azsh'ir und 12 Archaeen der Azsh'ir zu töten.", completion = "Ihr habt Euch da oben großartig geschlagen! Ihr habt ihre Reihen zerschmettert, aber es waren viel mehr als geplant und die meisten unserer Truppen sind da draußen in den Massen der Naga untergegangen.\n\nWir müssen diese Position so lange wie möglich halten, um ihnen Zeit zu erkaufen. Hoffentlich schaffen es einige von ihnen noch zum Treffpunkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25753] = { id = 25753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefallen, aber nicht vergessen", description = "Das war ein Desaster! Die meisten unserer Männer sind Speeren zum Opfer gefallen, noch bevor sie überhaupt in der Nähe des Treffpunkts waren!\n\nWir werden diese Position sicher nicht mehr lange halten können, bevor die Naga uns überrennen. Wir müssen uns in den Südwesten begeben und so viele der Männer retten, wie wir nur können. Geht und tut alles, was in Eurer Macht steht.\n\nLange halten sie nicht mehr durch. Bitte, beeilt Euch!", sourceObjective = "Rettet 6 verletzte freiwillige Angreifer.", completion = "Danke. Wirklich.\n\nWir müssen diese Männer so schnell wie möglich von hier wegbringen. Ich bin mir sicher, wir begegnen uns schon bald am Vorposten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25754] = { id = 25754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einschätzung des Erfolgs", description = "Boshafte Rüpel… Sie haben mit diesen Speeren einen ganz schönen Schaden angerichtet.\n\n<Der Admiral zuckt ein bisschen, als er sich die Wunde an der Seite hält.>\n\nWir werden hier so lange wie möglich durchhalten, damit alle Männer es schaffen. Ich brauche jemanden, der ausspioniert, wie viele es noch sind. Ich möchte wissen, wie viel Schaden wir ihnen zugefügt haben. Eine ihrer größten Gruppen war um die Ecke im nordwestlichen Teil dieser runden Terrasse, die andere war etwas weiter im Norden, in einem kleinen Tunnel, der auch Teil der mittleren Ebene der Ruinen ist.\n\nSeid Ihr bereit?", sourceObjective = "Späht den nordwestlichen Teil der runden Terrasse und den Tunnel unter der Haupttreppe im Norden aus. Beide Orte befinden sich auf der Terrasse von Nar'shola, der mittleren Ebene der Ruinen.", completion = "Immer noch so viele? Sie müssen hier etwas sehr Wichtiges vorhaben, wenn sie so zahlreich auftauchen.\n\nIch will ehrlich zu Euch sein, {name}, denn das bin ich Euch schuldig: Ich weiß nicht, wie viel Hoffnung besteht. Wir werden uns in Kürze zurückziehen, aber wir werden uns nicht verteidigen können, falls sie zurückschlagen. Wir haben keinen Ort, an den wir flüchten können... Und uns gehen die Optionen aus.\n\nEs tut mir leid, ich sollte meine Gedanken für mich behalten. Tut mir einen Gefallen und erwähnt den Truppen gegenüber nichts davon. Ich werde mir etwas einfallen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25755] = { id = 25755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visionen der Vergangenheit: Das Massaker von Biel'aran", description = "Ja, ich weiß, es ist in Zeiten wie diesen viel verlangt, aber Ihr müsst Euch einen Moment lang von dieser Niederlage losreißen.\n\nIch werde mich um diese Soldaten kümmern. Ihr müsst jedoch den Ort im Westen finden, an dem die Schlacht mit dem General der Kvaldir ausgetragen wurde, von der Ihr mir erzählt habt. Von dort aus solltet Ihr mehr über die Erlebnisse der Kriegsmaid erfahren können. Ich habe das untrügliche Gefühl, dass der Schlüssel zum Sieg über die Naga in dieser Kriegsmaid liegt.\n\nBitte, beeilt Euch. Ich tue alles, was ich kann, um Euch Zeit zu verschaffen.", sourceObjective = "Werdet Zeuge des weiteren Verlaufs der Geschichte der Kriegsmaid, indem Ihr ihre gebrochene Klinge am Sterbeort des Generals der Kvaldir benutzt.", completion = "Ihr seid fertig! Gerade rechtzeitig. Ich glaube nicht, dass wir ihnen noch lange hätten standhalten können.\n\nEin Artefakt? Ist das vielleicht etwas, was wir gegen die Naga einsetzen können? Ich schätze, dann müssten wir es erstmal finden.\n\nDoch möglicherweise müssen wir uns erst dringenderen Angelegenheiten widmen, bis wir die Gelegenheit haben, dies weiter zu verfolgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25756] = { id = 25756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zehrt an Zherin!", description = "Wenn wir die Bohrrechte erhalten wollen, müssen wir wissen, was für ein Angebot die Horde unterbreiten wird. Wir können die Bohrrechte nur bekommen, wenn unser Angebot besser ist!\n\nDer Vermittler der Horde, Rennstreckenleiter Zherin, ist gerade vor Ort in Gesprächen mit den Khans. Ich schlage vor, Ihr begebt Euch auch dorthin, und überzeugt Zherin davon, das Angebot der Horde auszuhändigen.\n\nIhr müsst ihn nicht töten ... wir sind ja keine Wilden! Es reicht, wenn Ihr etwas arg an seinen Nerven zehrt.", sourceObjective = "Erhaltet das Angebot der Horde.", progress = "Habt Ihr das Angebot der Horde erhalten? Was bieten sie für die Bohrrechte an?", completion = "Was?! Woher hat die Horde so viel Gold für ein Angebot?\n\nSo viel Gold haben wir nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[25757] = { id = 25757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas hart zu Kohlebart!", description = "Wenn wir die Bohrrechte erhalten wollen, müssen wir wissen, was für ein Angebot die Allianz unterbreiten wird. Wir können die Bohrrechte nur bekommen, wenn unser Angebot besser ist!\n\nDer Vermittler der Allianz, Kravel Kohlebart, ist gerade vor Ort in Gesprächen mit den Khans. Ich schlage vor, Ihr begebt Euch auch dorthin, und überzeugt Kohlebart davon, das Angebot der Allianz auszuhändigen.\n\nIhr müsst ihn nicht töten ... wir sind ja keine Wilden! Es reicht, wenn Ihr ihn ein bisschen hart rannehmt.", sourceObjective = "Erhaltet das Angebot der Allianz.", progress = "Habt Ihr das Angebot der Allianz erhalten? Was bieten sie für die Bohrrechte an?", completion = "Was?! Woher hat die Allianz so viel Gold für ein Angebot?\n\nSo viel Gold haben wir nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[25758] = { id = 25758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lücke in ihrer Rüstung", description = "Seht Ihr, was sie da tun? Sie statten ihre Drachkin mit Panzerplatten aus! Das muss Todesschwinges Idee gewesen sein.\n\nDiese Zwielichtmoloche sehen aus, als wären sie unbesiegbar, sobald sie fertig sind. Es muss doch einen Weg um diesen Panzer herum geben!\n\nGeht dorthin und holt Euch einige der Panzerplatten des Schattenhammers, die noch nicht angebracht wurden. Wir müssen herausfinden, wie wir das verhindern können!", sourceObjective = "Sammelt 8 Panzerplatten des Schattenhammers.", progress = "Habt Ihr ein paar Panzerplatten bekommen können? Musstet Ihr jemanden töten, um sie zu bekommen?\n\nIch hoffe doch sehr!", completion = "Schaut Euch diese Dinger an. Uff, die Runen schmerzen mir in den Augen. Diese hier soll Fleisch versengen? Im Ernst? Autsch! Moment mal…\n\nDiese Platten müssen direkt im Fleisch festgenietet werden. Die Schmerzen müssen unerträglich sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[25760] = { id = 25760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visionen der Vergangenheit: Die Invasion von Vashj'ir", description = "Das Bruchstück, das Ihr gefunden habt, scheint von Nagahand geschaffen zu sein. Ich hatte gehofft, ein starkes Fokusobjekt wie dieses für einen Zauber zu finden, an dem ich gerade arbeite. Mit diesem Zauber könnten wir einen Blick in die kürzliche Vergangenheit werfen.\n\nIch habe die Klinge verzaubert, aber Ihr müsst sie an einen Ort bringen, von dem wir wissen, dass ihr Besitzer sich dort aufgehalten hat. Ich möchte, dass Ihr zurück an die Stelle reist, wo Ihr die Klinge gefunden habt und sie dort benutzt.\n\nVielleicht können wir so mehr über die Pläne der Naga hier erfahren. Oder noch besser: Vielleicht finden wir einen ihrer Schwachpunkte, sodass wir eine bessere Chance haben, sie zu besiegen.", sourceObjective = "Benutzt die Klinge der Kriegsmaid der Naz'jar auf dem Schlachtfeld am südöstlichen Ende der Ruinen.", completion = "Eine Kriegsmaid? Davon habe ich noch nie gehört.\n\nSo wie Ihr mir die Sache schildert, scheinen die Truppen der Naga weitaus zahlreicher zu sein, als der Admiral es sich in seinen kühnsten Träumen vorstellt. Vielleicht können wir mehr von der Klinge erfahren, wenn wir andere Orte finden, an denen diese Kriegsmaid zugegen war. Ich habe nur Angst um den Admiral und seine Soldaten. Wir müssen sie warnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25761] = { id = 25761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demontage", description = "Wir müssen diese Moloche aufhalten, bevor sie komplett in Rüstung gehüllt sind. Im Augenblick sind sie noch verwundbar, aber auch nur, wenn wir an den Platten vorbei in das kranke Fleisch darunter stoßen können.\n\nNehmt mein Messer und rammt es zwischen die Platten der bewehrten Moloche, um ihnen die Rüstung zu rauben.\n\nSobald sie aus ihrer Trance erwachen, solltet Ihr Euch auf einen harten Kampf gefasst machen. Löst einfach weiter ihre Rüstung und haltet diese Moloche auf!", sourceObjective = "Benutzt Thisalees Messer, um 3 Zwielichtmoloche zu wecken und zu töten. Das Messer kann mehrfach verwendet werden, um die Rüstung eines Molochs herunterzureißen.", progress = "Oh, gut.\n\nIhr seid noch am Leben.", completion = "Das nenne ich atemberaubende Klingenkunst, {name}!\n\nUnd wieder eine Bedrohung weniger auf dem Hyjal, um die wir uns sorgen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25762] = { id = 25762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die uralte Kohlenpfanne", description = "Was haben wir denn hier? <Ein/Eine:r> {race}? Ihr seid wohl hier, um unser Land mit Süßholzraspelei und Versprechen zu stehlen?\n\nIhr könnt mich nicht täuschen. Ich habe schon viele Winter gesehen und weiß, wie man mit jemandem wie Euch umgehen muss. Die Khans hören jedoch nicht mehr auf die Ältesten, wie sie es einst taten.\n\nDa Ihr schon einmal hier seid, werde ich dafür sorgen, dass Ihr Euch nützlich macht. Als das Wasser über uns hereinbrach, hat der große Wassergeist Aquarian die uralte Kohlenpfanne in der Spalthufhöhle gelöscht.\n\nEntfacht die Kohlenpfanne wieder. Aquarian wird erscheinen. Bringt mir die heilige Flamme.", sourceObjective = "Entfacht die uralte Kohlenpfanne wieder und erhaltet die heilige Flamme.", progress = "Habt Ihr die heilige Flamme? Wagt es nicht, sonst mit mir zu sprechen, {race}!", completion = "Ihr habt mir diesen Gefallen getan, um Euch bei mir einzuschmeicheln. So leicht ist das aber nicht.\n\nIch weiß genau, was Ihr vorhabt. Das Meer hat es zwar nicht geschafft, aber der große Luftgeist wird Euch und Euer Volk für all die Vergehen bestrafen, die den Elementen gegenüber begangen wurden.\n\nVerschwindet aus meinen Augen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25763] = { id = 25763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kodex der Schatten", description = "<Dieses kunstvolle Buch besteht aus Hunderten von Seiten feinsten Pergaments und ist in Schiefer gebunden. Es ist in vielen Sprachen geschrieben, wovon Euch die meisten unbekannt sind. Aufwändig gezeichnete Bilder zeigen Zauberer oder gar ganze Gebäude, die hinter Schleiern aus Schatten verschwinden.>\n\n<Viele der Bilder zeigen magische Artefakte wie jene, die Ihr um das Lager herum seht. Ihr vermutet, dass die Drachendame Sethria etwas versteckt halten möchte. Thisalee will sicher davon erfahren!>", sourceObjective = "Meldet Thisalee Krähe bei Sethrias Nest auf dem Hyjal Eure Entdeckungen.", completion = "Sie tun was?\n\nSie verhüllen etwas? Aber natürlich! Damit unsere Späher in den Lüften es nicht mit ihren Adleraugen entdecken können!", sourceObjectiveStatus = "unverified-source-field" }
quests[25764] = { id = 25764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eierjagd", description = "Himmelsfürst Omnuron möchte, dass wir Avianas Ei finden. Ich kann Euch fast schon garantieren, dass es von einem von Sethrias Schattengeräten getarnt wird.\n\nSucht um das Lager herum nach Schattentarnungsgeneratoren und schaltet diese Dinger aus, bis Ihr das Ei gefunden habt.\n\nSobald Ihr es enttarnt habt, ruft die anderen Druiden herbei. Verteidigt das Ei, bis wir es in Sicherheit gebracht haben.\n\nLos, holt Euch das Ei, {name}!", sourceObjective = "Deaktiviert die Schattentarnungsgeneratoren, bis Ihr Avianas Ei gefunden habt. Sobald das Ei enttarnt wurde, verteidigt es, bis die Druiden der Klaue es in Sicherheit bringen können.", completion = "Wir haben es geschafft, {name}! Avianas Ei sollte bald schon sicher in den Zweigen ihres Schreins liegen.\n\nMeint Ihr, dass sie dann wirklich zu uns zurückkehren wird?", sourceObjectiveStatus = "unverified-source-field" }
quests[25765] = { id = 25765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sagt ihnen, Koko schickt Euch", description = "<Ein mächtiger/Eine mächtige:r> {race} wie Ihr wäre in Nordwacht wirklich von Nutzen. Wir haben eine Niederlage im Südlichen Brachland einstecken müssen und benötigen Eure Hilfe! Hättet Ihr Interesse daran, der Allianz behilflich zu sein?\n\nDie Bombe? Ja, sie ist ein Problem, aber das Steinkrallengebirge zeichnet sich nicht gerade durch seinen Grundstückspreis aus. Diese Gegend war schon ein Drecksloch, bevor die Horde ihre Klauen danach ausgestreckt hat!\n\nIch überlasse die Entscheidung Euch. Wenn Ihr uns im Brachland aushelfen wollt, nehmt mein Pferd Blaustahl. Er grast an der Kreuzung südlich von hier. Er wird Euch an der ersten Orcsperre vorbeitragen.", sourceObjective = "Meldet Euch bei Truppenkommandant Valen am Basislager der Nordwachtexpedition im Steinkrallengebirge.", completion = "Kosak hat Euch geschickt, ja? Erstaunlich. Ich hatte mit Sicherheit angenommen, dass er bereits tot ist.\n\nNun, wenn Ihr es an der Blockade vorbei geschafft habt, dann habt Ihr auf jeden Fall etwas, das wir brauchen können.\n\nHabt Ihr irgendwelche Neuigkeiten von der Horde? Was machen sie? Wohin gehen sie? Erzählt mir alles.", sourceObjectiveStatus = "unverified-source-field" }
quests[25766] = { id = 25766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkanes Vermächtnis", description = "Der Zorn der Elementare hat im Herzen des Steinkrallengebirges eine Stadt der Hochgeborenen ans Licht gebracht.\n\nDirekt im Südwesten vor hier, hinter dem Sishircanyon, findet Ihr die Ruinen von Eldre'thar. In den Ruinen liegen Schätze, die seit zehntausenden Jahren nicht von Sterblichen angerührt wurden!\n\nNehmt dieses Gerät und benutzt es gegen die Geister der Hochgeborenen, die die Ruinen bewohnen. Es wird... ihre Seelen zur letzten Ruhe betten und außerdem wertvolle Daten sammeln, die ich später auswerten kann.", sourceObjective = "Benutzt das Gefängnis der Hochgeborenen, um 5 Geister der Hochgeborenen zu binden.", completion = "Ich versichere Euch, Ihr Einfaltspinsel, die Geister, die Ihr gefangen habt, finden jetzt ihre Ruhe. Lasst Euch nicht von ihren Protesten aus der Ruhe bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25767] = { id = 25767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erinnerungen einfangen", description = "Der große Kataklysmus hat im Herzen des Steinkrallengebirges eine Stadt der Hochgeborenen ans Licht gebracht. Ihr müsst Euch nach Südwesten zu den Ruinen von Eldre'thar begeben. Wenn Ihr dort seid, durchsucht die Gegend nach uralten Relikten. Bringt die Relikte zu mir, damit ich sie untersuchen kann, {name}.\n\nLos! Wir dürfen den Arkanisten nicht warten lassen!", sourceObjective = "Besorgt 8 Relikte von Eldre'thar.", progress = "Habt Ihr die uralten Relikte gefunden?", completion = "Wunderbar! Arkanist Valdurian wird außerordentlich zufrieden sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25768] = { id = 25768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer frei: Mirkfallonposten!", description = "Späherkommandant Barus ist am Mirkfallonposten im Nordwesten stationiert und hat die Bombe der Horde entdeckt. Der Heißluftballon von Krom'gar, an dem die Bombe angebracht ist, befindet sich momentan bei der neuen Goblintankstelle am Mirkfallonsee. Das könnte die Gelegenheit sein, die wir brauchen, um das Ding ein für alle Male zu beseitigen.\n\nNehmt Eure Siebensachen, {name}, und macht Euch auf den Weg! Späherkommandant Barus erwartet Eure Ankunft am Mirkfallonposten.\n\nUnd {name}, Eure Hartnäckigkeit macht der Stärke und Tapferkeit der Allianz alle Ehre!\n\nMöge der Ruhm mit Euch sein!", sourceObjective = "Meldet Euch bei Späherkommandant Barus am Mirkfallonposten im Steinkrallengebirge.", completion = "Ich nehme einmal an, dass Ihr den Heißluftballon von Krom'gar auf Eurem Weg hierher gesehen habt? Wenn nicht, lasst Eure Augen untersuchen. Er schwebt direkt über der Ölplattform.", sourceObjectiveStatus = "unverified-source-field" }
quests[25769] = { id = 25769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brachweiher ruft", description = "Ihr seid hier? Worauf wartet Ihr - eine persönliche, gravierte Einladung? Lord Brachweiher ruft, Narr! Geht zu ihm - jetzt!", sourceObjective = "Sprecht mit Lord Brachweiher an der Scherwindfeste im Steinkrallengebirge.", completion = "Schön, Euch wiederzusehen, {name}. Ich habe Neuigkeiten vom Mirkfallonsee.", sourceObjectiveStatus = "unverified-source-field" }
quests[25770] = { id = 25770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fasslieferung", description = "Also gut. Wir müssen dieses Bier sofort an seinen Bestimmungsort bringen!\n\nEisenschmiede hat eine Gruppe Feldmesser ausgeschickt, um den Schaden im Sumpfland zu überprüfen, der bei dem Dammbruch entstanden ist. Forba Fliesmeißel leitet die Expedition... und glaubt mir, Ihr wollt Euch nicht mit ihr anlegen!\n\nMit einer Ladung Bier bei ihr aufzutauchen, kann nicht schaden. Geht und bringt ihr das hier und sie wird Euch vielleicht bitten, die ein oder andere Arbeit für sie zu verrichten.", sourceObjective = "Bringt das Gebirgsjägerbier zu Forba Fliesmeißel an Fliesmeißels Messstation.", progress = "Ja? Was habt Ihr da für mich?", completion = "Ha! Schön, dass die hohlköpfigen Gebirgsjäger genug Grips haben, um das Bier einem richtigen Mann zu überlassen, damit die Arbeit auch erledigt wird.\n\nWillkommen in meiner Messstation. Wenn Euch der Sinn danach steht, Eisenschmiede zu helfen, indem Ihr die Jobs einiger nutzloser, fauler Säcke, die sich Zwerge nennen, übernehmt, dann seid Ihr an der richtigen Adresse!", sourceObjectiveStatus = "unverified-source-field" }
quests[25771] = { id = 25771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des einen Draeneis Plunder...", description = "Ein Bruchstück glitzernden Steins liegt vor Euch. Ihr spürt, dass dieser Gegenstand für jemand in den Verwüsteten Landen von großem Wert sein könnte.", sourceObjective = "Bringt das unvollständige Draenethystfragment zu Kum'isha dem Sammler in den Verwüsteten Landen.", progress = "Und? Draenethyst?", completion = "Nur ein Splitter? Pah! Das nützt mir gar nichts! Nehmt Eure Belohnung und geht mir aus den Augen.\n\nKlingt bekannt? Sollte es auch, weil ich es tausend Mal am Tag sage.\n\nOh, wie ich diese Welt hasse.", sourceObjectiveStatus = "unverified-source-field" }
quests[25772] = { id = 25772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kum'ishas Bemühungen", description = "Vor Euch liegt eine schimmernde Kugel. Ihr spürt, dass dieser Gegenstand für jemand in den Verwüsteten Landen von großem Wert sein könnte.", sourceObjective = "Bringt die fehlerlose Draenethystsphäre zu Kum'isha dem Sammler in den Verwüsteten Landen.", progress = "Habt Ihr eine fehlerlose Draenethystsphäre gefunden?", completion = "Einfach erstaunlich. Ich hatte so meine Zweifel, dass irgendwer noch eine Sphäre finden würde, aber hier ist sie und pulsiert in meinen Händen.\n\nGut gemacht, {name}!\n\nSolltet Ihr noch weitere finden - wobei ich glaube, dass das unmöglich ist -, dann bringt sie mir und ich werde Euch erneut belohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25774] = { id = 25774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Katzengold", description = "Von so viel Gold, wie die Horde anbietet, können wir NUR TRÄUMEN. {name}, wir müssen etwas unternehmen, oder wir laufen in Gefahr, die Bohrrechte nicht erhalten zu können!\n\nOh, Moment! Eine der Unterwasseruntersuchungen, die wir nach dem Kataklysmus angestellt haben, hat von einer Art Erz berichtet, das wie Gold aussieht und vom Untergrund nach oben befördert wurde. Das ist die Idee!\n\nReist zum alten Revier der Zentauren, Spalthufklippe und Spalthufhöhle westlich von hier, und grabt etwas von diesem Material aus.", sourceObjective = "Sammelt 8 Pyriterzbrocken.", progress = "Wenn Ihr genug von dem Pyrit bringt, können wir es mit schnell mit ein wenig Farbe aufarbeiten, schön stapeln, und diese Palette könnt Ihr dann dem Häuptling bringen.", completion = "Genial! Jetzt müssen wir nur die Goldfarbe finden - ich weiß, dass sie hier irgendwo ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25775] = { id = 25775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Katzengold", description = "Von so viel Gold, wie die Allianz anbietet, können wir NUR TRÄUMEN. {name}, wir müssen etwas unternehmen, oder wir laufen in Gefahr, die Bohrrechte nicht erhalten zu können!\n\nOh, Moment! Eine der Unterwasseruntersuchungen, die wir nach dem Kataklysmus angestellt haben, hat von einer Art Erz berichtet, das wie Gold aussieht und vom Untergrund nach oben befördert wurde. Das ist die Idee!\n\nReist zum alten Revier der Zentauren, Spalthufklippe und Spalthufhöhle westlich von hier, und grabt etwas von diesem Material aus.", sourceObjective = "Sammelt 8 Pyriterzbrocken.", progress = "Wenn Ihr genug von dem Pyrit bringt, können wir es mit schnell mit ein wenig Farbe aufarbeiten, schön stapeln, und diese Palette könnt Ihr dann dem Häuptling bringen.", completion = "Genial! Jetzt müssen wir nur die Goldfarbe finden - ich weiß, dass sie hier irgendwo ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25776] = { id = 25776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sethrias Untergang", description = "Während Ihr Sethrias Nest überfallen habt, gab es einen regen Austausch von Botschaften zwischen uns und dem Schrein. Himmelsfürst Omnuron hat sich zunächst geziert, aber schließlich konnte ich meine Druidenfreunde überreden, einen direkten Angriff auf Sethria selbst zu wagen.\n\nAlle haben meinem Plan zugestimmt... unter einer Voraussetzung. IHR sollt den Angriff anführen.\n\nNehmt diese Signalrakete und stellt Euch Sethria auf dem hinteren Sims. Wenn sie ihr wahres Ich zeigt und in ihre Drachenform wechselt, schießt die Rakete ab und fordert Verstärkung an!", sourceObjective = "Tötet den Drachen Sethria. Sobald sie ihre wahre Form offenbart, benutzt die Signalrakete, um Verstärkung zu rufen.", progress = "Wenn ein geringerer Drache wie Sethria uns schon so viele Probleme bereiten kann, möchte ich gar nicht wissen, was der Schattenhammer sonst noch auf Lager hat…", completion = "Sethria ist nicht mehr! Ich wusste, dass es das Risiko wert ist.\n\nIch bleibe hier, um nach Überlebenden zu suchen, aber ich schätze, Eure Anwesenheit wird am Schrein gewünscht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25777] = { id = 25777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorwärts nach Menethil", description = "Diese Neuigkeiten müssen so schnell wie möglich nach Menethil gelangen. Ich werde Euch mit meinem schnellsten Widder auf den Weg schicken, {name}.\n\nEr kennt den Weg - Ihr müsst nur darauf achten, dass Ihr fest im Sattel sitzt und Euch gut festhaltet.\n\nTrödelt nicht im Lager herum. Wir müssen die Nachricht schnell überbringen!", sourceObjective = "Liefert Fliesmeißels Bericht bei Hauptmann Starkfaust im Hafen von Menethil ab.", progress = "Willkommen in Menethil, Fremder. Ich hoffe, Ihr habt gute Neuigkeiten oder etwas Hochprozentiges bei Euch.", completion = "Lasst mich mal sehen.\n\nNa großartig... \"Schwerwiegende geologische Instabilität\"? \"Gefahr einer plötzlichen, massiven topologischen Destabilisierung\"?\n\nSchön zu hören, dass hier etwas Schlimmes passieren könnte. Dann sollten wir vielleicht besser unsere überflutete Stadt zusammenpacken und mit ihr irgendwo hinfliegen, wo es sicher ist!\n\nBah!", sourceObjectiveStatus = "unverified-source-field" }
quests[25778] = { id = 25778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falsches Gold für schwarzes Gold", description = "Jetzt, da das \"Gold\" fertig ist, möchte ich, dass Ihr es zu Khan Ablinh bringt. Er wird davon so überwältigt sein, dass ich fast davon ausgehe, dass er uns dabei helfen wird, die Bohrtürme aufzustellen. Die Pferdestärke könnten wir gut gebrauchen.\n\nHaha, guter Witz, was? Pferdestärke?", sourceObjective = "Bringt die Palette voller \"Gold\" zu Khan Ablinh in den Spalthufanhöhen in Tausend Nadeln.", progress = "Was ist das? Wirklich viel Gold habt Ihr da.", completion = "Stellt die Palette einfach auf den Boden, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25779] = { id = 25779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falsches Gold für schwarzes Gold", description = "Jetzt, da das \"Gold\" fertig ist, möchte ich, dass Ihr es zu Khan Blizh bringt. Er wird davon so überwältigt sein, dass ich fast davon ausgehe, dass er uns dabei helfen wird, die Bohrtürme aufzustellen. Die Pferdestärke könnten wird gut gebrauchen.\n\nHaha, guter Witz, was? Pferdestärke?", sourceObjective = "Bringt die Palette voller \"Gold\" zu Khan Blizh in den Spalthufanhöhen in Tausend Nadeln.", progress = "Was ist das? Wirklich viel Gold habt Ihr da.", completion = "Stellt die Palette einfach auf den Boden, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25780] = { id = 25780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Burg Menethil", description = "Wir hatten uns kaum nach der Flut wieder zusammengerauft, als die Dunkeleisenzwerge die Stadt angriffen. Meine Männer und ich sind der Stadtbevölkerung zu Hilfe geeilt, aber die irren Dunkeleisenzwerge haben sich in die Burg zurückgezogen.\n\nSie haben sich da richtig eingegraben und wir können die Burg nicht zerstören. Nicht jetzt, da die halbe Stadt schon in Trümmern liegt.\n\nNehmt meinen Platz ein, {name}. Ich würde mir den Anführer ja vorknöpfen, aber er hat mir einen schweren Schlag versetzt. Verschafft Euch Zugang zur Burg, tötet Horghast und bereitet allem ein Ende!", sourceObjective = "Tötet Horghast Loderwahn.", completion = "Er ist tot! Den Schöpfern sei Dank...\n\nMir gefällt gar nicht, wie die aussehen. Die Dunkeleisenzwerge, mit denen ich bisher zu tun hatte, waren niemals so verrückt. Irgendwas ist mit diesen Schwachköpfen geschehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[25790] = { id = 25790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zu Crazzle", description = "Ich bin NICHT dumm!\n\nGeht zu Eurem Meister zurück und sagt ihm, dass es mit der Sache NICHTS wird! Falls Ihr überhaupt lebend bei ihm ankommen solltet.", sourceObjective = "Sprecht mit Crazzle Flinkspross in Spalthufanhöhen in Tausend Nadeln.", completion = "Sie haben WAS?!", sourceObjectiveStatus = "unverified-source-field" }
quests[25791] = { id = 25791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zu Riznek", description = "Ich bin NICHT dumm!\n\nGeht zu Eurem Meister zurück und sagt ihm, dass es mit der Sache NICHTS wird! Falls Ihr überhaupt lebend bei ihm ankommen solltet.", sourceObjective = "Sprecht mit Riznek in Spalthufanhöhen in Tausend Nadeln.", completion = "Sie haben WAS?!", sourceObjectiveStatus = "unverified-source-field" }
quests[25792] = { id = 25792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorwärts drängen", description = "Die meisten der Gebirgsjäger und Dampfpanzer in Dun Morogh kämpfen an der Frontlinie der Frostmähnen, die sich uns aus Südosten nähert. Wir können kaum die Trolle zurückhalten, geschweige denn, in ihr Dorf vorrücken und ihren Anführer angreifen.\n\nSie haben unseren Zugangspfad mit mysteriösen Totems blockiert, die allen sich nähernden Gebirgsjägern die Luft nehmen und ihre Opfer dadurch hilflos ihren Feinden überlassen. Auf diesem Stein ist eine Rune des Feuers eingraviert. Er sollte in der Lage sein, die Totems zu zerstören und unsere Gebirgsjäger zu befreien.", sourceObjective = "Benutzt die Rune des Feuers, um 4 Totems der Konstriktion an der Frontlinie der Frostmähnen zu zerstören.", completion = "Endlich gibt es mal gute Nachrichten von der Frontlinie der Frostmähnen. Ich werde dafür sorgen, dass die Gebirgsjäger sofort vorrücken und angreifen. Jetzt müssen wir unseren Gnomverbündeten am Depot signalisieren, dass sie ihren Vormarsch beginnen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[25793] = { id = 25793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ausufernden Tiefen", description = "Sinn und Zweck dieser Basis war es, im Steinkrallengebirge für Theramore Fuß zu fassen und eine Nachschublinie für die Nachtelfen zu eröffnen. Leider hat die Horde erbitterte Gegenwehr geleistet. Höllschreis Armeen sind mächtig und unnachgiebig. Ich habe so eine Heftigkeit von der Horde seit dem zweiten Krieg nicht erlebt.\n\nJetzt scheint es so, dass die Mine, die die Forscherliga ausgehoben hat, von der Horde dazu benutzt wird, uns zu umgehen. Wir müssen die Mine versiegeln!", sourceObjective = "Sprecht mit Stahlzeh McGee an den Ausufernden Tiefen im Steinkrallengebirge.", completion = "Versiegeln? Das ist ganz schön viel Arbeit, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[25794] = { id = 25794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuflucht unter dem Meer", description = "Ich glaube, ich habe den Verfasser Eurer Notiz gefunden, Freund.\n\nWie es aussieht, braucht er dringend Hilfe, um zu überleben.\n\nIch werde eine meiner Seherkugeln vorbereiten, damit Ihr ihn selbst sehen könnt.", sourceObjective = "Benutzt Erunaks Seherkugel, um die Position der Tiefennebelgrotte zu sehen.", progress = "Habt Ihr Euch die Position der Höhle eingeprägt, {name}?", completion = "Wir müssen uns beeilen!\n\nWie Ihr seht, hat er nicht mehr viel Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25795] = { id = 25795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Schrein", description = "Avianas Ei sollte sicher am Schrein angekommen sein. Geht ruhig und seht es Euch an! Choluna weiß sicher, was zu tun ist.\n\nIch werde unsere Aufgabe hier noch abschließen und stoße dann später zu Euch.", sourceObjective = "Kehrt zu Choluna am Schrein von Aviana auf dem Hyjal zurück.", completion = "{name}! Ist es wahr, dass Ihr einen Angriff gegen einen Zwielichtdrachen geführt habt?\n\nIhr seid wirklich der Herold der Ahnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25796] = { id = 25796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enteignung", description = "Es ist Schicksal, das wir dieses Öl erhalten haben. Dass die Zentauren diesen Ort gewählt haben, als das Meer über uns hereingebrochen ist, ist Pech.\n\nPech für sie, sollte ich sagen.\n\nSie haben uns ins Gesicht gespuckt, {name}. Wir haben ihnen ein großzügiges Angebot unterbreitet, und es war ein Fehler, es nicht anzunehmen. Jetzt werden... werdet Ihr ihnen zeigen, worin dieser Fehler lag.\n\nVertreibt die Zentauren von den Spalthufanhöhen. Das Öl muss fließen!", sourceObjective = "Tötet 15 Zentauren der Spalthufanhöhen.", completion = "Das wird ihnen eine Lektion erteilen. Ihr habt die Zentauren so sehr eingeschüchtert, dass wir nur sehr wenig Wachen des Turbodampfers brauchen werden, um das Gebiet zu sichern.\n\nZumindest wird es so sein, nachdem wir mit ihrem angeblichen Anführer, dem Luftelementar, fertig sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[25797] = { id = 25797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enteignung", description = "Es ist Schicksal, das wir dieses Öl erhalten haben. Dass die Zentauren diesen Ort gewählt haben, als das Meer über uns hereingebrochen ist, ist Pech.\n\nPech für sie, sollte ich sagen.\n\nSie haben uns ins Gesicht gespuckt, {name}. Wir haben ihnen ein großzügiges Angebot unterbreitet, und es war ein Fehler, es nicht anzunehmen. Jetzt werden... werdet Ihr ihnen zeigen, worin dieser Fehler lag.\n\nVertreibt die Zentauren von den Spalthufanhöhen. Das Öl muss fließen!", sourceObjective = "Tötet 15 Zentauren der Spalthufanhöhen.", completion = "Das wird ihnen eine Lektion erteilen. Ihr habt die Zentauren so sehr eingeschüchtert, dass wir nur sehr wenig Wachen des Turbodampfers brauchen werden, um das Gebiet zu sichern.\n\nZumindest wird es so sein, nachdem wir mit ihrem angeblichen Anführer, dem Luftelementar, fertig sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[25798] = { id = 25798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigt den Turm!", description = "Ich werde diesen Ort nicht mit leeren Händen verlassen! Ihr etwa?\n\nIch bin mir sicher, dass Ihr Euch gefragt habt, was wohl in der riesigen Kiste ist. Nun, Ihr müsst nicht länger warten. Bringt einen unserer Bohrtürme zu den Öltümpeln, und bohrt nach Öl für uns.\n\nIhr müsst natürlich damit rechnen, dass die Zentauren angreifen werden. Verteidigt den Turm lange genug, um ein oder zwei Fässer füllen zu können.", sourceObjective = "Verteidigt den Ölbohrturm.", completion = "Öl! Schwarzes Gold! Tanaristee!\n\nWir sind reich! Jetzt müssen wir uns nur den übrigen lästigen Zentauren annehmen. Mit dem ganzen Gold, das wir verdienen werden, können wir uns sicher leisten, sie auf irgendeine andere Klippe umzusiedeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[25799] = { id = 25799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigt den Turm!", description = "Ich werde diesen Ort nicht mit leeren Händen verlassen! Ihr etwa?\n\nIch bin mir sicher, dass Ihr Euch gefragt habt, was wohl in der riesigen Kiste ist. Nun, Ihr müsst nicht länger warten. Bringt einen unserer Bohrtürme zu den Öltümpeln, und bohrt nach Öl für uns.\n\nIhr müsst natürlich damit rechnen, dass die Zentauren angreifen werden. Verteidigt den Turm lange genug, um ein oder zwei Fässer füllen zu können.", sourceObjective = "Verteidigt den Ölbohrturm.", completion = "Öl! Schwarzes Gold! Tanaristee!\n\nWir sind reich! Jetzt müssen wir uns nur den übrigen lästigen Zentauren annehmen. Mit dem ganzen Gold, das wir verdienen werden, können wir uns sicher leisten, sie auf irgendeine andere Klippe umzusiedeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[25800] = { id = 25800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn das Leben dir Krabben schenkt...", description = "Es gibt hier viel zu tun, {class}, aber wir dürfen die Augen nicht vor den Geschenken des Schicksals verschließen.\n\nAls die Flut über unsere Häuser hereinbrach, schwemmte sie viele Meeresbewohner an. Die Bucht von Menethil ist jetzt voller großer Krabben, die genau richtig sind, um sie einzusammeln.\n\nWenn das Leben dir Krabben schenkt, geh Krabbenfischen, sag ich immer. Bringt mir die größten und fleischigsten Scheren, die Ihr finden könnt und ich bezahle Euch.", sourceObjective = "Findet 5 fleischige Kriecherklauen von Hafenkriechern.", progress = "Vergesst die kleineren Scheren - das Fleisch ist die viele Arbeit, es aus den Scheren zu holen, nicht wert.", completion = "Ein herzhaftes Meeresfrüchtedinner wird die Stimmung bei allen heben und uns dabei helfen, die Stadt wieder aufzubauen. Danke für die Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25801] = { id = 25801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klauen aus der Tiefe", description = "Murlocs kriechen aus den tiefen Wassern und bauen ihre Dörfer entlang der Küste. Sie überfallen unsere Fischer und Händler und müssen aufgehalten werden.\n\nEiner dieser Murlocs, Gobbler, streift mit den anderen Murlocs der Blaukiemen umher und plündert die Händler entlang der Straße aus, wobei sie sich danach immer in die Sicherheit der nahegelegenen Hütten zurückziehen. Unsere Händler sind in Gefahr und wir sind bereit, für ihre Sicherheit zu zahlen.\n\nGobbler strolcht in der kleinen Bucht nördlich von hier herum. Findet ihn, erschlagt seine Artgenossen und bringt mir seinen Kopf.", sourceObjective = "Holt Euch Gobblers Kopf von Gobbler und tötet 12 beliebige Murlocs der Blaukiemen.", progress = "Unsere Händler werden nicht sicher sein, bis wir Gobbler und diese Murlocs losgeworden sind.", completion = "Ah, gut gemacht, {name}.\n\nBitte nehmt dies als Bezahlung für die Erfüllung Eures Vertrages mit der Handelsmarine.", sourceObjectiveStatus = "unverified-source-field" }
quests[25802] = { id = 25802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waren-Wiederbeschaffung", description = "Vor nicht allzu langer Zeit wurde ein Handelsschiff, die 'Blinde Prinzessin', von Murlocs überfallen. Obwohl das Schiff unversehrt entkam, wurde ein Großteil seiner Fracht von den Kreaturen über Bord gezogen, darunter eine äußerst wertvolle Statuette von Terenas Menethil. Wir möchten, dass die Statuette geborgen wird.\n\nDurchsucht die Hütten der Murlocs an der Küste nach Kisten, Fässern und anderen Spuren von verlorener Fracht. Findet die Statuette von Menethil und bringt sie mir wieder.", sourceObjective = "Durchsucht die Kisten und Fässer in den Murloclagern an der Küste.", completion = "Diese Kiste ist mit klauenartigen Kratzern übersät und zeigt Spuren eines Wasserschadens. Das Aufbrechen enthüllt durchnässtes und verfaultes Stroh, als wäre etwas Wertvolles in dieser Kiste aufbewahrt worden. Ihr durchwühlt das Stroh...\n\n... und findet eine Handvoll rot gefärbter Flaschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25803] = { id = 25803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche geht weiter", description = "Ihr durchsucht gründlich diese Ansammlung von Murlochütten, findet aber keine Spur der Statuette von Menethil.\n\nVielleicht gibt es in einer der beiden nahe gelegenen Hütten im Norden und Nordosten mehr Hinweise.", sourceObjective = "Sucht nach der Statuette von Menethil.", completion = "Dieses Fass ist weitgehend unberührt. Als Ihr es öffnet...\n\n... schlägt Euch der stechende Geruch von Käse entgegen. Er ist etwas feucht, aber immer noch schmackhaft!", sourceObjectiveStatus = "unverified-source-field" }
quests[25804] = { id = 25804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche in weiteren Hütten", description = "Dieses Grüppchen Murlochütten offenbart auch nach einer gründlichen Überprüfung nichts.\n\n... Aber Ihr seid Euch sicher, dass der nächste Anhaltspunkt, den Ihr findet, nützlich sein wird.\n\nEine der Hütten nördlich von hier muss die Statuette von Menethil enthalten!", sourceObjective = "Sucht weiter in den Hütten der Murlocs nach der Statuette von Menethil.", completion = "Dieses Fass ist unter Schlamm und Gras halb begraben...", sourceObjectiveStatus = "unverified-source-field" }
quests[25805] = { id = 25805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückgabe der Statuette", description = "Nachdem Ihr das Fass aus dem Dreck gezogen und geöffnet habt, findet Ihr eine in dünnes Stroh eingepackte, silbrige Figur. Sie stellt einen jungen, langhaarigen Paladin mit erhobenem Hammer dar.\n\nDies kann nur die Statuette von Menethil sein! Ihr müsst sie nun zu Karl Boran in den Hafen von Menethil zurückbringen.", sourceObjective = "Bringt Karl Boran im Hafen von Menethil im Sumpfland die Statuette von Menethil.", sourceObjectiveStatus = "unverified-source-field" }
quests[25806] = { id = 25806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie haben die Assass in... ach, egal", description = "Ah, die Forscherliga - welche glanzvolle Gruppe von Schwachköpfen. Wir haben nicht nur die Geister der Tauren am Hals, die Forscherliga hat es ebenfalls geschafft, eine Hintertür für die Hauptbasis der Horde im Steinkrallengebirge - der Feste Krom'gar - zu öffnen.\n\nJetzt bringen Auftragsmörder von Krom'gar alle in der Mine um, ohne dass man auch nur einen Mucks hört.\n\nIhr müsst da hineingehen und aufräumen.\n\nBeinahe hätte ich vergessen, Euch diese Brille zu geben. Setzt sie sofort auf. Damit werden alle getarnten Assassinen in der Mine sichtbar.", sourceObjective = "Tötet 12 Auftragsmörder von Krom'gar.", sourceObjectiveStatus = "unverified-source-field" }
quests[25807] = { id = 25807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wiedergeburt eines Ahnen", description = "Ich bin davon überzeugt, dass IHR der Herold Avianas seid, {name}. Ihr wart es, der sie zuerst gesehen hat und ihre Essenz aus den Klauen eines Drachen errettete.\n\nJa, ich glaube, dass Aviana in diese Welt wiedergeboren wird. Und Ihr habt die Ehre, sie über die Schwelle zu führen.\n\nNehmt dieses Rauchwerk und verbrennt es vor Avianas Ei im Raum direkt über mir.\n\nDie Ahnin ist nah, {name}. Unsere Errettung steht kurz bevor!", sourceObjective = "Benutzt das Rauchwerk des Herolds vor Avianas Ei im Schrein von Aviana.", completion = "Ich… lebe.\n\nDiejenigen, die versucht haben, mich zu verderben und meine Kinder zu stehlen, werden bald den Hieb meiner Klauen spüren, {class}. Glaubt mir.\n\nDringt weiter auf den Hyjal vor. Ich werde mich sammeln und die anderen Ahnen um mich rufen.", sourceObjectiveStatus = "unverified-source-field" }
